APP_ICONS.book=['#DDA94D','M6 2h4l2 4 2-4h4l-3.4 5.9A6.5 6.5 0 1 1 9.4 7.9zM12 10.5a3.5 3.5 0 1 0 0 7a3.5 3.5 0 1 0 0-7z'];
