  gDorsal(c,-4.4,-2.9,1.4,A,.7);ell(c,3,2.9,o.flip||2.4,.75,o.flip?B:A,.55);if(o.bumps)for(let i=0;i<4;i++)disc(c,8.4+i*.9,-2.4+i*.35,.32,'rgba(255,255,255,.35)');
  gEye(c,7.4,.5,.5);line(c,12.2,.8,6.6,1.3,'rgba(0,0,0,.35)',.35);
