const FAM_LINES={
  start:{deep:["You're far from the shallows, little boat.","Something big just noticed you. It's me.","The deep sent me. The deep is cross."],oddity:["Oh. It's you.","Right. Let's get this over with."],season:["Winter has a face. This is it."]},
  p75:{deep:["That one stung. Do it again and see.","Lucky shot.","Is that all? I've been tickled harder by plankton."],oddity:["Ow. Rude.","I felt that, you know."],season:["Ice cracks. I don't."]},
  p50:{deep:["Half of me is still plenty.","Wait! I have a family! Of 400 eggs!","This was supposed to be a quiet day!"],oddity:["Can we take five?","I'm writing a strongly worded letter."],season:["The cold... is leaving me..."]},
  p25:{deep:["I'll give you treasure! I don't have treasure! I'll give you a nice rock!","Can we talk about this over a nice fish?","I regret nothing. Except this."],oddity:["I'm too weird to die.","This isn't fair. I'm unique."],season:["Spring... is coming..."]},
  dead:{deep:["Tell my clam I loved her.","Bury me at sea. Oh. Right.","I'll be back. Next Thursday. Ish."],oddity:["Well. That was a day.","Fine. Fine! I'm going."],season:["Thaw... ing..."]}
};
NEW_BOSSES.forEach(b=>{const f=k=>{const l=FAM_LINES[k][b.fam]||FAM_LINES[k].deep;return l[h32(b.id+k)%l.length];};b.lines={start:b.sig[0],p75:f('p75'),p50:b.sig[1]||f('p50'),p25:f('p25'),dead:b.sig[2]||f('dead')};});
