[...BOSSES,...RARE_BOSSES].forEach(b=>{const m=OLD_META[b.id];if(m){b.title=m[0];b.weak=m[1];b.bio=m[2];b.fam=b.fam||'classic';}});
const ROSTER=[...BOSSES,...RARE_BOSSES.filter(b=>b.id==='kraken'),...NEW_BOSSES.filter(b=>b.fam!=='season'&&b.id!=='mondaykraken'&&b.id!=='weekendsiren')];
const ALL_BOSSES=Object.fromEntries([...BOSSES,...RARE_BOSSES,...NEW_BOSSES,...(typeof XMAS_BOSSES!=='undefined'?XMAS_BOSSES:[])].map(b=>[b.id,b]));

/* ---------- Boss of the Day rotation (only from 1 December; earlier days keep their boss) ---------- */
{const _bfR=bossFor;bossFor=function(date){const inner=_bfR.apply(this,arguments);if(date<ROSTER_FROM||(typeof XMAS_BOSSES!=='undefined'&&XMAS_BOSSES.includes(inner)))return inner;
  if(h32(date+'rare')%14===0)return RARE_BOSSES[h32(date+'rb')%RARE_BOSSES.length];
  const se=typeof seasonAt==='function'?seasonAt(date):null;if(se&&se.n===1&&h32(date+'season')%7===0)return ALL_BOSSES.icekraken;
  const w=new Date(date+'T12:00:00Z').getUTCDay();if(w===5&&h32(date+'fri')%2===0)return ALL_BOSSES.weekendsiren;if(w===1&&h32(date+'mon')%3===0)return ALL_BOSSES.mondaykraken;
  const m=date.slice(0,7);const order=[...ROSTER].sort((a,b)=>h32(m+a.id)-h32(m+b.id));return order[(+date.slice(8,10)-1)%order.length];};}

/* ---------- weak spots: counted from the day's taps, paid as a bonus once the boss is sunk ---------- */
function weakHits(date,p,boss){boss=boss||(G.days[date]||{}).boss;const W_=boss&&WEAK[boss.weak];if(!W_||boss.weak==='stub')return 0;const evs=G.evs.filter(e=>e.date===date);let n=0,run={};
  evs.forEach((e,i)=>{if(e.k==='d')run[e.pid]=(run[e.pid]||0)+1;const prev=i?evs[i-1]:null;if(e.pid!==p)return;if(W_.test(e,e.k==='d'?run[e.pid]-1:0,prev))n+=W_.w||1;});return n;}
function weakBonus(date,p){const D=G.days[date];if(!D||!D.boss||date<ROSTER_FROM)return null;const won=D.target>0&&D.team>=D.target;const stub=D.boss.weak==='stub';const n=weakHits(date,p,D.boss);
  const g=stub?40:Math.min(80,n*2),xp=stub?60:Math.min(120,n*3);return{won,n,g,xp,stub,key:`wk_${date}`};}
function bossCardExtra(){const D=G.days[G.today];const b=D&&D.boss;if(!b||!b.title)return '';const W_=WEAK[b.weak];const wb=weakBonus(G.today,S.me);const cl=wb&&G.players[S.me].claimed.has(wb.key);
  return `<div class="bossMeta"><small><b>${esc(b.title)}</b>${W_?` \u00b7 <span title="${esc(W_.rule)}">${esc(W_.name)}: ${esc(W_.rule.charAt(0).toLowerCase()+W_.rule.slice(1))}</span>`:''}</small>${wb?`<small class="muted">${wb.stub?'Stubborn: sinking it pays a double bonus.':`Your weak-spot hits today: <b>${wb.n}</b>`}</small>`:''}
    ${wb&&wb.won&&!cl&&(wb.n>0||wb.stub)?`<button class="btn sm primary" data-act="weakClaim">Claim weak-spot bonus: +${wb.g} ${CN}, +${wb.xp} XP</button>`:''}<button class="btn sm ghost" data-act="bossInfo" data-id="${b.id}">Bestiary page</button></div>`;}
ACT.weakClaim=async()=>{const wb=weakBonus(G.today,S.me);if(!wb||!wb.won||G.players[S.me].claimed.has(wb.key))return;try{await writeDay(S.me,G.today,{bonus:{[wb.key]:{xp:wb.xp,g:wb.g,ts:Date.now()}}});SFX.ach();toast(`<b>Weak spot!</b> +${wb.g} ${CN}, +${wb.xp} XP.`);}catch(e){writeFail(e);}};
{const _hR=SCREENS.harbour;SCREENS.harbour=function(){const h=_hR.apply(this,arguments);const x=bossCardExtra();if(!x)return h;const k='<div class="hp"';const i=h.indexOf(k);if(i<0)return h;const j=h.indexOf('</div>',h.indexOf('>',i))+6;return h.slice(0,j)+x+h.slice(j);};}

/* ---------- moods and speech bubbles on the Harbour ---------- */
const MOOD_LINES={
  smug:["Take your time, little boat. The sea is patient. So am I.","I've swallowed bigger ships for breakfast. Smaller ones as mints.","Your cannons tickle. Do it again, it's nice.","Is that all? I've been tickled harder by plankton.","Quiet out here. Lovely. Keep it that way.","Having a nap, are we?","I could get used to this."],
  panic:["How many cannons have you GOT?","That one went through my good fin!","Nobody said the boat would fight back!","Wait! I have a family! Of 400 eggs!","This was supposed to be a quiet day!","Too many! Too fast!","Who taught you to aim like that?"],
  beg:["Can we talk about this over a nice fish?","I'll give you my pearl! It's a pebble, but I'll give you it!","I'll give you treasure! I don't have treasure! I'll give you a nice rock!","Mercy! I have a mortgage on a reef!","Stop! I'll leave! I'll move to a different sea!"],
  sulk:["Fine. I'll just bleed here. Don't worry about me.","No, go home. I'll sink myself. Again.","Off you go then. I'll just lie here and think about what you've done.","Half a boss. Is that what you wanted?"],
  dead:["Tell my clam I loved her.","I regret nothing. Except that ship. And that one.","Bury me at sea. Oh. Right.","I'll be back. Next Thursday. Ish.","Avenge meee... no, don't, it's fine."],
  early:["Before elevenses? In front of the gulls?","Sunk before lunch. My mum's going to hear about this."]
};
function bossMood(){const D=G.days[G.today];if(!D||!D.boss||!D.target)return null;const now=Date.now(),min=L(now).min;const hp=Math.max(0,D.target-D.team),ratio=hp/D.target;
  if(hp<=0)return min<660&&D.team>=D.target?'early':'dead';if(ratio<.1)return 'beg';
  const recent=G.evs.filter(e=>e.date===G.today&&e.k==='d'&&now-e.t<600000).length;if(recent>=10)return 'panic';
  if(min>=1080&&ratio>=.4&&ratio<=.6)return 'sulk';
  const last=G.evs.filter(e=>e.date===G.today&&e.k==='d').slice(-1)[0];if(min>=540&&min<1020&&(!last||now-last.t>1200000))return 'smug';return null;}
const BUB={until:0,next:0,text:''};
function bossSay(force){if(!G)return;const D=G.days[G.today];if(!D||!D.boss)return;const mood=bossMood();const now=Date.now();if(!mood&&!force)return;if(!force&&now<BUB.next)return;
  const b=D.boss;let pool=mood?MOOD_LINES[mood]:[b.lines.start];if(mood&&b.sig&&Math.random()<.3)pool=b.sig;const line=pool[h32(G.today+mood+Math.floor(now/180000))%pool.length];
  BUB.text=line;BUB.until=now+6000;BUB.next=now+180000;try{const q=JSON.parse(localStorage.getItem('hl_quotes')||'{}');if(!q[b.id]||mood==='beg'||mood==='early')q[b.id]=line;localStorage.setItem('hl_quotes',JSON.stringify(q));}catch(e){}}
setInterval(()=>{try{if(S.screen==='harbour'&&PREFS.heckles!==false)bossSay(false);}catch(e){}},60000);
addLayer('world','bossBubble',(c,t)=>{if(Date.now()>BUB.until||!S.target||!BUB.text)return;const x=Math.min(250,S.target.x-10),y=Math.max(14,S.target.y-30);c.font='600 7.8px Fredoka, Nunito, sans-serif';
  const words=BUB.text.split(' ');const lines=[];let cur='';words.forEach(w=>{const tt=cur?cur+' '+w:w;if(c.measureText(tt).width>104){lines.push(cur);cur=w;}else cur=tt;});lines.push(cur);
  const w=Math.max(...lines.map(l=>c.measureText(l).width))+12,h=lines.length*9.6+7;const bx=Math.max(4,x-w+20);rr(c,bx,y-h,w,h,4,'rgba(255,255,255,.95)');poly(c,[[x+4,y],[x+12,y],[x+14,y+6]],'rgba(255,255,255,.95)');
  c.fillStyle='#21313F';c.textAlign='left';c.textBaseline='top';lines.forEach((l,i)=>c.fillText(l,bx+6,y-h+4.5+i*9.6));},{z:30,scenes:['harbour']});

/* ---------- cinematic intro: once a day per captain on the first Harbour view ---------- */
const INTRO_KEY=()=>'hl_intro_'+(G?G.today:'');
function bossIntro(force){try{if(!G||!S.me)return;const D=G.days[G.today];const b=D&&D.boss;if(!b||!D.target)return;if(!force){if(!PREFS.intros||S.focus||localStorage.getItem(INTRO_KEY()))return;
    const last=G.evs.filter(e=>e.pid===S.me).slice(-1)[0];if(last&&Date.now()-last.t<120000)return;if(D.team>=D.target)return;}
  localStorage.setItem(INTRO_KEY(),'1');const ov=document.createElement('div');ov.className='bossIntro'+(THEME.reduced?' still':'');ov.setAttribute('role','dialog');ov.setAttribute('aria-label',`Today's boss: ${b.name}`);
  ov.innerHTML=`<i class="bar t"></i><i class="bar b"></i><canvas width="600" height="400"></canvas><div class="biName"><small>Boss of the Day</small><b>${esc(b.name)}</b>${b.title?`<em>${esc(b.title)}</em>`:''}</div><span class="biSkip">Tap to skip</span>`;
  document.body.appendChild(ov);const cv=ov.querySelector('canvas'),c=cv.getContext('2d');c.setTransform(2,0,0,2,0,0);const t0=performance.now();let raf;
  const draw=()=>{const t=performance.now(),q=Math.min(1,(t-t0)/1200);c.clearRect(0,0,300,200);const ease=1-Math.pow(1-q,3);if(typeof isArtLook==='function'&&isArtLook()&&typeof artIntro==='function'){try{artIntro(c,b,t,ease);}catch(e){}}else{try{drawBoss(c,b,150,200-ease*95,42,1,t,false,b.kit&&b.kit.floats?null:170);}catch(e){}}raf=requestAnimationFrame(draw);};draw();
  if(S.sound){try{tone(70,.5,'sine',.25);setTimeout(()=>tone(55,.6,'sine',.2),180);}catch(e){}}
  const close=()=>{cancelAnimationFrame(raf);ov.classList.add('out');setTimeout(()=>ov.remove(),350);};ov.addEventListener('click',close);setTimeout(close,3400);setTimeout(()=>bossSay(true),3600);}catch(e){console.warn('intro',e);}}
FEATURES.intros=true;
(function introLoop(){let n=0;const iv=setInterval(()=>{n++;try{if(S.screen==='harbour'&&G&&S.me&&$('#modal')&&$('#modal').hidden){bossIntro(false);clearInterval(iv);}else if(n>120)clearInterval(iv);}catch(e){clearInterval(iv);}},2500);})();

/* ---------- Bestiary: a page per boss ---------- */
function bossStats(id,p){const out={sunk:0,first:null,fastest:null,bestDay:0,total:0,days:0};Object.values(G.days).forEach(D=>{if(!D.boss||D.boss.id!==id||!D.target)return;const mine=D.p[p]?.d||0;out.total+=mine;out.bestDay=Math.max(out.bestDay,mine);if(mine>0)out.days++;
  if(D.team>=D.target&&mine>0){out.sunk++;if(!out.first||D.date<out.first)out.first=D.date;const ev=G.evs.filter(e=>e.date===D.date&&e.k==='d');if(ev.length>=D.target){const mins=Math.round((ev[D.target-1].t-ev[0].t)/60000);if(out.fastest==null||mins<out.fastest)out.fastest=mins;}}});return out;}
function bossPageHtml(id){const b=ALL_BOSSES[id];if(!b)return '';const q=(()=>{try{return JSON.parse(localStorage.getItem('hl_quotes')||'{}')[id];}catch(e){return null;}})();const W_=WEAK[b.weak];
  const cols=G.P.map(p=>[p,bossStats(id,p)]);const row=(lab,f)=>`<tr><th>${lab}</th>${cols.map(([p,s])=>`<td>${f(s)}</td>`).join('')}</tr>`;
  return `<div class="bossPage"><canvas class="bpArt" width="480" height="300" data-boss="${id}"></canvas><h2>${esc(b.name)}</h2>${b.title?`<p class="muted" style="margin:-4px 0 8px">${esc(b.title)}</p>`:''}
    ${W_?`<p><b>Weak spot:</b> ${esc(W_.name)}. ${esc(W_.rule)}.</p>`:''}${b.bio?`<p class="tiny">${esc(b.bio)}</p>`:''}${q?`<blockquote class="bpQuote">"${esc(q)}"</blockquote>`:''}
    <table class="bpStats"><tr><th></th>${cols.map(([p])=>`<th>${esc(pname(p))}</th>`).join('')}</tr>${row('Times sunk',s=>s.sunk)}${row('First sunk',s=>s.first?shortDate(s.first):'\u2013')}${row('Fastest kill',s=>s.fastest!=null?s.fastest+' min':'\u2013')}${row('Most DMs in a day',s=>s.bestDay)}${row('Total hits',s=>fmtN(s.total))}</table>
    <div class="row" style="justify-content:flex-end;margin-top:10px"><button class="btn primary" data-act="wnClose">Close</button></div></div>`;}
ACT.bossInfo=d=>{openModal(bossPageHtml(d.id));setTimeout(()=>{const cv=document.querySelector('#modal canvas[data-boss]');if(!cv)return;const c=cv.getContext('2d');const b=ALL_BOSSES[d.id];let raf;const go=()=>{if(!document.body.contains(cv))return cancelAnimationFrame(raf);const t=performance.now();c.setTransform(2,0,0,2,0,0);c.clearRect(0,0,240,150);if(typeof isArtLook==='function'&&isArtLook()&&typeof artBestiary==='function'){try{artBestiary(c,b,t);}catch(e){}}else{const g=c.createLinearGradient(0,0,0,150);g.addColorStop(0,'#BFE4F2');g.addColorStop(1,'#5BA9CC');c.fillStyle=g;c.fillRect(0,0,240,150);try{drawBoss(c,b,120,92,30,1,t,false,b.kit&&b.kit.floats?null:118);}catch(e){}}raf=requestAnimationFrame(go);};go();},30);};
function rosterHtml(){const seen=new Set(Object.values(G.days).filter(D=>D.boss&&D.date<=G.today).map(D=>D.boss.id));const list=[...ROSTER,ALL_BOSSES.mondaykraken,ALL_BOSSES.weekendsiren,ALL_BOSSES.icekraken,...RARE_BOSSES.filter(b=>b.id==='aurora'),...(typeof XMAS_BOSSES!=='undefined'?XMAS_BOSSES:[])];
  return `<div class="card"><h3>Bosses <small class="muted">${list.filter(b=>seen.has(b.id)).length} of ${list.length} met</small></h3><p class="tiny muted">Every boss of the day, with its weak spot, biography and your record against it. New ones join the rotation from 1 December.</p>
   <div class="bossGrid">${list.map(b=>`<button class="bossTile ${seen.has(b.id)?'':'unseen'}" data-act="bossInfo" data-id="${b.id}"><canvas width="160" height="120" data-bossicon="${b.id}"></canvas><b>${seen.has(b.id)?esc(b.name):'???'}</b></button>`).join('')}</div></div>`;}
{const _bst=SCREENS.bestiary;SCREENS.bestiary=function(){const h=_bst.apply(this,arguments);const k='<div class="card">';const i=h.indexOf(k);return i<0?h+rosterHtml():h.slice(0,i)+rosterHtml()+h.slice(i);};}
{const _rd=render;render=function(){_rd.apply(this,arguments);try{document.querySelectorAll('canvas[data-bossicon]').forEach(cv=>{const b=ALL_BOSSES[cv.dataset.bossicon];if(!b)return;const c=cv.getContext('2d');c.setTransform(2,0,0,2,0,0);c.clearRect(0,0,80,60);c.fillStyle='#DCEFF7';c.fillRect(0,0,80,60);
  if(cv.closest('.unseen')){c.globalAlpha=.25;}try{drawBoss(c,b,40,34,15,1,1000,false,b.kit&&b.kit.floats?null:48);}catch(e){}c.globalAlpha=1;});}catch(e){}};}
HELP.push(['Boss of the Day','From 1 December the daily boss comes from a roster of 36, each with a title, a weak spot and a Bestiary page. Hit its weak spot (early DMs, follow-ups, responses, afternoon DMs and so on, printed on the Today card) and once it\'s sunk you can claim a weak-spot bonus. HP is still the crew target and every DM is still one hit. Bosses talk back now, depending on how the day is going, and the first time you open the Harbour each day the boss gets a short intro (turn it off in Settings, Game feel). Tap "Bestiary page" for its biography and your record against it.']);

/* ============================== LOOT, TROPHIES AND LEGENDS (Stage 3) ==============================
   Loot sets: from 1 December every boss you help sink drops one piece of its 4-piece set (both of you
   roll; Stubborn bosses drop two). Complete a set for its banner. Five duplicates of a piece trade at
   Pell's for a missing one. Trophies: a mounted head per boss, bronze at 1 kill, silver 10, gold 50,
   diamond 200, with one-off rewards to claim. Legendary hunts: a giant raid boss on set days, 1.4 times
   the crew target, announced the day before. Ship damage: looks only, from the last few working days. */
const PIECE_T={crab:['Claw Tip','Shell Shard','Barnacle Crown','Golden Pincer'],fish:['Scale','Fin','Tooth','Golden Scale'],squid:['Ink Sac','Sucker','Beak','Pearl of the Deep'],kraken:['Ink Sac','Sucker','Beak','Pearl of the Deep'],octopus:['Ink Sac','Sucker','Beak','Pearl of the Deep'],
  eel:['Scale','Fang','Spine','Golden Coil'],serpent:['Scale','Fang','Spine','Golden Coil'],jelly:['Tendril','Glow Drop','Bell Shard','Moon Pearl'],puffer:['Spine','Puff','Grumpy Face','Golden Spine'],shell:['Shell Chip','Pincer','Spiral','Perfect Shell'],
  ray:['Wing Tip','Barb','Shadow Scale','Night Pearl'],blob:['Whisker','Slime','Tooth','Strange Pearl'],storm:['Raindrop','Thundercloud','Lightning Bolt','Bottled Storm'],ship:['Rusty Cannonball','Torn Flag',"Captain's Log",'Golden Wheel'],whale:['Barnacle','Song','Spout','Golden Ambergris']};
const PIECE_RAR=['common','uncommon','rare','legendary'],SET_SYM={crab:'anchor',fish:'fish',squid:'kraken',kraken:'kraken',octopus:'kraken',eel:'fin',serpent:'fin',jelly:'diamond',puffer:'star',shell:'heart',ray:'fin',blob:'skull',storm:'diamond',ship:'swords',whale:'fish'};
const bodyOf=b=>(b.kit&&b.kit.body)||b.type||'blob';const shortName=b=>b.name.replace(/^The /,'').replace(/,.*$/,'');
function setOf(b){const t=PIECE_T[bodyOf(b)]||PIECE_T.blob;return t.map((n,i)=>({id:`lp_${b.id}_${i}`,name:`${shortName(b)}'s ${n}`,rar:PIECE_RAR[i],i,boss:b.id}));}

/* ---------- legendary hunts ---------- */
const LEGENDS=[
  {date:'2026-12-18',id:'krampus',name:'The Krampus Kraken',title:'Keeper of the Naughty List',type:'kraken',col:'#7A2A3A',eye:'#3F3A30',legend:true,kit:{body:'squid',col:'#7A2A3A',eyes:3,eyeStyle:'angry',mouth:'fangs',acc:['antlers','tentacles','chains']},lines:{start:"You've been VERY slow this year.",p75:"I've got a list. You're on it. Twice.",p50:'Coal for everyone! Except Bryn\'s Mum. I\'m scared of Bryn\'s Mum.',p25:'Wait... this is very festive of you...',dead:'Merry Christmas. You\'re off the list. For now.'},bio:'Enjoys: lists, checking them twice, coal. Dislikes: good behaviour. Last seen: up a chimney.',trophy:"the Krampus Kraken's Sack"},
  {date:'2027-01-13',id:'leviathan',name:'The Leviathan',title:'Older Than Ships',type:'whale',col:'#3A5A7A',eye:'#3F3A30',legend:true,kit:{body:'fish',col:'#3A5A7A',col2:'#9FB8CC',pat:'scales',eyes:2,eyeStyle:'angry',mouth:'fangs',acc:['fins','barnacles','scars','spikes']},lines:{start:'I am older than your ship. I am older than ships.',p75:'A scratch. I have had worse from a reef.',p50:'You... are persistent.',p25:'The deep is calling me home...',dead:'Remember me when the tide turns.'},bio:'Enjoys: the abyss, centuries. Dislikes: being disturbed. Last seen: 1702.',trophy:"the Leviathan's skeleton"},
  {date:'2027-02-10',id:'krakenqueen',name:'The Kraken Queen',title:'Mother Of All Tentacles',type:'kraken',col:'#8A4AB8',eye:'#3F3A30',legend:true,kit:{body:'squid',col:'#8A4AB8',eyes:2,eyeStyle:'angry',mouth:'beak',acc:['crown','tentacles']},lines:{start:'You sank my son. He was a disappointment, but still.',p75:'How dare you. I am royalty.',p50:'Guards! Guards? Oh. I ate the guards.',p25:'This is treason.',dead:'Long live... the queen... ugh.'},bio:'Enjoys: crowns, ruling, revenge. Dislikes: republicans, calamari. Last seen: on her throne of shipwrecks.',trophy:"the Kraken Queen's crown"}
];
const LEGEND_BY_DATE=Object.fromEntries(LEGENDS.map(l=>[l.date,l]));LEGENDS.forEach(l=>{ALL_BOSSES[l.id]=l;});
{const _bfL=bossFor;bossFor=function(date){return LEGEND_BY_DATE[date]||_bfL.apply(this,arguments);};}
function legendToday(){return G&&LEGEND_BY_DATE[G.today];}
function legendTomorrow(){if(!G)return null;let d=addDays(G.today,1);for(let i=0;i<4;i++){if(LEGEND_BY_DATE[d])return i===0?LEGEND_BY_DATE[d]:null;if(isWork(d))return null;d=addDays(d,1);}return null;}
function legendState(date){const L_=LEGEND_BY_DATE[date],D=G.days[date];if(!L_||!D||!D.target)return null;const hp=Math.ceil(D.target*1.4);return{L:L_,hp,team:D.team,won:D.team>=hp,key:`lg_${L_.id}_${date}`};}

/* ---------- loot, worked out from the days ---------- */
function bossLoot(p){if(!G)return{have:{},sets:{}};const ck=p+'|'+G.evs.length+'|'+G.today+'|'+((G.players[p]||{}).bonus||[]).length;if(bossLoot._c&&bossLoot._c.k===ck)return bossLoot._c.v;const have={};const add=(id,n=1)=>{have[id]=(have[id]||0)+n;};
  Object.values(G.days).forEach(D=>{if(!D.boss||D.date<ROSTER_FROM||!D.target||!(D.p[p]?.d>0))return;const L_=LEGEND_BY_DATE[D.date];const set=setOf(D.boss);
    if(L_){const st=legendState(D.date);if(st&&st.won)add(set[3].id);return;}if(D.team<D.target)return;
    const rolls=D.boss.weak==='stub'?2:1;for(let r=0;r<rolls;r++){const u=h32(D.date+p+'loot'+r)%100;add(set[u<55?0:u<85?1:u<97?2:3].id);}});
  (G.players[p]?.bonus||[]).forEach(b=>{if(b.key.startsWith('lt_')&&b.take&&b.give){add(b.take,-(b.n||5));add(b.give,1);}else if(b.key.startsWith('fn_')&&b.take){add(b.take,-(b.n||1));}});
  const v={have};bossLoot._c={k:ck,v};return v;}
function setDone(p,b){const {have}=bossLoot(p);return setOf(b).every(x=>(have[x.id]||0)>0||G.players[p]?.bonus?.some(y=>y.give===x.id));}
// set banners: one per boss, earned by completing its set, hidden from the shop until owned
const SET_FLAGS={};Object.values(ALL_BOSSES).forEach(b=>{const id=`flag_set_${b.id}`;const it={id,name:`${shortName(b)} Banner`,cat:'flag',col:b.col||'#5C6A80',sym:SET_SYM[bodyOf(b)]||'skull',sc:'#FFFFFF',earn:[`set_${b.id}`,4,`Complete the ${shortName(b)} loot set`,'pieces'],setBanner:true};SET_FLAGS[b.id]=id;if(!ALL_ITEMS[id]){ITEMS.push(it);ALL_ITEMS[id]=it;}});
const _deriveLoot=derive;derive=function(){const g=_deriveLoot.apply(this,arguments);try{const prev=G;G=g;g.P.forEach(p=>{const pl=g.players[p];if(!pl)return;const {have}=bossLoot(p);
  Object.values(ALL_BOSSES).forEach(b=>{const id=SET_FLAGS[b.id];const n=setOf(b).filter(x=>(have[x.id]||0)>0).length;if(pl.earnP)pl.earnP[id]=n;if(n>=4)pl.owned[id]=pl.owned[id]||1;});
  LEGENDS.forEach(L_=>{if(pl.claimed.has(`lg_${L_.id}_${L_.date}`))pl.legendTrophies=(pl.legendTrophies||[]).concat(L_.id);});});G=prev;}catch(e){console.warn('loot derive',e);}return g;};
{const _shopL=SCREENS.shop;SCREENS.shop=function(){const me=G&&G.players[S.me];const keep=ITEMS.slice();const hide=new Set(keep.filter(i=>i.setBanner&&!(me&&me.owned[i.id])).map(i=>i.id));if(!hide.size)return _shopL.apply(this,arguments);
  ITEMS.length=0;keep.forEach(i=>{if(!hide.has(i.id))ITEMS.push(i);});try{return _shopL.apply(this,arguments);}finally{ITEMS.length=0;keep.forEach(i=>ITEMS.push(i));}};}

/* ---------- loot on the boss page, with Pell's 5-for-1 trade ---------- */
function lootHtml(id){const b=ALL_BOSSES[id];if(!b)return '';const {have}=bossLoot(S.me);const set=setOf(b);const done=set.every(x=>(have[x.id]||0)>0);const missing=set.filter(x=>!(have[x.id]>0));
  return `<h3 style="margin-top:12px">Loot set ${done?'<small class="okTag">complete</small>':''}</h3><div class="lootSet">${set.map(x=>{const n=have[x.id]||0;return `<div class="lootPc r-${x.rar} ${n?'':'none'}"><canvas width="96" height="96" data-piece="${x.id}"></canvas><b>${esc(x.name)}</b><small>${x.rar}${n>1?` \u00b7 \u00d7${n}`:''}</small>${n>=6&&missing.length?`<button class="btn sm ghost" data-act="lootTrade" data-id="${x.id}">Trade 5 at Pell's</button>`:''}</div>`;}).join('')}</div>
    <p class="tiny muted">From 1 December, every time ${esc(shortName(b))} is sunk on a day you sent at least one DM, you get a piece (Stubborn bosses drop two). Complete the set for the <b>${esc(ALL_ITEMS[SET_FLAGS[b.id]].name)}</b>. Pell swaps 5 duplicates for a missing piece.</p>`;}
ACT.lootTrade=async d=>{const pc=d.id;const bid=pc.split('_').slice(1,-1).join('_');const b=ALL_BOSSES[bid];const set=setOf(b);const {have}=bossLoot(S.me);if((have[pc]||0)<6)return;const i=+pc.split('_').pop();
  const miss=set.filter(x=>!(have[x.id]>0));if(!miss.length)return toast('<b>Set complete.</b> Pell has nothing you need.');const give=(miss.find(x=>x.i>i)||miss[0]);
  try{await writeDay(S.me,G.today,{bonus:{[`lt_${uid()}`]:{xp:0,g:0,take:pc,give:give.id,n:5,ts:Date.now()}}});SFX.ach();toast(`<b>Pell trades!</b> 5 \u00d7 ${esc(set[i].name)} for ${esc(give.name)}. "Pleasure doing business. Mostly."`);setTimeout(()=>ACT.bossInfo({id:bid}),300);}catch(e){writeFail(e);}};
function drawPiece(cv,id){const [_,...rest]=id.split('_');const i=+rest.pop();const bid=rest.join('_');const b=ALL_BOSSES[bid];if(!b)return;const c=cv.getContext('2d');c.setTransform(cv.width/48,0,0,cv.width/48,0,0);c.clearRect(0,0,48,48);
  const cols={0:'#C9BFA8',1:'#7CC7A6',2:'#7CB0E6',3:'#F2C462'};disc(c,24,24,21,cols[i]);disc(c,24,24,18,'#FFFFFF');c.save();c.beginPath();c.arc(24,24,18,0,TAU);c.clip();try{drawBoss(c,b,24,30,11,1,1000,false,null);}catch(e){}c.restore();
  if(i===3){c.strokeStyle='#F2C462';c.lineWidth=2;c.beginPath();c.arc(24,24,20,0,TAU);c.stroke();}}
{const _bpL=bossPageHtml;bossPageHtml=function(id){const h=_bpL.apply(this,arguments);const k='<div class="row" style="justify-content:flex-end;margin-top:10px">';return h.replace(k,lootHtml(id)+k);};}
{const _biL=ACT.bossInfo;ACT.bossInfo=d=>{_biL(d);setTimeout(()=>document.querySelectorAll('#modal canvas[data-piece]').forEach(cv=>drawPiece(cv,cv.dataset.piece)),60);};}

/* ---------- the Trophy Room ---------- */
const TR_TIERS=[[1,'bronze','#C98A4A'],[10,'silver','#AEB8C2'],[50,'gold','#F2C462'],[200,'diamond','#9FE8F2']];const TR_PAY={silver:{xp:100,g:0},gold:{xp:300,g:100},diamond:{xp:1000,g:300}};
function trophyTier(n){let t=null;TR_TIERS.forEach(x=>{if(n>=x[0])t=x;});return t;}
function trophies(p){return Object.values(ALL_BOSSES).filter(b=>!b.legend).map(b=>{const s=bossStats(b.id,p);return{b,n:s.sunk,t:trophyTier(s.sunk)};}).filter(x=>x.t);}
function trophyClaims(p){const me=G.players[p];const out=[];trophies(p).forEach(x=>{TR_TIERS.forEach(([n,name])=>{if(x.n>=n&&TR_PAY[name]){const key=`tr_${x.b.id}_${name}`;if(!me.claimed.has(key))out.push({key,...TR_PAY[name],b:x.b,name});}});});return out;}
function trophyRoomHtml(){const p=S.me;const list=trophies(p).sort((a,b)=>b.n-a.n);const leg=LEGENDS.filter(L_=>G.players[p].claimed.has(`lg_${L_.id}_${L_.date}`));const cl=trophyClaims(p);
  return `<div class="card trophyRoom"><h3>Trophy Room <small class="muted">${list.length} mounted${leg.length?` \u00b7 ${leg.length} legendary`:''}</small></h3><p class="tiny muted">A mounted head for every boss you've helped sink: bronze at 1, silver at 10, gold at 50, diamond at 200. Upgrades pay out once.</p>
    ${cl.length?`<button class="btn primary" style="width:100%;margin:6px 0" data-act="trClaim">Claim ${cl.length} trophy reward${cl.length===1?'':'s'}</button>`:''}
    ${list.length||leg.length?`<div class="trGrid">${leg.map(L_=>`<div class="trPl legend"><canvas width="120" height="120" data-trophy="${L_.id}" data-tier="legend"></canvas><b>${esc(L_.trophy)}</b><small>Legendary</small></div>`).join('')}${list.map(x=>`<div class="trPl ${x.t[1]}"><canvas width="120" height="120" data-trophy="${x.b.id}" data-tier="${x.t[1]}"></canvas><b>${esc(shortName(x.b))}</b><small>${x.t[1]} \u00b7 ${x.n} sunk</small></div>`).join('')}</div>`:'<p class="muted">No trophies yet. Sink a boss of the day.</p>'}</div>`;}
ACT.trClaim=async()=>{const cl=trophyClaims(S.me);if(!cl.length)return;const bonus={};let xp=0,g=0;cl.forEach(x=>{bonus[x.key]={xp:x.xp,g:x.g,ts:Date.now()};xp+=x.xp;g+=x.g;});try{await writeDay(S.me,G.today,{bonus});SFX.ach();toast(`<b>Trophies polished!</b> +${fmtN(xp)} XP${g?`, +${fmtN(g)} ${CN}`:''}.`);}catch(e){writeFail(e);}};
// 21 Nov: a proper mounted trophy: an oval wooden plaque with a tier-coloured rim, the boss's head and shoulders
// coming out of it on a wooden collar, and a small brass name plate
function drawTrophy(cv,id,tier){const c=cv.getContext('2d');c.setTransform(cv.width/60,0,0,cv.width/60,0,0);c.clearRect(0,0,60,60);const col=tier==='legend'?'#B03A4A':(TR_TIERS.find(x=>x[1]===tier)||[0,0,'#C98A4A'])[2];
  ell(c,31,55,17,2.6,'rgba(0,0,0,.12)');
  const wd=c.createLinearGradient(0,6,0,52);wd.addColorStop(0,'#A8744A');wd.addColorStop(1,'#6A4428');c.fillStyle=wd;c.beginPath();c.ellipse(30,29,21,23,0,0,TAU);c.fill();
  c.save();c.beginPath();c.ellipse(30,29,21,23,0,0,TAU);c.clip();c.strokeStyle='rgba(60,34,18,.25)';c.lineWidth=.5;for(let k=0;k<6;k++){c.beginPath();c.moveTo(12,12+k*6.5);c.quadraticCurveTo(30,9+k*6.5+(k%2?2:-2),48,12+k*6.5);c.stroke();}c.restore();
  c.strokeStyle=col;c.lineWidth=2.4;c.beginPath();c.ellipse(30,29,20,22,0,0,TAU);c.stroke();c.strokeStyle='rgba(255,255,255,.45)';c.lineWidth=.7;c.beginPath();c.ellipse(30,29,20,22,0,Math.PI*1.1,Math.PI*1.6);c.stroke();
  const b=ALL_BOSSES[id]||LEGENDS.find(l=>l.id===id);
  c.save();c.beginPath();c.ellipse(30,29,19,21,0,0,TAU);c.rect(13,0,34,29);c.clip();c.beginPath();c.rect(0,0,60,40.6);c.clip();c.shadowColor='rgba(40,20,10,.35)';c.shadowBlur=3;c.shadowOffsetY=1.2;
  try{if(b){const big=b.type==='ship'?14:b.type==='storm'?12:15;const sx=b.type==='serpent'&&!b.kit?30-big*.55:30;drawBoss(c,b,sx,b.type==='storm'?26:b.type==='serpent'?34:30,big,1,1000,false,null);}}catch(e){}c.restore();
  const cw=c.createLinearGradient(0,38,0,45);cw.addColorStop(0,'#8A5A36');cw.addColorStop(1,'#5A3820');c.fillStyle=cw;c.beginPath();c.ellipse(30,41.6,12.5,3.4,0,0,TAU);c.fill();c.fillStyle='rgba(255,255,255,.18)';c.beginPath();c.ellipse(30,40.8,10,1.2,0,0,TAU);c.fill();
  rr(c,21,46,18,4.6,1.4,col);rr(c,21,46,18,1.6,1,'rgba(255,255,255,.35)');disc(c,22.6,48.3,.5,'rgba(0,0,0,.3)');disc(c,37.4,48.3,.5,'rgba(0,0,0,.3)');
  if(tier==='diamond'||tier==='legend'){const tm=performance.now();for(let i=0;i<4;i++){const a=.5+.5*Math.sin(tm/400+i*1.7);c.fillStyle=`rgba(255,255,255,${.4+.5*a})`;c.beginPath();const x=14+i*10.5,y=12+(i%2)*5;c.moveTo(x,y-2);c.lineTo(x+.8,y);c.lineTo(x,y+2);c.lineTo(x-.8,y);c.closePath();c.fill();}}}
{const _bk=SCREENS.book;if(_bk)SCREENS.book=function(){const h=_bk.apply(this,arguments);const k='<div class="card';const i=h.indexOf(k);return i<0?h+trophyRoomHtml():h.slice(0,i)+trophyRoomHtml()+h.slice(i);};}
{const _rdL=render;render=function(){_rdL.apply(this,arguments);try{document.querySelectorAll('canvas[data-trophy]').forEach(cv=>drawTrophy(cv,cv.dataset.trophy,cv.dataset.tier));}catch(e){}};}

/* ---------- legendary hunt cards, the eve, and the Herald ---------- */
function legendCardHtml(){const st=legendToday()&&legendState(G.today);if(st){const pct=Math.min(100,st.team/st.hp*100);const cl=G.players[S.me].claimed.has(st.key);
    return `<div class="card legendCard"><small>Legendary hunt \u00b7 today only</small><h3>${esc(st.L.name)}</h3><p class="tiny">${esc(st.L.title)}. HP is 1.4 times the crew target: ${st.hp} DMs. Every DM either of you sends today hits it.</p><div class="miniBar big"><i style="width:${pct}%"></i></div><small class="muted">${st.team} / ${st.hp}</small>
      ${st.won&&!cl?`<button class="btn primary" style="width:100%;margin-top:8px" data-act="legendClaim">Claim: ${esc(st.L.trophy)}, its legendary piece, +600 XP, +200 ${CN}</button>`:st.won?'<small class="okTag">Sunk! Trophy mounted.</small>':''}</div>`;}
  const tm=legendTomorrow();if(tm)return `<div class="card legendEve"><small>Herald warning</small><h3>${esc(tm.name)} approaches</h3><p class="tiny">Tomorrow is a legendary hunt: ${esc(tm.title)}. It has 1.4 times the usual HP, so it'll take a big day from both of you. Fishermen are advised to stay indoors, or at least send more DMs.</p></div>`;return '';}
ACT.legendClaim=async()=>{const st=legendState(G.today);if(!st||!st.won||G.players[S.me].claimed.has(st.key))return;try{await writeDay(S.me,G.today,{bonus:{[st.key]:{xp:600,g:200,ts:Date.now()}}});SFX.ach();toast(`<b>LEGENDARY!</b> ${esc(st.L.name)} is sunk. ${esc(st.L.trophy)} is on your wall.`);}catch(e){writeFail(e);}};
{const _hL=SCREENS.harbour;SCREENS.harbour=function(){const h=_hL.apply(this,arguments);const x=legendCardHtml();if(!x)return h;const k='<div class="card today">';return h.includes(k)?h.replace(k,x+k):h+x;};}
addLayer('sky','legendEve',(c,t)=>{c.fillStyle='rgba(30,10,50,.22)';c.fillRect(-80,-300,W+160,420);},{z:10,when:()=>THEME.scene==='harbour'&&!!(legendTomorrow()||legendToday())});
{const _hrL=SCREENS.herald;SCREENS.herald=function(){let h=_hrL.apply(this,arguments);const tm=legendTomorrow();const yd=addDays(G.today,-1);const ys=LEGEND_BY_DATE[yd]&&legendState(yd);let x='';
  if(tm)x+=`<div class="hXmas legendNote"><h4>${esc(tm.name.toUpperCase())} APPROACHES</h4><p>Fishermen advised to stay indoors, or at least send more DMs. Tomorrow's legendary hunt needs 1.4 times the usual crew target.</p></div>`;
  if(ys)x+=`<div class="hXmas legendNote"><h4>${ys.won?'SPECIAL EDITION: '+esc(ys.L.name.toUpperCase())+' SUNK':esc(ys.L.name.toUpperCase())+' ESCAPES'}</h4><p>${ys.won?`The crew landed ${ys.team} DMs and sent ${esc(ys.L.name)} back to the deep. ${esc(ys.L.trophy)} now hangs in the Trophy Room.`:`${esc(ys.L.name)} slipped away at ${ys.team} of ${ys.hp}. Its parting words: "${esc(ys.L.lines.start)}" It may return next month.`}</p></div>`;
  if(!x)return h;const k='<div class="head">';return h.includes(k)?h.replace(k,x+k):h+x;};}

/* ---------- ship damage: looks only, from the last few working days ---------- */
function shipDamage(){if(!G)return{lvl:0,shine:false};const ck=G.today+'|'+G.evs.length;if(shipDamage._c&&shipDamage._c.k===ck)return shipDamage._c.v;let lvl=0,shine=false;const days=[];let d=addDays(G.today,-1);
  for(let i=0;i<20&&days.length<8;i++){if(isWork(d)&&G.days[d]&&G.days[d].target>0)days.unshift(d);d=addDays(d,-1);}
  days.forEach(x=>{const D=G.days[x];if(D.team>=D.target*1.5){lvl=0;shine=x===days[days.length-1];}else if(D.team>=D.target)lvl=Math.max(0,lvl-1);else lvl=Math.min(3,lvl+1);});
  const T=G.days[G.today];if(T&&T.target>0&&T.team>=T.target){if(T.team>=T.target*1.5){lvl=0;shine=true;}else lvl=Math.max(0,lvl-1);}
  const v={lvl,shine};shipDamage._c={k:ck,v};return v;}
{const _dsD=drawShip;drawShip=function(c,x,y,s,pl,t,opts={}){_dsD.apply(this,arguments);if(!G||!opts.pid)return;const {lvl,shine}=shipDamage();if(!lvl&&!shine)return;const ph=opts.phase||0;const fire=opts.firing>0?opts.firing:0,kick=fire*fire;
  const rock=Math.sin(t/900+ph)*.04+Math.sin(t/410+ph*2)*.012-kick*.045,bob=Math.sin(t/650+ph)*1.3+Math.sin(t/270+ph)*.3;c.save();c.translate(x-kick*2.2*s,y+bob*s*.4);c.rotate(rock);c.scale(s,s);
  try{if(lvl>=1){rr(c,-8,-33,6,5,.6,'#E8DCC0');line(c,-8,-33,-2,-28,'rgba(120,90,60,.5)',.3);line(c,-8,-28,-2,-33,'rgba(120,90,60,.5)',.3);rr(c,-24,-30,4,4,.5,'#D9C9A4');c.save();c.translate(10,-10);c.rotate(.18);R(c,-6,-.5,12,1.4,'rgba(90,60,40,.6)');c.restore();}
    if(lvl>=2){ell(c,14,-6,3.4,2.4,'#1E1A16');for(let i=0;i<3;i++){const q=((t/700)+i/3)%1;disc(c,17+q*5,-6+q*q*10,.7*(1-q)+.3,'rgba(160,210,240,.8)');}rr(c,-14,-21,3.4,3.6,.8,'#8A939C');R(c,-14.4,-21.6,4.2,.8,'#6E7780');}
    if(lvl>=3){for(let i=0;i<5;i++){const q=((t/1500)+i/5)%1;c.globalAlpha=.55*(1-q);disc(c,-6+Math.sin(q*6+i)*3,-20-q*30,2+q*4,'#8A8A8A');}c.globalAlpha=1;
      const cx=3,cy=-17;ell(c,cx,cy,2.4,1.6,'#E0704A');line(c,cx-1,cy-1,cx-1.6,cy-6,'#E0704A',.8);line(c,cx+1,cy-1,cx+1.6,cy-6,'#E0704A',.8);disc(c,cx-.7,cy-.8,.35,'#1E1A16');disc(c,cx+.7,cy-.8,.35,'#1E1A16');}
    if(shine)for(let i=0;i<6;i++){const q=(t/900+i*.37)%1;const a=Math.sin(q*Math.PI);c.globalAlpha=a;c.fillStyle='#FFFFFF';const sx=-28+i*11,sy=-8+(i%2)*4;c.beginPath();c.moveTo(sx,sy-1.6);c.lineTo(sx+.5,sy);c.lineTo(sx,sy+1.6);c.lineTo(sx-.5,sy);c.closePath();c.fill();}c.globalAlpha=1;}catch(e){}c.restore();};}
// Gary notices repairs
(function repairWatch(){setInterval(()=>{try{if(!G||!S.me)return;const v=shipDamage();const k='hl_dmg';const prev=+(localStorage.getItem(k)??v.lvl);if(v.lvl<prev)toast(PREFS.heckles!==false?'<b>Repairs done.</b> Gary: "Finally."':'<b>Repairs done.</b>');localStorage.setItem(k,String(v.lvl));}catch(e){}},20000);})();
HELP.push(['Loot sets and trophies','From 1 December, every boss of the day you help sink (send at least one DM that day) drops a piece of its 4-piece loot set: common, uncommon, rare or legendary. Complete a set for that boss\'s banner. Pell will trade 5 duplicates of a piece for a missing one (on the boss\'s Bestiary page). Every boss you sink also earns a mounted head in the Trophy Room (in Achievements): bronze at 1 kill, silver at 10, gold at 50, diamond at 200, with a one-off reward for each upgrade.']);
HELP.push(['Legendary hunts','A few times a season a legendary boss replaces the boss of the day: the Krampus Kraken on Friday 18 December, the Leviathan in January and the Kraken Queen in February. It has 1.4 times the crew target in HP and every DM that day hits it. The Herald and the Today card warn you the day before. Sink it for a unique trophy, its legendary loot piece, 600 XP and 200 doubloons each.']);
HELP.push(['Ship damage','Your ships show how the last few working days went, as looks only: a patched sail after a missed target, a hole and a bailing bucket after two, smoke and a crab holding up the mast after three. Every target day repairs a level, and a 150% day fixes everything and gives the hull a shine. It never costs anything.']);

/* ============================== GARY THE GULL, FULL CHARACTER (Stage 4) ==============================
   Gary's lines live in the content file (lines.gary). He comments on the day as it happens, can be poked,
   pinches one doubloon on a missed-target day (from GARY_FROM) and gives them all back on the next target day,
   files a complaint once a week, keeps a nest on the Funnal Cove lighthouse and runs a Lost and Found. */
const GARY_FROM='2026-11-23';
const GL=()=>((CT().lines||{}).gary)||{};
function garyVars(extra){const D=G&&G.days[G.today]||{};const o=G?other(S.me):'';
  return Object.assign({me:C().players[S.me]?.name||'Captain',other:C().players[o]?.name||'the other captain',boss:(D.boss&&D.boss.name)||'the boss',target:D.target||0,team:D.team||0,left:Math.max(0,(D.target||0)-(D.team||0)),mins:Math.max(0,hm(G.cfg.dayEnd)-L().min)},extra||{});}
function garyLine(cat,seed,extra){const l=GL()[cat];if(!l||!l.length)return '';return fill(l[h32(String(seed))%l.length],garyVars(extra));}

/* ---------- what's Gary's take on the moment? ---------- */
function garySituation(){if(!G||!S.me)return null;const D=G.days[G.today];const lm=L().min;
  if(lm>=21*60||lm<5*60)return 'night';
  if(!isWork(G.today)||!D||!D.target)return 'weekend';
  if(typeof legendToday==='function'&&legendToday()&&!D.hit)return 'legend';
  if(D.hit)return h32(G.today+'gh')%2?'hit':'boss';
  const yd=G.workdays.filter(d=>d<G.today).pop();const st=hm(G.cfg.dayStart),en=hm(G.cfg.dayEnd);
  if(yd&&G.days[yd]&&G.days[yd].target&&G.days[yd].team<G.days[yd].target&&lm<12*60&&D.team<D.target*.3)return 'miss';
  if(D.team===0)return 'morning';
  const f=clamp((lm-st)/Math.max(1,en-st),0,1),exp=D.target*f;
  if(D.team>=10&&D.team>=exp*1.25)return 'fast';
  if(f>.35&&D.team<exp*.7)return 'slow';
  return null;}
function garyUrgent(){try{const D=G.days[G.today];if(!D||!D.target||D.hit)return false;const lm=L().min;const gt=goldenFor(G.today);if(isWork(G.today)&&lm>=gt.start&&lm<gt.end)return true;
  const sg=sightingState(S.me,sightingFor(G.today));if(sg&&sg.phase==='live'&&!sg.ok)return true;const mins=hm(G.cfg.dayEnd)-lm;const left=D.target-D.team;return (mins<=60&&mins>0)||left<=15;}catch(e){return false;}}
{const _remG=reminder;reminder=function(){let base=null;try{base=_remG.apply(this,arguments);}catch(e){}if(!G||!S.me)return base;if(S.garyPoke&&Date.now()<S.garyPoke.until)return S.garyPoke.line;
  if(base&&garyUrgent())return base;let sit=garySituation();if(!sit)return base;
  if(xmasNowSafe()&&h32(G.today+'x'+Math.floor(L().min/45))%3===0&&sit!=='night')sit='xmas';
  const hr=Math.floor(L().min/60);return garyLine(sit,G.today+sit+hr+'|'+S.reminderIdx)||base;};}
function xmasNowSafe(){try{return typeof xmasNow==='function'&&xmasNow();}catch(e){return false;}}

/* ---------- poking Gary ---------- */
const POKES=[];
ACT.garyPoke=()=>{const now=Date.now();while(POKES.length&&now-POKES[0]>60000)POKES.shift();POKES.push(now);
  const el=document.querySelector('.remind > div');let line;
  if(POKES.length>3)line=GL().pokeLimit||'Stop poking me.';
  else{const sit=garySituation();const pool=Math.random()<.6||!sit?'poke':sit;line=garyLine(pool,now+'p'+POKES.length);}
  S.garyPoke={line,until:now+9000};if(el){el.textContent=line;const r=el.closest('.remind');r.classList.remove('gPoke');void r.offsetWidth;r.classList.add('gPoke');}else toast('<b>Gary:</b> '+esc(line),'joke');SND.pop();};
{const _hG=SCREENS.harbour;SCREENS.harbour=function(){const h=_hG.apply(this,arguments);return h.replace('<canvas class="gull" id="gullIco">','<canvas class="gull" id="gullIco" data-act="garyPoke" title="Poke Gary">');};}

/* ---------- the nest: a doubloon pinched per missed day, all returned on the next target day ---------- */
function garyNestCalc(g,p){let held=0,stolen=0,returned=0,chips=0;const log=[];
  let chip=new Set();try{if(typeof chipDays==='function')chip=chipDays(p);}catch(e){}
  Object.keys(g.days).filter(d=>d>=GARY_FROM&&d<g.today).sort().forEach(d=>{const D=g.days[d];if(!D||!D.target)return;if(typeof absent==='function'&&absent(p,d))return;if(chip.has(d)&&D.team<D.target)return;
    if(D.team>=D.target){if(held){returned+=held;chips++;log.push({date:d,k:'back',n:held});held=0;}}else{held++;stolen++;log.push({date:d,k:'took'});}});
  return{held,stolen,returned,chips,log};}
const _deriveGary=derive;derive=function(){const g=_deriveGary.apply(this,arguments);try{g.P.forEach(p=>{const pl=g.players[p];if(!pl)return;const n=garyNestCalc(g,p);pl.nest=n;pl.balance-=n.held;});}catch(e){console.warn('gary derive',e);}return g;};
function myNest(){return (G&&G.players[S.me]&&G.players[S.me].nest)||{held:0,stolen:0,returned:0,chips:0,log:[]};}

/* ---------- weekly formal complaints ---------- */
function complaintFor(ws){if(ws<weekStart(GARY_FROM))return null;const days=[0,1,2,3,4].map(i=>addDays(ws,i));const date=days[h32(ws+'cmp')%5];
  const n=44+Math.round((new Date(ws+'T12:00:00Z')-new Date(weekStart(GARY_FROM)+'T12:00:00Z'))/604800000);
  const l=GL().complaints||[];return{date,n,text:l.length?fill(l[h32(ws+'cmpT')%l.length],garyVars()):''};}
function complaintsSoFar(){const out=[];if(!G)return out;let ws=weekStart(GARY_FROM);const end=G.today;while(ws<=end){const c=complaintFor(ws);if(c&&c.date<=end)out.push(c);ws=addDays(ws,7);}return out.reverse();}
function complaintCardHtml(){if(!G||PREFS.heckles===false)return '';const c=complaintFor(weekStart(G.today));if(!c||c.date!==G.today)return '';let seen=false;try{seen=localStorage.getItem('hl_cmp_'+c.n)==='1';}catch(e){}if(seen)return '';
  return `<div class="card gComplaint"><small>Gary has filed a complaint</small><h3>Complaint #${c.n}</h3><p>"${esc(c.text)}"</p><div class="row"><a class="btn sm ghost" href="#nest">See the complaints drawer</a><button class="btn sm ghost" data-act="cmpSeen" data-n="${c.n}">Noted</button></div></div>`;}
ACT.cmpSeen=d=>{try{localStorage.setItem('hl_cmp_'+d.n,'1');}catch(e){}render();};
{const _hC=SCREENS.harbour;SCREENS.harbour=function(){const h=_hC.apply(this,arguments);const x=complaintCardHtml();if(!x)return h;const k='<div class="remind">';return h.includes(k)?h.replace(k,x+k):h;};}

/* ---------- Gary's Lost and Found: things that fell off the other captain's ship, at a markup ---------- */
function lostFound(){if(!G||!S.me)return [];const me=G.players[S.me],o=G.players[other(S.me)];if(!me||!o)return [];const ws=weekStart(G.today);
  const pool=ITEMS.filter(i=>o.owned[i.id]&&!me.owned[i.id]&&i.price>0&&!i.free&&!i.merchantOnly&&!i.xmas&&!i.bm&&!i.earn&&!i.track&&!i.setBanner&&i.cat!=='shield'&&!String(i.id).startsWith('m_')&&!itemLocked(i,me));
  return pool.map(i=>({i,k:h32(ws+i.id+'lf')})).sort((a,b)=>a.k-b.k).slice(0,3).map(x=>({it:x.i,price:Math.ceil(x.i.price*1.25/10)*10}));}

/* ---------- the nest screen ---------- */
SCREENS.nest=()=>{const n=myNest();const cs=complaintsSoFar();const lf=lostFound();const me=G.players[S.me];const quote=garyLine('nest',G.today+'n'+(S.reminderIdx||0));
  const logH=n.log.slice(-8).reverse().map(x=>`<div class="li"><span class="grow">${shortDate(x.date)}</span><span>${x.k==='took'?'Pinched 1 doubloon (target missed)':`Gave back ${x.n} (target hit) + 1 chip, owed`}</span></div>`).join('');
  return `<div class="pad"><div class="card nestHead"><canvas class="gull" id="nestGull" width="96" height="96"></canvas><div><small>Gary's nest, top of the lighthouse</small><h2>${n.held?`${n.held} of your doubloons in here`:'No doubloons of yours. Yet.'}</h2><p class="tiny">"${esc(quote)}"</p></div></div>
   <div class="card"><h3>How it works</h3><p class="tiny">On any working day the crew misses the target, Gary pinches one doubloon from each captain. The next day you hit the target he gives them all back, plus interest of exactly one chip (chips are not a currency; he still owes you them). ${GARY_FROM>G.today?'He starts on '+shortDate(GARY_FROM)+'.':''}</p>
   <div class="statRow"><div><b>${n.stolen}</b><small>pinched</small></div><div><b>${n.returned}</b><small>given back</small></div><div><b>${n.chips}</b><small>chips owed</small></div></div>${logH?`<div class="list" style="margin-top:8px">${logH}</div>`:''}</div>
   <div class="card"><h3>Lost and Found</h3><p class="tiny muted">Things that "fell off" Captain ${esc(pnameRaw(other(S.me)))}'s ship. Gary's markup is 25%. It changes every Monday.</p>
   ${lf.length?`<div class="list">${lf.map(x=>`<div class="li"><canvas class="lfIco" width="96" height="96" data-lf="${x.it.id}"></canvas><span class="grow"><b>${esc(x.it.name)}</b><br><small>${esc(CAT_NAMES[x.it.cat]||x.it.cat)} \u00b7 shop price ${fmtN(x.it.price)}</small></span><button class="btn sm" data-act="buy" data-id="${x.it.id}" data-p="${x.price}" ${me.balance<x.price?'disabled':''}>${fmtN(x.price)} ${CN}</button></div>`).join('')}</div>`:'<p class="tiny">Nothing this week. Gary says the other ship is "annoyingly well secured".</p>'}</div>
   <div class="card"><h3>The complaints drawer</h3>${cs.length?`<div class="list">${cs.slice(0,12).map(c=>`<div class="li"><span class="grow"><b>Complaint #${c.n}</b> <small class="muted">${shortDate(c.date)}</small><br><small>${esc(c.text)}</small></span></div>`).join('')}</div>`:`<p class="tiny">Empty. Gary starts filing on ${shortDate(GARY_FROM)}. He has a lot saved up.</p>`}</div>
   <p class="tiny muted" style="text-align:center">Gary's column runs every week in the Salty Herald.</p></div>`;};
{const _rdG=render;render=function(){_rdG.apply(this,arguments);try{const cv=document.getElementById('nestGull');if(cv)drawGullIcon(cv);document.querySelectorAll('canvas[data-lf]').forEach(cv=>drawItemIcon(cv,cv.dataset.lf));}catch(e){}};}

/* ---------- on the Harbour: the nest on the lighthouse, and the doubloon heist ---------- */
function lighthouseTop(){const B=G&&G.proj?G.proj.find(p=>p.id==='beacon'):null;return 106-(B&&B.built?50:34);}
function artNestBowl(c,t,coins){ell(c,0,1.4,6.6,2.4,'#6A4A2E');ell(c,0,.6,6,1.6,'#8A6440');c.strokeStyle='#B08050';c.lineWidth=.45;for(let i=0;i<9;i++){c.beginPath();c.moveTo(-6+i*1.5,.4+(i%2)*.9);c.lineTo(-4.6+i*1.4,-.5+(i%3)*.5);c.stroke();}
  for(let i=0;i<Math.min(coins,5);i++){const gx=-3.6+i*1.8,gy=-.2-(i%2)*.5;disc(c,gx,gy,.95,'#E8B43A');if(Math.sin(t/300+i*2)>.85)disc(c,gx-.3,gy-.3,.35,'#FFFFFF');}}
function artGaryNest(c,x,y,t){const b=Math.sin(t/700)*.25,look=Math.sin(t/2300)>.6?-1:1;c.save();c.translate(x,y-1.6+b);c.scale(look*1.6,1.6);c.shadowColor='rgba(30,40,60,.45)';c.shadowBlur=1.2;
  ell(c,1.6,.2,1.6,.7,'#9AA6B0');ell(c,0,-.4,3.4,2.1,'#FFFFFF');ell(c,-.4,-.7,2.4,1.2,'#B8C2CC');poly(c,[[-3.2,-.8],[-4.8,-1.6],[-3.4,.2]],'#3F4A55');
  disc(c,2.4,-2.6,1.55,'#FFFFFF');poly(c,[[3.6,-2.9],[5.4,-2.5],[3.6,-2.1]],'#F2A33A');disc(c,3.5,-2.25,.25,'#D9485F');disc(c,2.9,-3,.36,'#2C2A28');disc(c,3,-3.1,.12,'#FFFFFF');
  if(xmasNowSafe()){poly(c,[[1.1,-3.8],[3.8,-4],[2,-6.6]],'#C8102E');R(c,1,-4.2,3,.7,'#FFFFFF');disc(c,1.9,-6.8,.55,'#FFFFFF');}c.restore();}
function drawNest(c,x,y,t,coins,gary){ell(c,x,y+1.2,6.4,2.2,'#7A5A3A');c.strokeStyle='#A8784A';c.lineWidth=.5;for(let i=0;i<7;i++){c.beginPath();c.moveTo(x-6+i*1.9,y+.4+(i%2)*.8);c.lineTo(x-4+i*1.7,y-.6+(i%3)*.6);c.stroke();}
  for(let i=0;i<Math.min(coins,5);i++){const gx=x-3.6+i*1.8,gy=y-.4-(i%2)*.5;disc(c,gx,gy,.95,'#E8B43A');if(Math.sin(t/300+i*2)>.85)disc(c,gx-.3,gy-.3,.35,'#FFFFFF');}
  if(gary){const b=Math.sin(t/600)*.3;ell(c,x+.5,y-1.6+b,3.2,2,'#FFFFFF');disc(c,x+2.6,y-3.6+b,1.5,'#FFFFFF');poly(c,[[x+3.8,y-3.8+b],[x+5.6,y-3.3+b],[x+3.8,y-2.9+b]],'#F2A33A');disc(c,x+3,y-4+b,.35,'#3F3A30');ell(c,x-1.6,y-1.4+b,2.2,1,'#B8C2CC');
    if(xmasNowSafe()){poly(c,[[x+1.2,y-4.8+b],[x+4,y-5+b],[x+2.2,y-7.6+b]],'#C8102E');R(c,x+1.1,y-5.2+b,3,.7,'#FFFFFF');disc(c,x+2.1,y-7.8+b,.55,'#FFFFFF');}}}
// 21 Nov: in the painted look the nest sits on the lighthouse gallery with a proper Gary in it (it read as stray eggs half way up the tower)
addLayer('world','garyNest',(c,t)=>{if(!G||!S.me)return;const n=myNest();const top=lighthouseTop();const away=typeof marketOpen==='function'&&marketOpen();const art=typeof isArtLook==='function'&&isArtLook();const x=art?118.4:114,y=art?top-3.6:top+12;
  if(art){R(c,x-5.6,y+2.4,4,.8,'#4A3A30');line(c,x-3,y+3,x-5,y+5.2,'#4A3A30',.6);c.save();c.translate(x,y);c.scale(1.3,1.3);artNestBowl(c,t,n.held);c.restore();if(!away&&!HEIST.on)artGaryNest(c,x,y-1,t);}
  else{R(c,x-4,y+2.6,8,.8,'#6B5040');drawNest(c,x,y,t,n.held,!away&&!HEIST.on);}if(away&&!art)txt(c,'out',x,y-4,'rgba(255,255,255,.7)',4.6,'center');
  hit(x-8,y-9,16,13,"Gary's nest",n.held?`${n.held} of your doubloons are in here. Hit the target to get them back. Tap to visit.`:'Twigs, chip papers and anything shiny. Tap to visit.',{go:'nest'});},{scenes:['harbour'],z:4});
const HEIST={on:false,t0:0,back:false};
addLayer('fx','garyHeist',(c,t)=>{if(!HEIST.on)return;const u=(performance.now()-HEIST.t0)/5200;if(u>=1){HEIST.on=false;return;}const top=lighthouseTop();
  const [x0,y0,x1,y1]=HEIST.back?[114,top+8,150,150]:[150,150,114,top+8];const x=x0+(x1-x0)*u,y=y0+(y1-y0)*u-Math.sin(u*Math.PI)*36;
  drawGull(c,x-5,y-3,t);disc(c,x+5.6,y+.4,1.3,'#E8B43A');disc(c,x+5.2,y,.4,'#FFF4C0');if(u<.25){c.globalAlpha=1-u*4;txt(c,HEIST.back?'Fine. Here.':'Mine now.',x,y-8,'#FFFFFF',6,'center');}},{scenes:['harbour'],z:20});
function heistCheck(){try{if(!G||!S.me||S.screen!=='harbour')return;const n=myNest();const last=n.log[n.log.length-1];if(!last)return;const yd=G.workdays.filter(d=>d<G.today).pop();if(last.date!==yd)return;
  const k='hl_heist_'+last.date;if(localStorage.getItem(k))return;localStorage.setItem(k,'1');HEIST.on=true;HEIST.back=last.k==='back';HEIST.t0=performance.now();
  setTimeout(()=>toast(last.k==='took'?`<b>Gary pinched a doubloon.</b> Yesterday's target was missed. Hit today's and he'll give ${n.held>1?'all '+n.held:'it'} back.`:`<b>Gary gave back ${last.n} doubloon${last.n>1?'s':''}.</b> Plus one chip. He still owes you the chip.`,'joke'),900);}catch(e){}}
{const _rdH=render;render=function(){_rdH.apply(this,arguments);setTimeout(heistCheck,600);};}

/* scene hit regions that open a screen: {go:'nest'} */
// 21 Nov: works in full screen too (it leaves full screen and goes there)
document.addEventListener('click',ev=>{const cv=ev.target.closest&&ev.target.closest('canvas.scene');if(!cv||!S.hits)return;const r=cv.getBoundingClientRect();let x=(ev.clientX-r.left)/r.width*W,y=(ev.clientY-r.top)/r.height*H;const fs=cv.id==='focusCv';if(fs){const f=S.focusXf;if(!f)return;x=((ev.clientX-r.left)*f.dpr-f.ox)/f.s;y=((ev.clientY-r.top)*f.dpr-f.oy)/f.s;}
  for(let i=S.hits.length-1;i>=0;i--){const h=S.hits[i];if(x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h){if(h.act&&h.act.go){const tp=document.getElementById('tip');if(tp)tp.hidden=true;setTimeout(()=>{if(fs)try{focusOff();}catch(e){}location.hash='#'+h.act.go;},fs?260:120);}return;}}});

HELP.push(["Gary's nest",'Gary lives on top of the Funnal Cove lighthouse. On a missed-target day he pinches one doubloon from each captain; the next day you hit the target he gives them all back, plus one chip. Tap the nest to see what he has, his complaints drawer, and the Lost and Found (things the other captain owns, at a 25% markup). Poke him on his Harbour card for a comment.']);

/* ============================== THE BLACK MARKET (Stage 4) ==============================
   9pm to 1am, a lantern-lit stall on the far side of the Harbour. The seller is a cloaked figure with a beak
   who is definitely not Gary. Four items a night (two exclusive cosmetics, two joke trinkets), one of them
   "tonight's bargain" at 40% off; one night a week the bargain is a dud (a Soggy Biscuit).
   Duplicate boss loot pieces can be fenced here for doubloons. Purchases are ordinary spend entries. */
const BM_REAL=[
  {id:'hat_bmcrown',name:'Definitely Not Stolen Crown',cat:'hat',st:'bmcrown',col:'#E8B43A',price:3200},
  {id:'fig_bmhood',name:'Suspiciously Familiar Figurehead',cat:'figure',st:'bmhood',price:4500},
  {id:'hull_bmkraken',name:'Pre-Owned Kraken Hull',cat:'hull',col:'#5A3A6E',col2:'#3A2448',suckers:true,price:5000},
  {id:'sail_bmshiny',name:'The Shiniest Sail',cat:'sail',col:'#F6E6A8',col2:'#D9E4F2',pat:'grad',shiny:true,price:3800},
  {id:'flag_bmgull',name:'The Jolly Gull',cat:'flag',col:'#22252E',sym:'gull',sc:'#FFFFFF',price:1500},
  {id:'bm_chest',name:'Chest of Definitely Legal Goods',cat:'decor',price:1200},
  // 21 Nov: more things you can only get here, after dark
  {id:'sail_bmmoon',name:"Smuggler's Moonlight Sails",cat:'sail',col:'#0E1424',col2:'#9FE3F5',pat:'galaxy',price:4200},
  {id:'sail_bmtiger',name:'Contraband Tiger Sails',cat:'sail',col:'#2A2024',col2:'#C9A24A',pat:'tiger',price:3600},
  {id:'sail_bmcheck',name:"Pickpocket's Chequers",cat:'sail',col:'#2A2433',col2:'#F2C462',pat:'checker',price:2600},
  {id:'hull_bmrum',name:"Rum-Runner's Hull",cat:'hull',col:'#1C2A30',col2:'#122026',lights:true,price:6200},
  {id:'flag_bmspot',name:'The Black Spot',cat:'flag',col:'#0E0E12',sym:'skull',sc:'#C91E36',price:1400},
  {id:'flag_bmblades',name:'Hot Cutlasses',cat:'flag',col:'#5A1E2A',sym:'swords',sc:'#F2C462',price:1800},
  {id:'hat_bmmoon',name:'Moonshine Tricorn',cat:'hat',st:'tricorn',col:'#3A2A5C',price:2200},
  {id:'hat_bmband',name:"Smuggler's Bandana",cat:'hat',st:'bandana',col:'#1E1A24',price:900},
  {id:'coat_bmfence',name:"The Fence's Coat",cat:'coat',st:'trim',col:'#2A2433',col2:'#F2C462',price:3400}];
const BM_JOKE=[
  {id:'bm_scale',name:'Genuine Mermaid Scale (laminated)',cat:'decor',price:120},
  {id:'bm_map',name:'Slightly Used Treasure Map (Tesco car park)',cat:'decor',price:150},
  {id:'bm_bottle',name:'Message in a Bottle (it says "help")',cat:'decor',price:90},
  {id:'bm_tooth',name:'Real Kraken Tooth (plastic)',cat:'decor',price:140},
  {id:'bm_shipbottle',name:'Ship in a Bottle (ship sold separately)',cat:'decor',price:110},
  {id:'bm_air',name:'Bag of Premium Sea Air',cat:'decor',price:60},
  {id:'bm_rock',name:'Pet Rock (answers to Kevin)',cat:'decor',price:80},
  {id:'bm_spoon',name:'Captain Blackbeard\'s Spoon (probably)',cat:'decor',price:100}];
const BM_DUD={id:'bm_soggy',name:'Soggy Biscuit',cat:'decor',price:0};
[...BM_REAL,...BM_JOKE,BM_DUD].forEach(i=>{i.bm=true;i.lvl=1;if(!ALL_ITEMS[i.id]){ITEMS.push(i);ALL_ITEMS[i.id]=i;}});
const BM_IDS=new Set([...BM_REAL,...BM_JOKE,BM_DUD].map(i=>i.id));
// the shop never lists Black Market goods; owners still see theirs in the wardrobe and hideout
{const _shopBM=SCREENS.shop;if(_shopBM)SCREENS.shop=function(){const me=G&&G.players[S.me];const keep=ITEMS.slice();ITEMS.length=0;keep.forEach(i=>{if(!BM_IDS.has(i.id)||(me&&me.owned[i.id]))ITEMS.push(i);});try{return _shopBM.apply(this,arguments);}finally{ITEMS.length=0;keep.forEach(i=>ITEMS.push(i));}};}
(function bmTags(){const st=document.createElement('style');const ids=[...BM_IDS];st.textContent=ids.map(i=>`.shopItem:has(canvas[data-id="${i}"])`).join(',')+`{position:relative}`+ids.map(i=>`.shopItem:has(canvas[data-id="${i}"])::after`).join(',')+`{content:'Black Market';position:absolute;top:6px;right:6px;background:#2A2433;color:#F2C462;font:600 9.5px var(--display);padding:2px 6px;border-radius:8px}`;document.head.appendChild(st);})();

/* ---------- opening hours: the night belongs to the evening's date ---------- */
function marketNight(ts=Date.now()){const l=L(ts);if(l.min>=21*60)return l.date;if(l.min<60)return addDays(l.date,-1);return null;}
function marketOpen(){return !!marketNight();}
function nextNight(){const l=L();return l.min<60?addDays(l.date,-1):l.date;}
function dudNight(night){const ws=weekStart(night);return addDays(ws,h32(ws+'bmdud')%7)===night;}
function marketStock(night){const pick=(arr,n,salt)=>arr.map(i=>({i,k:h32(night+i.id+salt)})).sort((a,b)=>a.k-b.k).slice(0,n).map(x=>x.i);
  const real=pick(BM_REAL,3,'r'),joke=pick(BM_JOKE,2,'j');const bar=joke[h32(night+'bar')%2];
  const dud=dudNight(night);return [...real,...joke].map(i=>({it:i,bargain:i===bar,price:i===bar?Math.max(10,Math.round(i.price*(dud?.4:.6)/10)*10):i.price}));}

/* ---------- fenced treasure: two relics you're missing, each night, at a proper price ---------- */
function bmRelics(night){if(typeof relicList!=='function'||!G||!S.me)return [];const have=relicCounts(S.me);const miss=relicList().filter(r=>!(have[r.id]>0));
  return miss.map(r=>({r,k:h32(night+r.id+'bmr')})).sort((a,b)=>a.k-b.k).slice(0,2).map(x=>({r:x.r,price:900+(x.r.si%5)*150}));}
ACT.bmRelic=async d=>{const night=marketNight();if(!night)return toast('<b>Shut.</b> The stall packed up at 1am.','joke');const x=bmRelics(night).find(y=>y.r.id===d.id);if(!x)return;const me=G.players[S.me];
  if(me.balance<x.price)return toast('<b>Not enough doubloons.</b> "Treasure costs treasure," says the trader.','joke');const id=uid();
  try{await writeDay(S.me,G.today,{spend:{[id]:{item:'bm_relic',cost:x.price,ts:Date.now(),bm:night,relic:x.r.id}},bonus:{['bmr_'+id]:{xp:0,g:0,ts:Date.now(),relic:x.r.id}}});SFX.ach();toast(`<b>${esc(x.r.name)}</b> is in your Treasure. "Found it on a beach. Honest."`);}catch(e){writeFail(e);}};

/* ---------- fencing duplicate loot pieces ---------- */
const FENCE_PAY={common:15,uncommon:30,rare:70,legendary:180};
function fenceList(){if(typeof bossLoot!=='function'||!G)return [];const {have}=bossLoot(S.me);return Object.entries(have).filter(([id,n])=>n>1).map(([id,n])=>{const bid=id.split('_').slice(1,-1).join('_');const b=ALL_BOSSES[bid];if(!b)return null;const pc=setOf(b)[+id.split('_').pop()];return pc?{pc,n,pay:FENCE_PAY[pc.rar]||15}:null;}).filter(Boolean).sort((a,b)=>b.pay-a.pay);}

/* ---------- the screen ---------- */
function bmSay(salt){const l=GL().market||[];return l.length?l[h32(String(salt))%l.length]:"I'm not Gary.";}
SCREENS.market=()=>{const night=marketNight();const me=G.players[S.me];
  if(!night){const tonight=nextNight();return `<div class="pad"><div class="card bmShut"><canvas class="bmArt" width="480" height="260" data-bm="shut"></canvas><h2>The Black Market</h2><p>The stall is shut. A soggy sign says: <i>"Back at 9pm. Not Gary."</i></p><p class="tiny muted">Open every night from 9pm to 1am on the far side of the Harbour. Four shady items a night, and the trader buys duplicate boss loot. ${dudNight(tonight)?'':''}</p></div></div>`;}
  const st=marketStock(night);const fl=fenceList();S.bmSalt=(S.bmSalt||0);
  return `<div class="pad"><div class="card bmCard"><canvas class="bmArt" width="480" height="260" data-bm="open"></canvas><small>The Black Market \u00b7 open until 1am</small><h2>"${esc(bmSay(night+S.bmSalt))}"</h2><button class="btn sm ghost" data-act="bmTalk">Ask if he's Gary</button></div>
   <div class="card"><h3>Tonight's goods</h3><div class="list">${st.map(x=>{const own=me.owned[x.it.id];return `<div class="li bmItem ${x.bargain?'bargain':''}"><canvas class="lfIco" width="96" height="96" data-bmi="${x.it.id}"></canvas><span class="grow"><b>${esc(x.it.name)}</b>${x.bargain?' <span class="bmTag">Tonight\'s bargain</span>':''}<br><small>${x.it.cat==='decor'?'Hideout decoration':esc(CAT_NAMES[x.it.cat]||x.it.cat)}${BM_REAL.includes(x.it)?' \u00b7 only sold here':''}${x.bargain?` \u00b7 <s>${fmtN(x.it.price)}</s>`:''}</small></span>${own?'<span class="okTag">Owned</span>':`<button class="btn sm ${x.bargain?'primary':''}" data-act="bmBuy" data-id="${x.it.id}" ${me.balance<x.price?'disabled':''}>${fmtN(x.price)} ${CN}</button>`}</div>`;}).join('')}</div>
   <p class="tiny muted">The first three are only ever sold here. No receipts, no refunds. The trinket bargain is usually 40% off; if it looks too good to be true, it probably is. Stock changes every night.</p></div>
   ${(()=>{const rl=bmRelics(night);return rl.length?`<div class="card"><h3>Fenced treasure</h3><p class="tiny muted">Relics you haven't found yet. They go straight into your Treasure and count towards their set.</p><div class="list">${rl.map(x=>`<div class="li"><canvas width="96" height="96" class="lfIco" data-relic="${x.r.id}" data-found="1"></canvas><span class="grow"><b>${esc(x.r.name)}</b><br><small>${esc(x.r.set)}</small></span><button class="btn sm" data-act="bmRelic" data-id="${x.r.id}" ${me.balance<x.price?'disabled':''}>${fmtN(x.price)} ${CN}</button></div>`).join('')}</div></div>`:'';})()}
   <div class="card"><h3>Fencing</h3><p class="tiny muted">The trader buys duplicate boss loot pieces (Pell won't). He always leaves you one of each.</p>${fl.length?`<div class="list">${fl.map(x=>`<div class="li"><canvas width="96" height="96" class="lfIco" data-piece="${x.pc.id}"></canvas><span class="grow"><b>${esc(x.pc.name)}</b><br><small class="r-${x.pc.rar}">${x.pc.rar} \u00b7 you have ${x.n}</small></span><button class="btn sm" data-act="bmFence" data-id="${x.pc.id}">Sell 1 \u00b7 ${x.pay} ${CN}</button></div>`).join('')}</div>`:'<p class="tiny">No duplicates to sell. Sink more bosses. "I\'ll be here," he says. "Not as Gary."</p>'}</div></div>`;};
ACT.bmTalk=()=>{S.bmSalt=(S.bmSalt||0)+1;const h=document.querySelector('.bmCard h2');if(h)h.textContent='"'+bmSay(marketNight()+S.bmSalt)+'"';SND.pop();};
ACT.bmBuy=async d=>{const night=marketNight();if(!night)return toast('<b>Shut.</b> The stall packed up at 1am.','joke');const x=marketStock(night).find(y=>y.it.id===d.id);if(!x)return;const me=G.players[S.me];
  if(me.owned[x.it.id])return;if(me.balance<x.price)return toast('<b>Not enough doubloons.</b> "Come back richer," says the trader.','joke');
  const dud=x.bargain&&dudNight(night);const id=uid();
  try{await writeDay(S.me,G.today,{spend:{[id]:{item:dud?BM_DUD.id:x.it.id,cost:x.price,ts:Date.now(),bm:night,...(dud?{dud:x.it.id}:{})}}});
    if(dud){SND.err();const l=GL().scammed||[];toast(`<b>Scammed by a gull.</b> The "${esc(x.it.name)}" was a Soggy Biscuit in a box. "${esc(l.length?l[h32(id)%l.length]:'No refunds.')}"`,'joke');banner('SCAMMED BY A GULL','Soggy Biscuit acquired');}
    else{SFX.ach();toast(`<b>Bought ${esc(x.it.name)}.</b> "Pleasure. Tell nobody. Especially not Gary."`);banner('NEW '+x.it.name.toUpperCase(),'Black Market');
      if(x.it.cat==='decor')await ACT.place({id:x.it.id,cat:'decor'});else if(EQUIP_CATS.includes(x.it.cat))await writePlayer(S.me,{[x.it.cat]:x.it.id});}}catch(e){writeFail(e);}};
ACT.bmFence=async d=>{if(!marketOpen())return toast('<b>Shut.</b> Fencing happens after 9pm.','joke');const x=fenceList().find(y=>y.pc.id===d.id);if(!x||x.n<2)return;
  try{await writeDay(S.me,G.today,{bonus:{[`fn_${uid()}`]:{xp:0,g:x.pay,take:x.pc.id,n:1,ts:Date.now()}}});SND.coin();toast(`<b>Sold ${esc(x.pc.name)}</b> for ${x.pay} ${CN}. "Lovely. No questions."`);}catch(e){writeFail(e);}};

/* the Scammed by a Gull achievement */
{const _fm=fishMetrics;fishMetrics=function(p){const m=_fm.apply(this,arguments)||{};let n=0;try{for(const k in S.days){const d=S.days[k];if(!d||d.pid!==p)continue;for(const id in d.spend||{}){if(d.spend[id]&&d.spend[id].item===BM_DUD.id)n++;}}}catch(e){}m.scammed=n;return m;};}
[['scammed1','Scammed by a Gull','Buy a Black Market bargain that turns out to be a Soggy Biscuit','rare','Secret',['scammed',1]]].forEach(([id,name,desc,rar,cat,[metric,target]])=>{if(ACH_BY_ID[id])return;const a={id,name,desc,rar,cat,metric,target,secret:true,reveal:'Something about a biscuit.'};ACHIEVEMENTS.push(a);ACH_BY_ID[id]=a;});

/* ---------- art: the stall, the trader and the goods ---------- */
function drawTrader(c,x,y,t,s=1){c.save();c.translate(x,y);c.scale(s,s);const b=Math.sin(t/700)*.3;
  c.fillStyle='#2A2433';c.beginPath();c.moveTo(-5,0);c.quadraticCurveTo(-5.6,-8,-2.6,-12+b);c.quadraticCurveTo(0,-14.4+b,2.6,-12+b);c.quadraticCurveTo(5.6,-8,5,0);c.closePath();c.fill();
  ell(c,.4,-10.2+b,2.4,2.2,'#15121B');poly(c,[[1.6,-10.6+b],[5.8,-9.8+b],[1.6,-9+b]],'#F2A33A');disc(c,.9,-11+b,.45,'#FFE7A0');disc(c,.9,-11+b,.2,'#15121B');
  R(c,-2.2,-7+b,1.3,3.2,'#FFFFFF');c.restore();}
function drawStall(c,x,y,t){const glow=.75+.25*Math.sin(t/230)+.06*Math.sin(t/57);
  const g=c.createRadialGradient(x+2,y-12,1,x+2,y-12,26);g.addColorStop(0,`rgba(255,196,110,${.42*glow})`);g.addColorStop(1,'rgba(255,196,110,0)');c.fillStyle=g;c.fillRect(x-26,y-40,56,52);
  R(c,x-9,y-15,1,15,'#4A3628');R(c,x+11,y-15,1,15,'#4A3628');for(let i=0;i<5;i++)rr(c,x-10+i*4.4,y-18,4.4,4,1.4,i%2?'#3A2448':'#1E1A26');
  rr(c,x-9,y-6,21,6,1,'#5C4330');R(c,x-9,y-6.6,21,1,'#7A5A3A');disc(c,x-5,y-7.6,1.2,'#E8B43A');rr(c,x-1,y-9,3.4,2.6,.6,'#8A5A3A');disc(c,x+6,y-7.8,1.4,'rgba(170,220,255,.8)');
  if(xmasNowSafe())for(let i=0;i<9;i++){const on=Math.sin(t/300+i*1.7)>-.3;disc(c,x-9.5+i*2.6,y-13.6+Math.sin(i*1.4)*.4,.55,on?['#E0453B','#F2C462','#3FA34D','#4A9BE0'][i%4]:'rgba(255,255,255,.3)');}drawTrader(c,x+2.5,y-6.6,t,.62);R(c,x+11.5,y-15.4,.6,3,'#4A3628');disc(c,x+11.8,y-11.4,1.3,`rgba(255,214,130,${glow})`);lamp(c,x+11.8,y-11.4,6,.5*glow,'255,200,120');}
addLayer('world','blackMarket',(c,t)=>{const x=21,y=111;drawStall(c,x,y,t);hit(x-12,y-22,28,24,'The Black Market','Open 9pm to 1am. A cloaked trader with a beak sells shady goods and buys duplicate loot. Tap to visit.',{go:'market'});},{scenes:['harbour'],z:6,when:()=>marketOpen()});
{const _rdM=render;render=function(){_rdM.apply(this,arguments);try{document.querySelectorAll('canvas[data-bmi]').forEach(cv=>drawItemIcon(cv,cv.dataset.bmi));const pcs=document.querySelectorAll('#screen canvas[data-piece]');if(pcs.length&&typeof drawPiece==='function')pcs.forEach(cv=>drawPiece(cv,cv.dataset.piece));
  document.querySelectorAll('canvas[data-bm]').forEach(cv=>{if(cv.__on)return;cv.__on=1;const c=cv.getContext('2d');const open=cv.dataset.bm==='open';let raf;const go=()=>{if(!document.body.contains(cv))return cancelAnimationFrame(raf);const t=performance.now();c.setTransform(2,0,0,2,0,0);
    const g=c.createLinearGradient(0,0,0,130);g.addColorStop(0,'#141A33');g.addColorStop(1,'#2C3560');c.fillStyle=g;c.fillRect(0,0,240,130);for(let i=0;i<24;i++){disc(c,(i*47.3)%240,(i*19.7)%70,.5+(i%3)*.25,`rgba(255,255,255,${.4+.4*Math.sin(t/600+i)})`);}
    c.fillStyle='#1B2A44';c.fillRect(0,104,240,26);ell(c,120,106,110,10,'#3A3428');
    if(open){c.save();c.translate(120,104);c.scale(3,3);drawStall(c,0,0,t);c.restore();}else{c.save();c.translate(120,104);c.scale(3,3);R(c,-9,-15,1,15,'#4A3628');R(c,11,-15,1,15,'#4A3628');rr(c,-9,-6,21,6,1,'#5C4330');for(let i=0;i<5;i++)rr(c,-10+i*4.4,-18,4.4,4,1.4,'#3A3440');rr(c,-6,-12,14,5,.6,'#C9B48A');c.restore();txt(c,'BACK AT 9',123,84,'#3A2A1C',7,'center');}
    raf=requestAnimationFrame(go);};go();});}catch(e){}};}

