  const lit=artLitNow();const S1=P.bld,S2=shadeHex(P.bld,.74),WIN=lit?'#FFC46A':rgbaOf(P.win,.6),awn=k=>mixHex(['#E06034','#F4E2C6','#4A7EC2'][k%3],S1,.55);
