const ENV_VOLC={x:0};
/* ---------- the backdrop: three layers, current place and the next one during the fade ---------- */
function envBackdrop(c,t){const y0=ART_HZ.voyage;const st=ENVST;const draw=(e,alpha)=>{if(alpha<=0)return;const k=e.id+(e.pal?'':'_'+artMode()+(artSnowy()?'s':''));
    const far=artStrip(c,'efar'+k,ENV_W,80,q=>envFar(q,e,80));stripLoop(c,far,ENV_W,80,y0,VOY.off*.12,alpha);
    if(e.id==='volcano'){const off=VOY.off*.12;let vx=420-(((off%ENV_W)+ENV_W)%ENV_W)-90;if(vx<-100)vx+=ENV_W;ENV_VOLC.x=vx;}
    c.save();c.globalAlpha=alpha;artFog(c,y0,32,envPalOf(e).fog,.55);c.restore();
    const mid=artStrip(c,'emid'+k,ENV_W,60,q=>envMid(q,e,60));stripLoop(c,mid,ENV_W,60,y0,VOY.off*.3,alpha);
    c.save();c.globalAlpha=alpha;artFog(c,y0+1,14,envPalOf(e).fog,.45);c.restore();
    let spots=null;const near=artStrip(c,'enear'+k,ENV_W,62,q=>{spots=envNear(q,e,62);});if(spots)ENV_ANIM[k]=spots;stripLoop(c,near,ENV_W,62,y0+.5,VOY.off,alpha);return {cv:near,k};};
  const A=draw(st.a,1-st.fade);const B=st.fade>0?draw(st.b,st.fade):null;VOY.cvCur=A?A.cv:null;VOY.cvNxt=B?B.cv:null;VOY.fade=st.fade;
  // moving bits on the near shore: waterfalls, lava, lamps, crystals, the lighthouse beam
  [[A,1-st.fade,st.a],[B,st.fade,st.b]].forEach(([X,al,e])=>{if(!X||al<=0)return;const spots=ENV_ANIM[X.k];if(!spots)return;const off=(((VOY.off%ENV_W)+ENV_W)%ENV_W);c.save();c.globalAlpha=al;
    spots.forEach(s=>{for(const base of [-ENV_W,0,ENV_W]){const x=s.x+base-off-90;if(x<-40||x>W+40)continue;const y=y0-62+.5+s.y;envAnim(c,t,s,x,y);}});c.restore();});}
const ENV_ANIM={};
function envAnim(c,t,s,x,y){if(s.t==='fall'||s.t==='lava'){const lava=s.t==='lava';const col=lava?'255,150,60':s.col;c.fillStyle=`rgba(${col},${lava?.9:.75})`;c.fillRect(x,y,s.w,s.hh);for(let i=0;i<6;i++){const q=((t/(lava?900:420))+i/6)%1;c.fillStyle=lava?`rgba(255,230,140,${.7*(1-q)})`:`rgba(255,255,255,${.6*(1-q)})`;c.fillRect(x+((i*1.7)%s.w),y+q*s.hh,1,4);}
    glowAt(c,x+s.w/2,y+s.hh,lava?16:10,lava?'255,140,60':'230,245,255',lava?.6:.35);for(let i=0;i<4;i++){const q=((t/700)+i/4)%1;disc(c,x+s.w/2+(i-1.5)*3,y+s.hh-q*3,1+q*2,lava?`rgba(255,180,90,${.5*(1-q)})`:`rgba(255,255,255,${.4*(1-q)})`);}}
  else if(s.t==='glow'){glowAt(c,x,y,7,'255,190,100',.35+.12*Math.sin(t/300+x));}
  else if(s.t==='crystal'){glowAt(c,x,y,10,s.col,.35+.2*Math.sin(t/600+x*.3));}
  else if(s.t==='beam'){const a=Math.sin(t/2400)*.8+.2;c.save();c.globalCompositeOperation='lighter';const L=140;const g=c.createLinearGradient(x,y,x+Math.cos(a)*L,y+Math.sin(a)*L*.25);g.addColorStop(0,'rgba(220,255,240,.4)');g.addColorStop(1,'rgba(220,255,240,0)');c.fillStyle=g;c.beginPath();c.moveTo(x,y);c.lineTo(x+Math.cos(a-.07)*L,y+Math.sin(a-.07)*L*.25-8);c.lineTo(x+Math.cos(a+.07)*L,y+Math.sin(a+.07)*L*.25+8);c.closePath();c.fill();c.restore();glowAt(c,x,y,10,'255,236,170',.6);}}
/* ---------- the voyage sky, taken over while a place is showing ---------- */
{const _skyE=sky;sky=function(c,t,opts={}){if(!envOn())return _skyE.apply(this,arguments);envNow();const st=ENVST;const e=st.fade>.5?st.b:st.a;const s=e.sun||{};const mode=e.pal?(s.moon||s.none?'night':s.big?'sunset':'day'):skyPhase()==='dusk'?'night':skyPhase();
  SUN={x:s.x||58,y:s.y||30,night:!!(s.moon||s.none),col:s.col||'255,250,215',mode};if(!e.pal){return _skyE.apply(this,arguments);}
  SKY_TOP=artPal().sky[0];envSky(c,t,st.a,1);if(st.fade>0)envSky(c,t,st.b,st.fade);envBackdrop(c,t);runLayers('sky',c,t,{mode,night:SUN.night,opts});
  if(opts.rainbow){['#E0453B','#F2A33A','#F2D24A','#5DBE9C','#4A7EC2','#9B5DE5'].forEach((col,i)=>{c.strokeStyle=col;c.globalAlpha=.26;c.lineWidth=2.4;c.beginPath();c.arc(200,140,90-i*2.4,Math.PI,TAU);c.stroke();});c.globalAlpha=1;}};}
// the four coasts still use the Stage B backdrop but now follow the route
{const _vb=artVoyBackdrop;artVoyBackdrop=function(c){if(!envOn()||!ENVST.a)return _vb.apply(this,arguments);envBackdrop(c,performance.now());};}

/* ---------- foreground framing: branches, leaves, rocks and ice at the edges of the view ---------- */
function envFrame(c,t,e,alpha){const P=envPalOf(e);const L=-VIEW_EXT.side-2,R_=W+VIEW_EXT.side+2,T=-VIEW_EXT.top-2,B=H+VIEW_EXT.bot+2;const dk=shadeHex(P.near,.55);c.save();c.globalAlpha=alpha;const id=e.id;
  const branch=(x0,y0,dir,col,leaf,n)=>{c.strokeStyle=col;c.lineCap='round';c.lineWidth=4;c.beginPath();c.moveTo(x0,y0);c.quadraticCurveTo(x0+dir*30,y0+14,x0+dir*62,y0+22);c.stroke();c.lineWidth=2;c.beginPath();c.moveTo(x0+dir*26,y0+11);c.quadraticCurveTo(x0+dir*34,y0+26,x0+dir*30,y0+36);c.moveTo(x0+dir*48,y0+18);c.lineTo(x0+dir*58,y0+8);c.stroke();
    if(leaf)for(let i=0;i<n;i++){const u=(h32(id+'lf'+i)%1000)/1000,v=(h32(id+'lv'+i)%1000)/1000;const lx=x0+dir*(10+u*58),ly=y0+6+u*16+(v-.5)*22+Math.sin(t/900+i)*.8;c.fillStyle=leaf[i%leaf.length];c.beginPath();c.ellipse(lx,ly,3.4,2.2,u*3,0,TAU);c.fill();}};
  const rocks=(x,y,dir,col)=>{c.fillStyle=col;c.beginPath();c.moveTo(x,y);c.lineTo(x+dir*8,y-16);c.lineTo(x+dir*26,y-22);c.lineTo(x+dir*44,y-8);c.lineTo(x+dir*56,y);c.closePath();c.fill();c.fillStyle=shadeHex(col,1.3);c.beginPath();c.moveTo(x+dir*8,y-16);c.lineTo(x+dir*26,y-22);c.lineTo(x+dir*22,y-10);c.closePath();c.fill();};
  const leaves=(x,y,dir,col,n)=>{for(let i=0;i<n;i++){const a=(-Math.PI/2)+dir*(.2+i*.32)+Math.sin(t/1400+i)*.04;const len=26+i*4;c.fillStyle=i%2?col:shadeHex(col,1.2);c.save();c.translate(x,y);c.rotate(a);c.beginPath();c.moveTo(0,0);c.quadraticCurveTo(len*.5,-len*.22,len,0);c.quadraticCurveTo(len*.5,len*.22,0,0);c.fill();c.restore();}};
  if(id==='haunted'){branch(L,T+8,1,dk,null,0);branch(R_,T+4,-1,dk,null,0);rocks(L,B,1,dk);rocks(R_,B,-1,dk);c.strokeStyle=dk;c.lineWidth=3;[[L+20,0],[L+34,1]].forEach(([x,k])=>{c.beginPath();c.moveTo(x,B);c.lineTo(x+10+k*4,B-30-k*8);c.stroke();});}
  else if(id==='autumn'){branch(L,T+4,1,dk,['#E0502A','#F08A2A','#C83A20','#F4B040'],26);branch(R_,T+10,-1,dk,['#E0502A','#F08A2A','#C83A20'],22);}
  else if(id==='sky'){c.fillStyle=rgbaOf(P.fog,.9);[[L+10,B-6,26],[L+40,B,20],[R_-14,B-4,28],[R_-44,B,18]].forEach(([x,y,r])=>{c.beginPath();c.arc(x,y,r,0,TAU);c.fill();});}
  else if(id==='winter'||id==='glacier'){if(id==='winter'){artPine(c,L+14,B+4,48,dk,true);artPine(c,R_-12,B+6,42,dk,true);}else{c.fillStyle='#CFE2FA';[[L,B,1],[R_,B,-1]].forEach(([x,y,d])=>{c.beginPath();c.moveTo(x,y);c.lineTo(x+d*6,y-14);c.lineTo(x+d*40,y-18);c.lineTo(x+d*52,y);c.closePath();c.fill();c.fillStyle='#FFFFFF';c.fillRect(Math.min(x,x+d*40),y-18.5,40,2.4);c.fillStyle='#CFE2FA';});}}
  else if(id==='desert'){leaves(L-4,T+6,1,dk,5);leaves(R_+4,B+4,-1,dk,5);}
  else if(id==='crystal'){c.fillStyle=dk;c.fillRect(L,T,R_-L,6);for(let i=0;i<22;i++){const x=L+i*((R_-L)/22)+(h32('st'+i)%6),hh=8+(h32('sh'+i)%22);c.beginPath();c.moveTo(x-4,T+5);c.lineTo(x,T+5+hh);c.lineTo(x+4,T+5);c.closePath();c.fill();if(i%4===1){c.fillStyle='rgba(138,232,255,.85)';c.beginPath();c.moveTo(x-2,T+5);c.lineTo(x,T+5+hh*.7);c.lineTo(x+2,T+5);c.closePath();c.fill();c.fillStyle=dk;glowAt(c,x,T+hh*.5,10,'138,232,255',.3);}}
    [[L+18,B,'255,138,224'],[R_-20,B,'122,240,255']].forEach(([x,y,col])=>{glowAt(c,x,y-12,20,col,.4+.15*Math.sin(t/700));c.fillStyle=`rgb(${col})`;c.fillRect(x-1,y-12,2,12);c.beginPath();c.ellipse(x,y-12,9,5,0,Math.PI,0);c.fill();});}
  else if(id==='blossom'){branch(L,T+6,1,dk,['#F8B4D0','#FFD6E6','#F090B8'],34);}
  else if(id==='storm'){rocks(L,B,1,dk);rocks(R_,B,-1,dk);for(let i=0;i<5;i++){const q=((t/900)+i/5)%1;disc(c,L+40+i*6,B-14-q*12,1.4*(1-q)+.4,`rgba(230,240,250,${.6*(1-q)})`);}}
  else if(id==='volcano'){rocks(L,B,1,dk);rocks(R_,B,-1,dk);c.strokeStyle=`rgba(255,120,40,${.7+.2*Math.sin(t/250)})`;c.lineWidth=.8;c.beginPath();c.moveTo(L+8,B-16);c.lineTo(L+26,B-22);c.moveTo(R_-8,B-16);c.lineTo(R_-26,B-22);c.stroke();}
  else if(id==='jungle'){leaves(L-4,T+4,1,dk,6);leaves(R_+4,T+4,-1,dk,6);leaves(L-4,B+2,1,shadeHex(dk,1.15),5);leaves(R_+4,B+2,-1,shadeHex(dk,1.15),5);c.strokeStyle=dk;c.lineWidth=1;for(let i=0;i<4;i++){const x=L+24+i*9;c.beginPath();c.moveTo(x,T);c.quadraticCurveTo(x+3,T+20+i*6,x-1,T+34+i*8);c.stroke();}}
  c.restore();}
/* ---------- drifting particles for each place ---------- */
function envFx(c,t,e,alpha){const T=-VIEW_EXT.top,span=H+VIEW_EXT.top+VIEW_EXT.bot,L=-VIEW_EXT.side,wid=W+VIEW_EXT.side*2;const q=THEME.reduced?.4:1;c.save();c.globalAlpha=alpha;const n=Math.round(30*q);
  if(e.fx==='leaves'||e.fx==='petals'){const cols=e.fx==='leaves'?['#E0502A','#F08A2A','#F4B040']:['#F8B4D0','#FFD6E6','#FFFFFF'];for(let i=0;i<n;i++){const fall=t*q/(60+(i%7)*14);const y=T+((i*37.7+fall)%span);const x=L+((i*61.3+Math.sin(t*q/900+i)*14+fall*.6)%wid);c.save();c.translate(x,y);c.rotate(t/500+i);c.fillStyle=cols[i%3];c.beginPath();c.ellipse(0,0,e.fx==='leaves'?2.2:1.6,1.1,0,0,TAU);c.fill();c.restore();}}
  else if(e.fx==='snow'){for(let i=0;i<n*1.6;i++){const fall=t*q/(38+(i%7)*9);const y=T+((i*37.7+fall)%span);const x=L+((i*61.3+Math.sin(t*q/900+i)*3+fall*.18)%wid);disc(c,x,y,i%4===0?1.1:.6,'rgba(255,255,255,.85)');}}
  else if(e.fx==='embers'){for(let i=0;i<n;i++){const rise=t*q/(50+(i%7)*12);const y=T+span-((i*37.7+rise)%span);const x=L+((i*61.3+Math.sin(t*q/600+i)*8)%wid);const a=.5+.5*Math.sin(t/200+i);disc(c,x,y,.7,`rgba(255,${150+(i%5)*20},60,${a})`);}}
  else if(e.fx==='rain'){c.strokeStyle='rgba(210,225,240,.5)';c.lineWidth=.6;c.beginPath();for(let i=0;i<n*4;i++){const x=L+((i*53.7+t*q*.12)%wid),y=T+((i*91.3+t*q*.5)%span);c.moveTo(x,y);c.lineTo(x-3,y+8);}c.stroke();
    const k=Math.floor(t/3000),u=t%3000;if(h32('el'+k)%2===0&&u<180){c.fillStyle=`rgba(230,240,255,${.3*(1-u/180)})`;c.fillRect(L,T,wid,span);let x=60+h32('ex'+k)%200,y=T;c.strokeStyle='rgba(245,250,255,.95)';c.lineWidth=1.1;c.beginPath();c.moveTo(x,y);while(y<ART_HZ.voyage-6){x+=(h32('ej'+k+y)%13)-6;y+=8;c.lineTo(x,y);}c.stroke();}}
  else if(e.fx==='spores'||e.fx==='fireflies'||e.fx==='sparkle'){const col=e.fx==='spores'?['138,232,255','200,154,255']:e.fx==='fireflies'?['220,255,140','255,230,140']:['255,240,255','255,210,240'];c.save();c.globalCompositeOperation='lighter';for(let i=0;i<n;i++){const x=L+((h32('sp'+i)%1000)/1000*wid+Math.sin(t*q/1700+i)*12+t*q/(160+i*7))%wid,y=T+span*.25+((h32('sy'+i)%1000)/1000)*span*.6+Math.sin(t*q/1300+i*1.7)*8;const a=Math.max(0,Math.sin(t*q/(500+(i%5)*120)+i*2.3));if(a<.1)continue;glowAt(c,x,y,4,col[i%2],.5*a);disc(c,x,y,.6,`rgba(${col[i%2]},${a})`);}c.restore();}
  else if(e.fx==='dust'){for(let i=0;i<n;i++){const x=L+((i*61.3+t*q/40)%wid),y=T+span*.4+((i*29.1)%(span*.5));c.fillStyle=`rgba(255,220,170,${.25+.2*Math.sin(t/400+i)})`;c.fillRect(x,y,2.4,.5);}}
  else if(e.fx==='mist'){for(let i=0;i<5;i++){const x=((((h32('hm'+i)%1000)/1000)*(W+200)+t*q/60)%(W+200))-100,y=ART_HZ.voyage+6+i*6;const g=c.createRadialGradient(x,y,0,x,y,70);g.addColorStop(0,'rgba(150,240,220,.16)');g.addColorStop(1,'rgba(150,240,220,0)');c.save();c.translate(x,y);c.scale(1,.15);c.translate(-x,-y);c.fillStyle=g;c.fillRect(x-70,y-70,140,140);c.restore();}}
  c.restore();}
addLayer('fx','envFx',(c,t)=>{const st=ENVST;if(!st.a)return;if(st.a.fx)envFx(c,t,st.a,1-st.fade);if(st.fade>0&&st.b.fx)envFx(c,t,st.b,st.fade);},{scenes:['voyage'],z:6,when:()=>envOn()});
addLayer('overlay','envFrame',(c,t)=>{const st=ENVST;if(!st.a)return;envFrame(c,t,st.a,1-st.fade);if(st.fade>0)envFrame(c,t,st.b,st.fade);
  // the name of the place as you sail in
  const age=performance.now()-ENVST.shownAt;if(ENVST.shownId&&age<5200){const e=ENV_BY[ENVST.shownId];const a=Math.min(1,age/600,(5200-age)/900);c.save();c.globalAlpha=a;const y=-VIEW_EXT.top+Math.max(36,VIEW_EXT.top*.55);
    c.font='600 5.4px Fredoka, Nunito, sans-serif';c.textAlign='center';c.fillStyle='rgba(255,255,255,.8)';c.fillText(e.rare?'A RARE PLACE':'NOW SAILING',160,y-7);c.font='700 10px Fredoka, Nunito, sans-serif';c.lineWidth=2.4;c.strokeStyle='rgba(0,0,0,.35)';c.strokeText(e.name,160,y+4);c.fillStyle='#FFFFFF';c.fillText(e.name,160,y+4);c.restore();}},{scenes:['voyage'],z:5,when:()=>envOn()});

/* ============================== VOYAGE SOUNDSCAPES (21 Nov) ==============================
   Each place you sail through has its own quiet soundscape, made live in the browser (no audio files): the sea and the
   wind underneath, then the things that make the place: gulls on the coasts, an owl and a creaking wreck in Wreckers'
   Bay, a waterfall and birdsong in the Amber Gorge, chimes over the Sky Isles, a howling wind and a far bell in
   Frostholm, dry wind and a lone plucked melody in the Sunken Sands, drips and glassy chimes in the Crystal Caverns,
   koto notes in the Blossom Isles, rain and thunder on the Thunder Coast, creaking ice under the Glass Glacier, rumbles,
   crackles and bubbling lava in the Ember Isles, and insects and birds around the Emerald Temple. It plays while a voyage is on screen
   (the Lock In screen or full screen), only with sound on (the speaker button), and fades between places. */
const SCAPE={cur:null,id:null,master:null};
const SCAPE_VOL=.22;
const NBUF={};
function noiseBuf(ac,type){if(NBUF[type])return NBUF[type];const n=ac.sampleRate*4,b=ac.createBuffer(1,n,ac.sampleRate),d=b.getChannelData(0);let l=0,b0=0,b1=0,b2=0,b3=0,b4=0,b5=0,b6=0;
  for(let i=0;i<n;i++){const w=Math.random()*2-1;if(type==='white')d[i]=w*.5;else if(type==='brown'){l=(l+.02*w)/1.02;d[i]=l*3.2;}else{b0=.99886*b0+w*.0555179;b1=.99332*b1+w*.0750759;b2=.969*b2+w*.153852;b3=.8665*b3+w*.3104856;b4=.55*b4+w*.5329522;b5=-.7616*b5-w*.016898;d[i]=(b0+b1+b2+b3+b4+b5+b6+w*.5362)*.11;b6=w*.115926;}}
  NBUF[type]=b;return b;}
function scapeMaster(ac){if(!SCAPE.master){const g=ac.createGain();g.gain.value=0;g.connect(ac.destination);SCAPE.master=g;}return SCAPE.master;}
// one place's soundscape: continuous beds plus little events on timers
function makeScape(ac,id){const out=ac.createGain();out.gain.value=0;out.connect(scapeMaster(ac));const nodes=[],timers=[];const now=()=>ac.currentTime;
  const src=type=>{const s=ac.createBufferSource();s.buffer=noiseBuf(ac,type);s.loop=true;s.loopStart=Math.random()*3;s.start(0,Math.random()*3);nodes.push(s);return s;};
  const lfo=(rate,depth,param)=>{const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=rate;g.gain.value=depth;o.connect(g);g.connect(param);o.start();nodes.push(o);};
  const bed=(type,ftype,freq,q,vol,swell,rate)=>{const s=src(type),f=ac.createBiquadFilter();f.type=ftype;f.frequency.value=freq;f.Q.value=q||.7;const g=ac.createGain();g.gain.value=vol;s.connect(f);f.connect(g);g.connect(out);if(swell)lfo(rate||.08,vol*swell,g.gain);return {f,g};};
  const waves=(v=1)=>{bed('brown','lowpass',520,.5,.55*v,.6,.09);bed('pink','lowpass',1400,.4,.05*v,.9,.07);};
  const wind=(freq,v=1)=>{const w=bed('pink','bandpass',freq,1.4,.16*v,.7,.05);lfo(.03,freq*.35,w.f.frequency);};
  const pad=(freqs,v=1,type='sine')=>{freqs.forEach((fq,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=fq;o.detune.value=(i%2?6:-6);g.gain.value=.018*v;o.connect(g);g.connect(out);lfo(.07+i*.02,.012*v,g.gain);lfo(.2,3,o.detune);o.start();nodes.push(o);});};
  const env=(g,a,peak,d,t0)=>{g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(peak,t0+a);g.gain.exponentialRampToValueAtTime(.0001,t0+a+d);};
  const tone=(fq,type,peak,a,d,{to,glide,filt,echo}={})=>{const t0=now()+.02,o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(fq,t0);if(to)o.frequency.exponentialRampToValueAtTime(to,t0+(glide||d));let n=o;if(filt){const f=ac.createBiquadFilter();f.type='lowpass';f.frequency.value=filt;o.connect(f);n=f;}n.connect(g);g.connect(out);
    if(echo){const dl=ac.createDelay(1);dl.delayTime.value=echo;const fb=ac.createGain();fb.gain.value=.35;g.connect(dl);dl.connect(fb);fb.connect(dl);dl.connect(out);setTimeout(()=>{try{dl.disconnect();fb.disconnect();}catch(e){}},(a+d+3)*1000);}
    env(g,a,peak,d,t0);o.start(t0);o.stop(t0+a+d+.1);};
  const burst=(type,ftype,freq,peak,a,d)=>{const t0=now()+.02,s=ac.createBufferSource();s.buffer=noiseBuf(ac,type);const f=ac.createBiquadFilter();f.type=ftype;f.frequency.value=freq;const g=ac.createGain();s.connect(f);f.connect(g);g.connect(out);env(g,a,peak,d,t0);s.start(t0,Math.random()*3);s.stop(t0+a+d+.1);};
  const every=(min,max,fn)=>{let alive=true,h=0;const go=()=>{if(!alive)return;try{fn();}catch(e){}h=setTimeout(go,min+Math.random()*(max-min));};h=setTimeout(go,Math.random()*min);timers.push({stop:()=>{alive=false;clearTimeout(h);}});};
  const pent=[0,2,4,7,9],note=(root,deg)=>root*Math.pow(2,(pent[deg%5]+12*Math.floor(deg/5))/12);
  const bird=()=>{const n=2+Math.floor(Math.random()*4),base=2200+Math.random()*1400;for(let i=0;i<n;i++)setTimeout(()=>tone(base*(1+Math.random()*.25),'sine',.03,.01,.12,{to:base*1.35,glide:.1}),i*130);};
  const gull=()=>{const b=1500+Math.random()*300;tone(b,'sawtooth',.012,.04,.35,{to:b*.7,glide:.3,filt:2200});setTimeout(()=>tone(b*1.05,'sawtooth',.01,.04,.3,{to:b*.72,glide:.25,filt:2200}),320);};
  const owl=()=>{tone(400,'sine',.05,.08,.35,{to:370,filt:900});setTimeout(()=>tone(400,'sine',.04,.08,.5,{to:360,filt:900}),520);};
  const creak=()=>tone(90+Math.random()*40,'sawtooth',.03,.4,1.4,{to:70+Math.random()*30,glide:1.6,filt:500});
  const bell=(f=330)=>{tone(f,'sine',.04,.01,4,{echo:.4});tone(f*2.4,'sine',.012,.01,2.4);};
  const chime=(root)=>tone(note(root,Math.floor(Math.random()*10)),'sine',.035,.005,2.6,{echo:.33});
  const pluck=(root,type='triangle')=>{const t=note(root,Math.floor(Math.random()*8));tone(t,type,.05,.004,.9,{filt:2600,echo:.28});};
  const drip=()=>tone(1200+Math.random()*900,'sine',.04,.002,.25,{to:700,glide:.15,echo:.22});
  const thunder=()=>{burst('brown','lowpass',180,.5,.25,3.5);setTimeout(()=>burst('brown','lowpass',90,.4,.1,2.5),400);};
  const crackle=()=>{for(let i=0;i<3+Math.random()*4;i++)setTimeout(()=>burst('white','highpass',2500,.05,.002,.03),Math.random()*400);};
  const bubble=()=>tone(110+Math.random()*60,'sine',.08,.01,.25,{to:50,glide:.2});
  const insects=()=>{const f=4200+Math.random()*800;for(let i=0;i<6;i++)setTimeout(()=>tone(f,'square',.006,.005,.04,{filt:6000}),i*55);};
  const iceCrack=()=>{burst('white','bandpass',1800,.06,.002,.12);setTimeout(creak,200);};
  switch(id){
    case 'fjord':waves(.9);wind(420,.7);every(9000,18000,bird);break;
    case 'cliffs':waves(1.1);every(6000,14000,gull);break;
    case 'ruins':waves(1);wind(500,.6);every(8000,16000,gull);break;
    case 'isles':waves(.8);every(5000,11000,bird);every(14000,26000,gull);break;
    case 'haunted':waves(.9);wind(300,.9);pad([110,130.8,164.8],1.1);every(9000,17000,owl);every(7000,14000,creak);every(20000,32000,()=>bell(196));break;
    case 'autumn':waves(.6);bed('pink','bandpass',1800,.6,.09,.15,.2);wind(650,.6);every(4000,9000,bird);break;
    case 'sky':wind(900,.8);pad([220,277.2,329.6,440],1.2);every(2500,6000,()=>chime(523));break;
    case 'winter':waves(.5);wind(480,1.4);every(18000,30000,()=>bell(294));every(9000,20000,()=>chime(784));break;
    case 'desert':waves(.5);wind(720,1.1);every(5000,11000,()=>pluck(147,'triangle'));break;
    case 'crystal':bed('pink','bandpass',1600,.6,.06,.2,.15);pad([196,246.9,293.7],.8);every(1500,4000,drip);every(3000,7000,()=>chime(1047));break;
    case 'blossom':waves(.6);every(2500,5500,()=>pluck(294,'triangle'));every(7000,14000,bird);break;
    case 'storm':waves(1.5);wind(560,1.3);bed('white','highpass',2400,.5,.06,.3,.3);every(9000,18000,thunder);break;
    case 'glacier':waves(.5);wind(440,1.2);pad([261.6,329.6,392],.7);every(7000,15000,iceCrack);every(10000,20000,()=>chime(988));break;
    case 'volcano':waves(.6);bed('brown','lowpass',110,.7,.6,.4,.05);every(1200,3500,crackle);every(1500,4000,bubble);every(14000,26000,thunder);break;
    // the Rusty Anchor: a low fire rumble and hiss, little snaps and pops, a bigger crackle now and then, a log settling
    case 'tavern':bed('brown','lowpass',220,.7,.35,.35,.12);bed('pink','bandpass',1300,.9,.022,.6,.35);every(160,650,()=>burst('white','highpass',2200+Math.random()*2400,.02+Math.random()*.04,.001,.015+Math.random()*.03));every(1400,3800,crackle);every(7000,15000,()=>burst('brown','lowpass',320,.12,.03,.6));break;
    case 'jungle':waves(.4);bed('pink','bandpass',1600,.6,.05,.15,.2);every(1800,4000,bird);every(1200,2600,insects);break;
    default:waves(1);}
  return {out,stop(fade=2.5){const t=now();try{out.gain.cancelScheduledValues(t);out.gain.setValueAtTime(out.gain.value,t);out.gain.linearRampToValueAtTime(0,t+fade);}catch(e){}
      timers.forEach(x=>x.stop());setTimeout(()=>{nodes.forEach(n=>{try{n.stop&&n.stop();n.disconnect();}catch(e){}});try{out.disconnect();}catch(e){}},fade*1000+200);},
    start(fade=2.5){const t=now();out.gain.setValueAtTime(0,t);out.gain.linearRampToValueAtTime(1,t+fade);}};}
// keep the right soundscape playing while the voyage is on screen
{const _dvS=drawVoyage;drawVoyage=function(){VOY.lastDraw=performance.now();return _dvS.apply(this,arguments);};}
function scapeTick(){try{const play=!!(S&&S.sound&&isArtLook()&&VOY.lk&&VOY.lastDraw&&performance.now()-VOY.lastDraw<1500&&document.visibilityState==='visible'&&ENVST.a);
    if(!play){if(SCAPE.cur){SCAPE.cur.stop(1.2);SCAPE.cur=null;SCAPE.id=null;}return;}
    const ac=getAC();if(!ac)return;const m=scapeMaster(ac);if(m.gain.value<SCAPE_VOL*.99){m.gain.setTargetAtTime(SCAPE_VOL,ac.currentTime,.4);}
    const want=(ENVST.fade>.5?ENVST.b:ENVST.a).id;if(SCAPE.id!==want){if(SCAPE.cur)SCAPE.cur.stop(3);SCAPE.cur=makeScape(ac,want);SCAPE.cur.start(3);SCAPE.id=want;}}catch(e){}}
setInterval(scapeTick,500);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'&&SCAPE.cur){SCAPE.cur.stop(.3);SCAPE.cur=null;SCAPE.id=null;}});

// the fire in the Tavern crackles while you're in there (follows the sound button)
const TVSCAPE={cur:null};
setInterval(()=>{try{const play=!!(S&&S.sound&&S.screen==='tavern'&&document.visibilityState==='visible');if(!play){if(TVSCAPE.cur){TVSCAPE.cur.stop(1.2);TVSCAPE.cur=null;}return;}
  const ac=getAC();if(!ac)return;const m=scapeMaster(ac);if(m.gain.value<SCAPE_VOL*.99)m.gain.setTargetAtTime(SCAPE_VOL,ac.currentTime,.4);if(!TVSCAPE.cur){TVSCAPE.cur=makeScape(ac,'tavern');TVSCAPE.cur.start(2);}}catch(e){}},500);

/* ============================== 22 Nov: every fish on every trip ==============================
   Trips that start from FISH_V5_AT on: the trip length no longer picks the spot. Each trip gets a random spot
   (seeded by its start time, so both captains see the same one), and every fish in the game can bite on any trip.
   The spot only nudges the odds a little (deeper water: slightly more rare-and-up). Dawn and dusk fish keep their hours.
   Trips that started earlier keep their old rolls, so nothing already caught changes. */
const FISH_V5_AT=Date.UTC(2026,10,22,1,0);
function fishSpotOf(s,durMs){return (s||0)>=FISH_V5_AT?h32('spot'+s)%4:fishDepth(durMs);}
fishTripsOf=function(sessions,lock){const t=(sessions||[]).filter(x=>isFish(x.mode)).map(x=>({s:x.s,e:x.e||x.s+(x.dur||0),depth:fishSpotOf(x.s,x.cdur||x.planned||x.dur),bait:x.bait||''}));
  if(lock&&isFish(lock.mode))t.push({s:lock.s,e:Infinity,depth:fishSpotOf(lock.s,lock.cdur||lock.dur),bait:lock.bait||''});return t.sort((a,b)=>a.s-b.s);};
const _fp5={};
function fishPool5(ri,tc){const k=ri+'|'+tc;return _fp5[k]||(_fp5[k]=FISH.filter(f=>f.rar===FORDER[ri]&&(!f.time||f.time===tc)));}
function fishRollV5(id,t,trip,date){const u=k=>h32(id+k)/4294967296;
  let x=u('tr');const lm=trip.bait==='lure'?BAITS.lure.trans:1;for(const f of FISH_TRANS4){const pr=lm/f.odds;if(x<pr)return f;x-=pr;}
  if(u('fish')>=.72)return null;const w=fishWeights(trip.depth,trip.bait);let y=u('fr')*w.reduce((a,b)=>a+b,0),ri=0;for(;ri<5;ri++){if(y<w[ri])break;y-=w[ri];}
  const min=L(t).min,tc=min<540?'dawn':min>=1020?'dusk':'day';const fd=fishOfDay(date).id;
  for(;ri>=0;ri--){const pool=fishPool5(ri,tc);if(pool.length){let tot=0;for(const f of pool)tot+=f.id===fd?6:1;let z=u('fs')*tot;for(const f of pool){const ww=f.id===fd?6:1;if(z<ww)return f;z-=ww;}return pool[pool.length-1];}}
  return null;}
{const _r4=fishRollV2;fishRollV2=function(id,t,trip,date){return trip&&trip.s>=FISH_V5_AT?fishRollV5(id,t,trip,date):_r4(id,t,trip,date);};}

/* odds as a player sees them before setting off: averaged over the four spots, since the spot is a surprise */
function fishOddsAny(bait,tc){const tt=FISH_TRANS4.reduce((a,f)=>a+1/f.odds,0)*(bait==='lure'?BAITS.lure.trans:1);const pr=FORDER.map(()=>0);
  for(let d=0;d<4;d++){const w=fishWeights(d,bait),tot=w.reduce((a,b)=>a+b,0);FORDER.forEach((r,i)=>{let j=i;while(j>=0&&!fishPool5(j,tc).length)j--;if(j>=0)pr[j]+=w[i]/tot*.72/4;});}
  return FORDER.map((r,i)=>({r,p:pr[i]*(1-tt),n:fishPool5(i,tc).length})).concat([{r:'transcendent',p:tt,n:FISH_TRANS4.length,each:FISH_TRANS4.map(f=>f.odds)}]);}
{const _foF=fishOddsFor;fishOddsFor=function(f,dep,bait=''){if(f.rar==='transcendent')return _foF(f,dep,bait);const ri=FORDER.indexOf(f.rar);let p=0;
  for(let d=0;d<4;d++){const w=fishWeights(d,bait),tot=w.reduce((a,b)=>a+b,0);p+=w[ri]/tot*.72/4;}const n=FISH.filter(x=>x.rar===f.rar).length||1;return Math.max(1,Math.round(n/p));};}

{const _fp=fishPanelHtml;fishPanelHtml=function(tier){let h=_fp(tier);const bait=S.view.bait||S._bait||'';const min=L().min,tc=min<540?'dawn':min>=1020?'dusk':'day';
  const head=`<div class="tierHead"><b>Fishing: a surprise spot</b><small>Every trip drops anchor somewhere random: ${FISH_SPOTS.map(s=>s.name).join(', ')}. Every fish can bite on any trip, whatever the length, transcendent ones included. Deeper water nudges the odds a little, and a few fish only bite at dawn or dusk. Every DM is a cast, and about 7 in 10 land a fish.</small></div>`;
  h=h.replace(/<div class="tierHead">[\s\S]*?<\/small><\/div>/,head).replace(/ \u00b7 bites deeper than this/,'');
  const rows=fishOddsAny(bait,tc).map(x=>{if(!x.n||!x.p)return `<span class="off"><b class="rtag r-${x.r}">${x.r}</b>not at this hour</span>`;
    const each=x.each?`each 1 in ${fmtN(Math.min(...x.each))} to ${fmtN(Math.max(...x.each))}`:`each fish 1 in ${fmtN(Math.round(x.n/x.p))}`;
    return `<span><b class="rtag r-${x.r}">${x.r}</b>any: 1 in ${fmtN(Math.max(1,Math.round(1/x.p)))} \u00b7 ${each}</span>`;}).join('');
  return h.replace(/<div class="fishOdds">[\s\S]*?<\/div>/,`<div class="fishOdds"><small class="tiny muted" style="flex-basis:100%">Odds per cast (per DM), averaged over the four spots, right now</small>${rows}</div>`);};}

/* fish info: no more "bites at X and deeper" */
{const _fi=ACT.fishInfo;ACT.fishInfo=function(d){const r=_fi.apply(this,arguments);const m=$('#modal');if(m)m.querySelectorAll('p.muted').forEach(p=>{p.innerHTML=p.innerHTML.replace(/Bites at [^.,]+?(?: and deeper| only)/,'Bites on any trip');});return r;};}

/* the on-screen label follows the trip's own spot */
{const _df=drawFishing;drawFishing=function(c,t,lk){const s0=fishDepth;fishDepth=()=>fishSpotOf(lk.s,lk.cdur||lk.dur);try{_df(c,t,lk);}finally{fishDepth=s0;}};}

/* ============================== 22 Nov: Challenges are gone ==============================
   The duels and co-op goals are removed everywhere. Stakes live in the Tavern only. Past results still count:
   the XP and doubloons they paid stay, and the two achievements already unlocked from them (First Blood, Game On)
   stay unlocked. Everything that could only be earned through challenges now comes from levels instead. */

// 1. No challenge screens, links, invites, banners or toasts. Old results stay inside the numbers that derive() adds up.
challengesHtml=()=>'';
wagersHtml=()=>'';
{const _dv=derive;derive=function(){const g=_dv.apply(this,arguments);if(g)g.chals=[];return g;};}

// 2. The weekly quest that needed a challenge becomes one you can finish on your own (same id, so this week's slot stays put)
{const q=WEEKLY_QUESTS.find(x=>x.id==='wchal');if(q)Object.assign(q,{name:'Send 40 follow-ups',m:'wFu',n:40,xp:300,g:90});}

// 3. Achievements nobody can reach any more are retired. The ones already unlocked stay (chalWon_0, chalPlayed_0).
{const gone=new Set(['chalWon_1','chalWon_2','chalWon_3','chalWon_4','chalWon_5','chalPlayed_1','chalPlayed_2','chalPlayed_3','chalPlayed_4','chalPlayed_5','coop10','coop50','s_final']);
 for(let i=ACHIEVEMENTS.length-1;i>=0;i--)if(gone.has(ACHIEVEMENTS[i].id)){delete ACH_BY_ID[ACHIEVEMENTS[i].id];ACHIEVEMENTS.splice(i,1);}}

// 4. The four challenge-only items move onto the level track
{const lv={flag_duellist:23,flag_raid:28,hull_arena:33,sail_champion:38};
 Object.entries(lv).forEach(([id,L])=>{const it=ALL_ITEMS[id];if(!it)return;delete it.earn;it.track=L;it.price=0;it.lvl=L;if(!TRACK.includes(it))TRACK.push(it);});
 TRACK.sort((a,b)=>a.track-b.track);}

// 5. Words: help, records and the tavern no longer mention challenges
{const drop=t=>{let i;while((i=HELP.findIndex(h=>h[0]===t))>=0)HELP.splice(i,1);};drop('Challenges');
 HELP.forEach(h=>{if(typeof h[1]==='string')h[1]=h[1].replace(', challenge gear','').replace('fish gear, boss trophies, hunter gear, veteran pieces','fish gear, boss trophies, hunter gear, veteran pieces');});}
{const _rv=SCREENS.rivals;if(_rv)SCREENS.rivals=function(){return _rv.apply(this,arguments).replace(/<tr><td>Challenges won<\/td>[\s\S]*?<\/tr>/,'');};}
{const _tv=SCREENS.tavern;if(_tv)SCREENS.tavern=function(){return _tv.apply(this,arguments).replace(/Challenges open when /g,'Head-to-head games open when ');};}

/* ============================== 22 Nov: Quests and Events ==============================
   The Quests tab opens on two painted buttons, Quests and Events, that animate like Fishing and Monsters in Lock In.
   Quests: today's three bounties on a board (a ring that fills, a stamp that thumps down, coins that fly to your purse),
   this week's bounties with the time to Monday's reset, and the long voyages drawn as routes on a sea chart.
   Events: what's on or next (the Christmas Event, with its Advent Calendar and its 40-tier pass), what's coming, what's past.
   Claims, quests and the advent rules are unchanged; this is the new front for them. */

/* ---------- small helpers ---------- */
function qClaimables(p){const me=G.players[p];const q=questState(p);const ws=weekStart(G.today);const out=[];
  q.daily.forEach(x=>{const k=`q_d_${G.today}_${x.id}`;if(x.prog>=x.n&&!me.claimed.has(k))out.push({k,xp:x.xp,g:x.g});});
  q.weekly.forEach(x=>{const k=`q_w_${ws}_${x.id}`;if(x.prog>=x.n&&!me.claimed.has(k))out.push({k,xp:x.xp,g:x.g});});
  q.long.forEach(x=>{const k=`q_l_${x.id}`;if(x.prog>=x.n&&!me.claimed.has(k))out.push({k,xp:x.xp,g:x.g});});return out;}
function qResetIn(){const nx=addDays(weekStart(G.today),7);const ms=Math.max(0,londonTs(nx,0)-Date.now());const d=Math.floor(ms/864e5),h=Math.floor(ms%864e5/36e5),m=Math.floor(ms%36e5/6e4);
  return d?`${d}d ${h}h`:h?`${h}h ${m}m`:`${m}m`;}
function qRing(prog,n,state){const r=18,C2=2*Math.PI*r,f=Math.max(0,Math.min(1,prog/n));
  return `<span class="qRingW ${state}"><svg class="qRing" viewBox="0 0 44 44" aria-hidden="true"><circle class="trk" cx="22" cy="22" r="${r}"/><circle class="val" cx="22" cy="22" r="${r}" stroke-dasharray="${(C2*f).toFixed(1)} ${C2.toFixed(1)}"/></svg><b class="num">${state==='cl'?'\u2713':Math.min(prog,n)}</b><small>${state==='cl'?'':'/ '+fmtN(n)}</small></span>`;}
S.justStamped=S.justStamped||new Set();
function qBounty(x,key,kind,i){const me=G.players[S.me];const done=x.prog>=x.n,cl=me.claimed.has(key);const st=cl?'cl':done?'ready':'go';
  const rot=[-.6,.5,-.3,.4,-.5][i%5];const left=Math.max(0,x.n-x.prog);
  const act=cl?`<span class="qStamp ${S.justStamped.has(key)?'thump':''}">Done</span>`
    :done?`<button class="btn primary sm qClaimBtn" data-act="qClaim" data-key="${key}" data-xp="${x.xp}" data-g="${x.g}">Claim</button>`
    :`<small class="qLeft">${fmtN(left)} to go</small>`;
  return `<div class="bounty ${st} k-${kind}" style="--rot:${rot}deg">${qRing(x.prog,x.n,st)}<div class="grow"><b>${esc(x.name)}</b><span class="qRew"><i class="xp">+${fmtN(x.xp)} XP</i><i class="gd">+${fmtN(x.g)} ${CN}</i></span></div>${act}</div>`;}

/* ---------- the sea chart of long voyages ---------- */
function qChartHtml(list){const me=G.players[S.me];const data=list.map(x=>({n:x.name,p:Math.min(x.prog,x.n),t:x.n,d:x.prog>=x.n?1:0,c:me.claimed.has(`q_l_${x.id}`)?1:0}));
  const h=data.length*46+22;return `<canvas class="qChart" width="680" height="${h*2}" style="aspect-ratio:340/${h}" data-qchart='${esc(JSON.stringify(data))}' role="img" aria-label="Long voyages: ${data.map(d=>`${d.n}, ${fmtN(d.p)} of ${fmtN(d.t)}`).join('; ')}"></canvas>`;}
function drawQChart(cv,t){let data;try{data=JSON.parse(cv.dataset.qchart);}catch(e){return;}const c=cv.getContext('2d');const W=340,H=cv.height/2;c.setTransform(2,0,0,2,0,0);c.clearRect(0,0,W,H);
  const g=c.createLinearGradient(0,0,0,H);g.addColorStop(0,'#F5E9CB');g.addColorStop(1,'#EBDBB5');c.fillStyle=g;c.fillRect(0,0,W,H);
  // faint grid and a compass rose, like an old chart
  c.strokeStyle='rgba(120,90,50,.10)';c.lineWidth=.6;for(let x=20;x<W;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,H);c.stroke();}for(let y=16;y<H;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(W,y);c.stroke();}
  const rx=W-24,ry=16;c.save();c.translate(rx,ry);c.rotate(Math.sin(t/4000)*.05);c.fillStyle='rgba(138,94,52,.55)';for(let k=0;k<4;k++){c.rotate(Math.PI/2);c.beginPath();c.moveTo(0,-9);c.lineTo(2.2,0);c.lineTo(-2.2,0);c.closePath();c.fill();}c.restore();
  c.fillStyle='rgba(120,80,40,.18)';const vg=c.createRadialGradient(W/2,H/2,Math.min(W,H)*.3,W/2,H/2,Math.max(W,H)*.75);vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(110,70,30,.22)');c.fillStyle=vg;c.fillRect(0,0,W,H);
  data.forEach((d,i)=>{const y=14+i*46;c.font='700 13px Nunito, Fredoka, sans-serif';c.textBaseline='alphabetic';c.textAlign='left';c.fillStyle='#3B2F1E';c.fillText(d.n,14,y+9);
    c.font='800 11.5px Nunito, sans-serif';c.textAlign='right';c.fillStyle=d.d?'#2F7A4E':'#6B5636';c.fillText(d.c?'claimed':`${fmtN(d.p)} / ${fmtN(d.t)}`,W-54,y+9);
    const x0=22,x1=W-46,yy=y+24;c.setLineDash([2.5,4]);c.strokeStyle='rgba(110,80,46,.65)';c.lineWidth=1.3;c.beginPath();c.moveTo(x0,yy);
    for(let x=x0;x<=x1;x+=8)c.lineTo(x,yy+Math.sin(x/22+i)*2.2);c.stroke();c.setLineDash([]);
    // the island at the end
    ell(c,x1+16,yy+3,13,4.5,'rgba(70,120,140,.25)');ell(c,x1+16,yy+1,11,4,'#E3C88E');ell(c,x1+14,yy-1,6,2.6,'#79A960');
    line(c,x1+20,yy,x1+20,yy-14,'#5A4030',1.1);const fc=d.c?'#D9A33A':d.d?'#2F9A63':'#C0392B';const wv=Math.sin(t/300+i)*1.2;poly(c,[[x1+20,yy-14],[x1+30,yy-11+wv*.3],[x1+20,yy-8]],fc);
    if(d.d&&!d.c){c.strokeStyle=`rgba(242,196,98,${.5+.4*Math.sin(t/260)})`;c.lineWidth=1.6;c.beginPath();c.ellipse(x1+16,yy+1,16,7,0,0,TAU);c.stroke();}
    // the ship, at your progress
    const f=Math.min(1,d.p/d.t),sx=x0+f*(x1-x0-8),sy=yy+Math.sin(sx/22+i)*2.2+Math.sin(t/420+i)*1.1;c.save();c.translate(sx,sy);c.rotate(Math.sin(t/520+i)*.06);
    poly(c,[[-7,-1],[7,-1],[5,3],[-5,3]],'#7A4A2C');line(c,0,-1,0,-12,'#4A3020',1);poly(c,[[.6,-11.5],[6.5,-3],[.6,-3]],'#FBF6EA');poly(c,[[-.6,-10],[-5,-3],[-.6,-3]],'#F1E8D6');poly(c,[[0,-12],[3,-11],[0,-10]],'#C0392B');c.restore();});}
(function qChartLoop(){const run=()=>{const l=document.querySelectorAll('canvas[data-qchart]');if(l.length){const t=performance.now();l.forEach(cv=>{try{drawQChart(cv,t);}catch(e){}});}requestAnimationFrame(run);};requestAnimationFrame(run);})();

/* ---------- coins that fly to the purse ---------- */
function coinFly(fromEl,n=9){try{if(!fromEl||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const to=$('#glowNum');if(!to)return;const a=fromEl.getBoundingClientRect(),b=to.getBoundingClientRect();
  const ax=a.left+a.width/2,ay=a.top+a.height/2,bx=b.left+b.width/2,by=b.top+b.height/2;
  for(let i=0;i<n;i++){const el=document.createElement('i');el.className='flyCoin';el.style.left=ax+'px';el.style.top=ay+'px';document.body.appendChild(el);
    const dx=bx-ax,dy=by-ay,sp=(i-(n-1)/2)*14,lift=-60-Math.random()*40;
    const an=el.animate([{transform:'translate(-50%,-50%) scale(.6)',opacity:0},{transform:`translate(calc(-50% + ${sp}px),calc(-50% + ${lift}px)) scale(1.1)`,opacity:1,offset:.3},{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) scale(.7)`,opacity:.9}],{duration:720+i*45,easing:'cubic-bezier(.5,0,.4,1)',delay:i*35,fill:'forwards'});
    an.onfinish=()=>{el.remove();if(i===n-1){to.classList.remove('purseBump');void to.offsetWidth;to.classList.add('purseBump');}};}}catch(e){}}

ACT.qClaim=async(d,el)=>{if(G.players[S.me].claimed.has(d.key))return;coinFly(el);S.justStamped.add(d.key);setTimeout(()=>S.justStamped.delete(d.key),1600);await ACT.claim(d);};
ACT.qClaimAll=async(d,el)=>{const list=qClaimables(S.me);if(!list.length)return;const bonus={};let xp=0,g=0;list.forEach(x=>{bonus[x.k]={xp:x.xp,g:x.g,ts:Date.now()};xp+=x.xp;g+=x.g;S.justStamped.add(x.k);});
  coinFly(el,12);setTimeout(()=>list.forEach(x=>S.justStamped.delete(x.k)),1600);
  try{await writeDay(S.me,G.today,{bonus});SFX.ach();toast(`<b>${list.length} quests claimed!</b> +${fmtN(xp)} XP, +${fmtN(g)} ${CN}. Gary has started calling you "the boss". Sarcastically.`);}catch(e){writeFail(e);}};

/* ---------- the Quests side ---------- */
function questsSideHtml(){const q=questState(S.me);const ws=weekStart(G.today);const all=qClaimables(S.me);const tx=all.reduce((a,x)=>a+x.xp,0),tg=all.reduce((a,x)=>a+x.g,0);
  const dDone=q.daily.filter(x=>x.prog>=x.n).length;const longReady=q.long.filter(x=>x.prog>=x.n&&!G.players[S.me].claimed.has(`q_l_${x.id}`));
  return `${all.length>1?`<button class="btn primary qAll" data-act="qClaimAll"><b>Claim all ${all.length}</b><small>+${fmtN(tx)} XP \u00b7 +${fmtN(tg)} ${CN}</small></button>`:''}
  <div class="card qBoard"><div class="qHead"><h2>Today's bounties</h2><small>${dDone} of ${q.daily.length} done \u00b7 ${shortDate(G.today)}</small></div>
    <div class="qList">${q.daily.map((x,i)=>qBounty(x,`q_d_${G.today}_${x.id}`,'d',i)).join('')}</div></div>
  <div class="card qBoard week"><div class="qHead"><h2>This week</h2><small>resets in <b>${qResetIn()}</b></small></div>
    <div class="qList">${q.weekly.map((x,i)=>qBounty(x,`q_w_${ws}_${x.id}`,'w',i+1)).join('')}</div></div>
  <div class="card qVoy"><div class="qHead"><h2>Long voyages</h2><small>lifetime goals</small></div>${qChartHtml(q.long)}
    ${longReady.length?`<div class="qList" style="margin-top:8px">${longReady.map((x,i)=>qBounty(x,`q_l_${x.id}`,'l',i)).join('')}</div>`:`<p class="tiny muted" style="margin:8px 2px 0">Your ship sits at your progress on each route. Reach the island to claim.</p>`}</div>`;}

/* ---------- the Events side ---------- */
const EVENT_LOOK={winter:{a:'#C8102E',b:'#1F3B63',word:'Event'},storm:{a:'#5B6C8F',b:'#1E2638',word:'Season'},spring:{a:'#E58BB0',b:'#3C4E6E',word:'Season'},summer:{a:'#F2A33A',b:'#1F5E7A',word:'Season'},autumn:{a:'#D9772B',b:'#3A2A3E',word:'Season'}};
function evDays(se){return daysBetween(se.start,se.end)+1;}
function evHeroHtml(se,mode){const lk=EVENT_LOOK[se.look]||EVENT_LOOK.winter;const today=G.today;let sub;
  if(mode==='now'){const day=daysBetween(se.start,today)+1;sub=`Day ${day} of ${evDays(se)} \u00b7 ends ${fmtDateLong(se.end)}`;}else{const d=daysBetween(today,se.start);sub=`Starts ${fmtDateLong(se.start)} \u00b7 in ${d} day${d===1?'':'s'}`;}
  return `<div class="evHero" style="--ea:${lk.a};--eb:${lk.b}"><canvas width="680" height="318" data-evart="${se.look}" aria-hidden="true"></canvas><div class="evTxt"><small>${mode==='now'?'Now on':'Next up'} \u00b7 ${esc(seLabel(se))}</small><h2>${esc(se.name)}</h2><span>${sub}</span></div>${mode!=='now'?`<div class="evCount"><b class="num">${daysBetween(today,se.start)}</b><small>days</small></div>`:''}</div>`;}
function advCalHtml(){if(typeof adventState!=='function')return '';const A=adventState();const inDec=G.today.slice(5,7)==='12';const day=+G.today.slice(8,10);
  const doors=Array.from({length:24},(_,i)=>{const k=i+1,o=A.open[k],cl=o&&A.claimed(k),p=ADVENT[k];const future=!inDec||k>day;const cls=cl?'cl':o?'ready':future?'future':'shut';
    const inside=cl?(p.item?`<canvas class="icon" data-id="${p.item}"></canvas>`:`<span>${p.joke?'\ud83c\udf84':p.feast?'\ud83c\udf57':p.xp&&!p.g?'\u2b50':'\ud83e\ude99'}</span>`):'';
    return `<button class="advDoor ${cls} c${k%3}" data-act="advDoor" data-k="${k}" aria-label="Door ${k}${cl?', opened':o?', ready to open':future?', opens '+k+' December':', still shut'}"><span class="in">${inside}</span><span class="leaf"><b>${k}</b></span></button>`;}).join('');
  const ready=Array.from({length:24},(_,i)=>i+1).filter(k=>A.open[k]&&!A.claimed(k)).length;
  return `<div class="card advCal"><div class="qHead"><h2>Advent Calendar</h2><small>${A.nClaimed} of 24 opened</small></div>
    <p class="tiny muted" style="margin:2px 0 10px">Hit the crew target to open that day's door. Weekend doors open on Monday, and every target day also opens one door you missed. Open all 24 for the Golden Reindeer figurehead.</p>
    <div class="advGrid">${doors}</div>${ready?`<button class="btn primary" style="width:100%;margin-top:10px" data-act="advOpenAll">Open ${ready} door${ready===1?'':'s'}</button>`:''}</div>`;}
function evComingHtml(list){if(!list.length)return '';return `<h3 class="evH">Coming up</h3>${list.map(se=>{const lk=EVENT_LOOK[se.look]||EVENT_LOOK.storm;const R_=SP_REWARDS[se.n]||{};
  return `<div class="card evCard" style="--ea:${lk.a}"><div class="evDot"></div><div class="grow"><small class="muted">${esc(seLabel(se))} \u00b7 ${fmtDateLong(se.start)} to ${fmtDateLong(se.end)}</small><b>${esc(se.name)}</b><p class="tiny muted">${esc(se.blurb)} Boss: ${esc(se.boss)}.</p>
    ${Object.keys(R_).length?`<div class="spCos">${Object.entries(R_).map(([t,id])=>`<div class="spCosI"><canvas class="icon" data-id="${id}"></canvas><b>${esc(ALL_ITEMS[id].name)}</b><small>Tier ${t}</small></div>`).join('')}</div>`:`<small class="muted">Rewards revealed nearer the time.</small>`}</div></div>`;}).join('')}`;}
function evPastHtml(list){return `<h3 class="evH">Past events</h3>${list.length?list.map(se=>{const st=seasonState(S.me,se);return `<div class="card evCard past"><div class="grow"><b>${esc(se.name)}</b><small class="muted">${fmtDateLong(se.start)} to ${fmtDateLong(se.end)} \u00b7 you reached tier ${st?st.tier:0}</small></div><button class="btn sm" data-act="spRecap" data-id="${se.id}">Recap</button></div>`;}).join(''):`<p class="tiny muted" style="margin:0 4px 12px">Nothing here yet. Your first event starts on ${fmtDateLong(GSEASONS[0].start)}.</p>`}`;}
function eventsSideHtml(){const today=G.today;const now=seasonAt(today);const nxt=seasonNext(today);const hero=now||nxt;
  const pass=seasonTabHtml().replace(/^<div class="pad">/,'<div class="evPass">').replace(/<small class="muted">[^<]*<\/small><h2>[^<]*<\/h2>/,'<h3 class="evPassH">The event pass</h3>').replace(/<div class="spCount">[\s\S]*?<\/div>/,'');
  const coming=GSEASONS.filter(s=>s.start>today&&s!==hero).slice(0,3);const past=GSEASONS.filter(s=>s.end<today).reverse();
  return `${hero?evHeroHtml(hero,now?'now':'next'):''}${hero&&hero.id==='frozen'?advCalHtml():''}${hero?pass:''}${evComingHtml(coming)}${evPastHtml(past)}`;}

/* ---------- the two painted buttons ---------- */
{const _dla=drawLiArt;drawLiArt=function(cv,t){const k=cv.dataset.liart;if(k!=='quests'&&k!=='events')return _dla(cv,t);const c=cv.getContext('2d');c.setTransform(cv.width/150,0,0,cv.width/150,0,0);const W2=150,H2=70;
  if(k==='quests'){c.fillStyle='#6E4A2E';c.fillRect(0,0,W2,H2);for(let y=0;y<H2;y+=10){R(c,0,y,W2,.8,'rgba(40,24,12,.35)');}for(let i=0;i<9;i++)R(c,(i*37)%W2,(i*23)%H2,5,.5,'rgba(255,220,170,.10)');
    rr(c,14,8,92,56,3,'#4A2F1C');rr(c,16,10,88,52,2,'#B88A55');for(let i=0;i<6;i++)disc(c,22+i*15,36+((i*7)%9),.9,'rgba(90,60,30,.35)');
    const notes=[[20,14,-.07],[48,12,.05],[76,15,-.04]];notes.forEach(([x,y,r],i)=>{const fl=Math.sin(t/380+i*1.7)*.03;c.save();c.translate(x+13,y);c.rotate(r+fl);rr(c,-13,0,26,34,1.5,'#F6EBCF');R(c,-9,7,18,1.6,'rgba(70,50,30,.55)');R(c,-9,12,14,1.2,'rgba(70,50,30,.35)');R(c,-9,16,16,1.2,'rgba(70,50,30,.35)');
      if(i===1){const ph=(t%2600)/2600;const s=ph<.08?2.2-ph/.08*1.2:1;const a=ph<.08?ph/.08:1;c.save();c.globalAlpha=a;c.translate(0,26);c.rotate(-.25);c.scale(s,s);c.strokeStyle='#C0392B';c.lineWidth=1.2;c.strokeRect(-8,-3.5,16,7);c.fillStyle='#C0392B';c.font='800 5px Fredoka, sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText('DONE',0,.3);c.restore();}
      else{c.strokeStyle='#2F9A63';c.lineWidth=1.4;c.beginPath();c.arc(0,25,5,-Math.PI/2,-Math.PI/2+TAU*(i===0?.66:.33));c.stroke();}
      disc(c,0,1.5,1.8,'#C0392B');disc(c,-.5,1,.6,'rgba(255,255,255,.6)');c.restore();});
    c.save();c.translate(124,40);c.rotate(-.6+Math.sin(t/900)*.05);poly(c,[[0,-24],[4,-6],[1.5,10],[-1.5,10],[-4,-6]],'#F4EFE6');line(c,0,-22,0,12,'#B9A98E',.6);R(c,-1,10,2,6,'#3B2F25');c.restore();
    for(let i=0;i<6;i++){const x=(i*29+t/50)%W2,y=10+((i*17+t/90)%50);disc(c,x,y,.5,'rgba(255,230,180,.35)');}}
  else{const g=c.createLinearGradient(0,0,0,H2);g.addColorStop(0,'#14213D');g.addColorStop(.7,'#2E4A78');g.addColorStop(.71,'#1E3A5C');g.addColorStop(1,'#0F2440');c.fillStyle=g;c.fillRect(0,0,W2,H2);
    for(let i=0;i<18;i++){const x=(i*41)%W2,y=(i*13)%34;disc(c,x,y,.45+((i*7)%3)*.15,`rgba(255,255,255,${.4+.4*Math.sin(t/500+i)})`);}
    // a firework every few seconds
    const fw=(t%3200)/3200;if(fw<.55){const fx=112,fy=20,rad=fw*30;for(let k2=0;k2<14;k2++){const an=k2/14*TAU;disc(c,fx+Math.cos(an)*rad,fy+Math.sin(an)*rad*.8,1.1*(1-fw),`hsla(${(k2*30+t/20)%360},90%,70%,${1-fw*1.6})`);}}
    // shore, tree, presents
    poly(c,[[0,54],[70,50],[96,56],[0,60]],'#EAF2F8');R(c,0,58,96,2,'#CFE0EE');
    const tx=40;[[0,30,18],[0,22,14],[0,15,10]].forEach(([o,y,w],i)=>poly(c,[[tx-w,y+12],[tx,y-6],[tx+w,y+12]],i%2?'#2F7A4E':'#256B43'));R(c,tx-2,42,4,6,'#5A3A26');
    poly(c,[[tx,6],[tx+2,10],[tx+6,10],[tx+3,13],[tx+4,17],[tx,15],[tx-4,17],[tx-3,13],[tx-6,10],[tx-2,10]],'#F2C462');
    for(let i=0;i<10;i++){const lx=tx-14+((i*11)%28),ly=18+((i*7)%24);disc(c,lx,ly,1,['#FF5A5A','#FFD45A','#7AD7FF','#FF9AE6'][i%4]);if(Math.sin(t/240+i*1.3)>.4)disc(c,lx,ly,2,'rgba(255,240,180,.25)');}
    rr(c,52,47,9,7,1,'#C8102E');R(c,55.8,47,1.4,7,'#F2C462');rr(c,62,49,7,5,1,'#2E6FB8');R(c,64.8,49,1.2,5,'#FFFFFF');rr(c,22,48,8,6,1,'#F2C462');R(c,25.3,48,1.2,6,'#C8102E');
    // a little ship on the water with a lantern
    c.save();c.translate(118,62+Math.sin(t/500)*1);poly(c,[[-12,-2],[12,-2],[9,3],[-9,3]],'#2A1E18');line(c,0,-2,0,-18,'#2A1E18',1);poly(c,[[.8,-17],[10,-4],[.8,-4]],'#E8EEF4');disc(c,-8,-5,1.4,'#FFD27A');c.restore();
    for(let i=0;i<22;i++){const x=(i*31+t/40+Math.sin(t/900+i)*6)%W2,y=(i*19+t/26)%H2;disc(c,x,y,.6+((i%3)*.25),'rgba(255,255,255,.85)');}}};}

/* the hero art is the Events painting, drawn large */
(function evArtLoop(){const run=()=>{const l=document.querySelectorAll('canvas[data-evart]');if(l.length){const t=performance.now();l.forEach(cv=>{try{const k=cv.dataset.liart;cv.dataset.liart='events';drawLiArt(cv,t);if(k)cv.dataset.liart=k;else delete cv.dataset.liart;}catch(e){}});}requestAnimationFrame(run);};requestAnimationFrame(run);})();

/* ---------- the screen ---------- */
SCREENS.quests=()=>{const tab=S.view.qtab==='season'?'events':(S.view.qtab||'quests');const q=questState(S.me);
  const claim=qClaimables(S.me).length;const dDone=q.daily.filter(x=>x.prog>=x.n).length;
  const se=seasonAt(G.today),nx=seasonNext(G.today);const un=se?unclaimedTiers(S.me,seasonState(S.me,se)).length:0;
  let adv=0;try{if(typeof adventState==='function'&&G.today.slice(5,7)==='12'){const A=adventState();adv=Array.from({length:24},(_,i)=>i+1).filter(k=>A.open[k]&&!A.claimed(k)).length;}}catch(e){}
  const evSub=se?`${esc(se.name)}: day ${daysBetween(se.start,G.today)+1} of ${evDays(se)}`:nx?`${esc(nx.label||nx.name)} in ${daysBetween(G.today,nx.start)} days`:'Nothing on right now';
  const btns=`<div class="liGroups qGroups"><button class="liGroup ${tab==='quests'?'on':''}" data-act="qTab" data-t="quests"><canvas class="liArt" width="300" height="140" data-liart="quests"></canvas><b>Quests${claim?` <span class="qBadge">${claim}</span>`:''}</b><small>${claim?`${claim} ready to claim`:`${dDone} of ${q.daily.length} done today`}</small></button><button class="liGroup ${tab==='events'?'on':''}" data-act="qTab" data-t="events"><canvas class="liArt" width="300" height="140" data-liart="events"></canvas><b>Events${un+adv?` <span class="qBadge">${un+adv}</span>`:''}</b><small>${evSub}</small></button></div>`;
  return `<div class="pad qPage">${btns}${tab==='events'?eventsSideHtml():questsSideHtml()}</div>`;};

/* the Harbour keeps a small nudge for the Advent Calendar instead of the whole grid */
if(typeof adventHtml==='function'){adventHtml=function(){if(!xmasNow()||!G)return '';const A=adventState();const ready=Array.from({length:24},(_,i)=>i+1).filter(k=>A.open[k]&&!A.claimed(k)).length;
  return `<a class="card advNudge" href="#quests" data-act="goEvents"><span class="advNudgeIco">\ud83c\udf84</span><span class="grow"><b>${ready?`${ready} advent door${ready===1?'':'s'} ready`:'Advent Calendar'}</b><small>${A.nClaimed} of 24 opened \u00b7 in Quests, Events</small></span><span class="chev">\u203a</span></a>`;};}
ACT.goEvents=()=>{S.view.qtab='events';if(location.hash==='#quests')render();else location.hash='#quests';};
// the door swings open before the reward appears
{const _ad=ACT.advDoor;ACT.advDoor=(d,el)=>{const A=adventState();const k=+d.k;if(el&&A.open[k]&&!A.claimed(k)&&!matchMedia('(prefers-reduced-motion: reduce)').matches){el.classList.add('opening');try{SND.pop&&SND.pop();}catch(e){}setTimeout(()=>_ad(d,el),520);return;}return _ad(d,el);};}

HELP.forEach(h=>{if(h[0]==='The Christmas Event and seasons'&&typeof h[1]==='string')h[1]=h[1].replace('in the Christmas Event tab of Quests','in Quests, under Events');if(h[0]==='Christmas'&&typeof h[1]==='string')h[1]=h[1].replace('The Advent Chest on the Harbour has 24 doors','The Advent Calendar (Quests, then Events) has 24 doors');});

/* ============================== 22 Nov: the client pipeline (part 1) ==============================
   Prospects live in Supabase (hl_prospects, hl_prospect_events), readable only by Sam's and James's logins, and sync
   live between you. No client details are in this file or the bundle. Opened from the banner at the top of More (and
   #pipeline). Part 1: the Board (stages, cards, quick add, swipe to move, full edit, history), Clients, and the
   import check. Part 2 adds Overview, Schedule, Growth, reminders, game taps and the Harbour button. */
const PIPE_STAGES=[
  {id:'video_needed',name:'Video needed',col:'#C0392B',hint:'Record a video for these'},
  {id:'video_made',name:'Video made',col:'#8E5BD0',hint:'Video ready, not sent yet'},
  {id:'messaged',name:'Messaged',col:'#3E8DDB',hint:'DM or email sent'},
  {id:'followed_up',name:'Followed up',col:'#2E8C88',hint:'Nudged at least once'},
  {id:'talking',name:'Talking',col:'#2F9A63',hint:'They replied'},
  {id:'meeting',name:'Meeting',col:'#D9902B',hint:'Booked or held'},
  {id:'quote_sent',name:'Quote sent',col:'#B8642A',hint:'Waiting on a yes'},
  {id:'client',name:'Client',col:'#A9781C',hint:'Won'}];
const PIPE_EXITS=[{id:'not_now',name:'Not now',col:'#7A8794',hint:'Comes back on a set date'},{id:'no_response',name:'No response',col:'#5E6A76',hint:'Kept for later'}];
const PIPE_ALL=[...PIPE_STAGES,...PIPE_EXITS];const PIPE_BY=Object.fromEntries(PIPE_ALL.map(s=>[s.id,s]));
const PIPE_PRODUCTS=['Websites','Full Package','Social Media Management','Branding','Email & SMS','Paid Adverts'];
const PIPE_RAG={likely:{n:'Likely',c:'#2F9A63'},maybe:{n:'Maybe',c:'#D9902B'},unlikely:{n:'Unlikely',c:'#C0392B'}};
const PIPE={rows:[],ready:false,err:null,src:null,ev:{},undo:null,allEv:null};

/* ---------- data ---------- */
const pLocal={get(){try{return JSON.parse(localStorage.getItem('hl_pipe_v1')||'[]');}catch(e){return [];}},set(r){try{localStorage.setItem('hl_pipe_v1',JSON.stringify(r));}catch(e){}}};
function pipeStart(){if(PIPE.src)return;if(S.sb){PIPE.src='supa';pipeLoad();
    try{S.sb.channel('hl-pipe').on('postgres_changes',{event:'*',schema:'public',table:'hl_prospects'},p=>{if(p.eventType==='DELETE'){PIPE.rows=PIPE.rows.filter(r=>r.id!==(p.old&&p.old.id));}else if(p.new){const i=PIPE.rows.findIndex(r=>r.id===p.new.id);if(i>=0)PIPE.rows[i]=p.new;else PIPE.rows.push(p.new);}pipeRefresh();}).subscribe();}catch(e){console.warn('pipe sub',e);}
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)pipeLoad();});}
  else{PIPE.src='local';PIPE.rows=pLocal.get();PIPE.ready=true;}}
async function pipeLoad(){try{const {data,error}=await S.sb.from('hl_prospects').select('*').order('sort',{ascending:true}).limit(5000);if(error)throw error;PIPE.rows=data||[];PIPE.ready=true;PIPE.err=null;}catch(e){PIPE.err=(e&&e.message)||'Could not load the pipeline';PIPE.ready=true;}pipeRefresh();}
function pipeRefresh(){if(S.screen==='pipeline'||S.screen==='more')render();}
function pipeSaveLocal(){if(PIPE.src==='local')pLocal.set(PIPE.rows);}
async function pipeLog(id,kind,detail){const ev={prospect_id:id,by:S.me,kind,detail:detail||{},at:new Date().toISOString()};(PIPE.ev[id]=PIPE.ev[id]||[]).unshift(ev);if(PIPE.allEv)PIPE.allEv.unshift(ev);
  if(PIPE.src==='supa'){try{await S.sb.from('hl_prospect_events').insert({prospect_id:id,by:S.me,kind,detail:detail||{}});}catch(e){}}else{try{const k='hl_pipe_ev_'+id;const l=JSON.parse(localStorage.getItem(k)||'[]');l.unshift(ev);localStorage.setItem(k,JSON.stringify(l.slice(0,200)));}catch(e){}}}
async function pipePatch(id,patch,kind,detail){const r=PIPE.rows.find(x=>x.id===id);if(!r)return;const prev={};Object.keys(patch).forEach(k=>prev[k]=r[k]);Object.assign(r,patch,{updated_by:S.me,updated_at:new Date().toISOString()});pipeSaveLocal();pipeRefresh();
  if(PIPE.src==='supa'){const {error}=await S.sb.from('hl_prospects').update({...patch,updated_by:S.me}).eq('id',id);if(error){Object.assign(r,prev);pipeRefresh();toast(`<b>Couldn't save.</b> ${esc(error.message||'')}`,'joke');return false;}}
  if(kind)pipeLog(id,kind,detail);return prev;}
async function pipeInsert(o){const id=(crypto.randomUUID&&crypto.randomUUID())||uid();const st=o.stage||'video_needed';const sort=Math.max(0,...PIPE.rows.filter(r=>r.stage===st).map(r=>r.sort||0))+1;
  const r=Object.assign({id,business:'',owner:S.me,stage:st,products:[],tags:[],links:[],priority:false,follow_ups:0,meeting_held:false,sort,source:'Added in the game',created_at:new Date().toISOString(),updated_by:S.me},o);
  PIPE.rows.push(r);pipeSaveLocal();pipeRefresh();
  if(PIPE.src==='supa'){const {error}=await S.sb.from('hl_prospects').insert(r);if(error){PIPE.rows=PIPE.rows.filter(x=>x.id!==id);pipeRefresh();toast(`<b>Couldn't add it.</b> ${esc(error.message||'')}`,'joke');return null;}}
  pipeLog(id,'created',{stage:st});return r;}
async function pipeRemove(id){const r=PIPE.rows.find(x=>x.id===id);if(!r)return;PIPE.rows=PIPE.rows.filter(x=>x.id!==id);pipeSaveLocal();pipeRefresh();
  if(PIPE.src==='supa'){const {error}=await S.sb.from('hl_prospects').delete().eq('id',id);if(error){PIPE.rows.push(r);pipeRefresh();toast(`<b>Couldn't remove it.</b> ${esc(error.message||'')}`,'joke');}}else{try{localStorage.removeItem('hl_pipe_ev_'+id);}catch(e){}}}
async function pipeEvents(id){if(PIPE.src==='supa'){try{const {data}=await S.sb.from('hl_prospect_events').select('*').eq('prospect_id',id).order('at',{ascending:false}).limit(100);PIPE.ev[id]=data||[];}catch(e){}}
  else{try{PIPE.ev[id]=JSON.parse(localStorage.getItem('hl_pipe_ev_'+id)||'[]');}catch(e){PIPE.ev[id]=[];}}return PIPE.ev[id]||[];}

/* ---------- helpers ---------- */
const PAV={};const pAvatar=p=>{const k=p+'|'+JSON.stringify((S.players[p]||{}).look||{});if(!PAV[k])PAV[k]=avatarCanvas(p);return PAV[k];};
const pIni=s=>{const w=String(s||'?').replace(/[^\p{L}\p{N} &]/gu,' ').split(/\s+/).filter(x=>x&&x!=='&'&&!/^(the|and|of)$/i.test(x));return ((w[0]||'?')[0]+((w[1]||'')[0]||'')).toUpperCase();};
const pMoney=n=>n==null||n===''?'':'\u00a3'+fmtN(Math.round(+n));
const pVal=r=>r.deal_value!=null?+r.deal_value:r.quote_value!=null?+r.quote_value:null;
// when a prospect is next due: the date you set, else a sensible gap after the last contact (so the imported sheet has dates too)
const P_GAP={messaged:5,followed_up:5,talking:3,quote_sent:4};
function pDueDate(r){if(r.stage==='not_now')return r.return_on||null;if(r.stage==='client'||r.stage==='no_response')return null;if(r.stage==='meeting'&&!r.meeting_held&&r.meeting_at)return r.meeting_at;if(r.next_due)return r.next_due;const g=P_GAP[r.stage];return g&&r.last_contact?addDays(r.last_contact,g):null;}
function pDue(r){const d=pDueDate(r);if(!d)return null;const t=G.today;return{d,cls:d<addDays(t,-30)?'stale':d<t?'over':d===t?'today':'later'};}
function pDueN(rows){return (rows||PIPE.rows).filter(r=>{const d=pDue(r);return d&&(d.cls==='over'||d.cls==='today');}).length;}
const pShortD=d=>{try{return new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short'});}catch(e){return d;}};
const pHost=u=>{try{return new URL(/^https?:/.test(u)?u:'https://'+u).hostname.replace(/^www\./,'');}catch(e){return u;}};
function pFilter(rows){const ow=S.view.powner||'all';return rows.filter(r=>ow==='all'||r.owner===ow);}
function pStageRows(st){return pFilter(PIPE.rows.filter(r=>r.stage===st)).sort((a,b)=>(b.priority?1:0)-(a.priority?1:0)||(a.sort||0)-(b.sort||0));}
function pSearchKey(r){return [r.business,r.contact,r.insta,r.website,r.niche,r.location,(r.products||[]).join(' '),r.notes].filter(Boolean).join(' ').toLowerCase();}

/* ---------- the sliding pill tab bar (the reel's stretchy motion: the front edge leads, the back edge catches up) ---------- */
function pillNav(id,tabs,cur,act){return `<nav class="pillNav" id="${id}" data-cur="${cur}">${tabs.map(([k,n,b])=>`<button class="${k===cur?'on':''}" data-act="${act}" data-t="${k}">${n}${b?` <span class="qBadge">${b}</span>`:''}</button>`).join('')}<i class="pillInd" aria-hidden="true"></i></nav>`;}
const PILL_POS={};
function pillPlace(nav){const on=nav.querySelector('button.on');const ind=nav.querySelector('.pillInd');if(!on||!ind)return;const nr=nav.getBoundingClientRect(),br=on.getBoundingClientRect();const L=br.left-nr.left+nav.scrollLeft,Rr=nr.width-(br.right-nr.left)-nav.scrollLeft;
  const prev=PILL_POS[nav.id];ind.style.transition='none';if(prev){ind.style.left=prev.L+'px';ind.style.right=prev.R+'px';void ind.offsetWidth;const right=L>prev.L;
    ind.style.transition=right?'left .42s cubic-bezier(.5,0,.2,1) .06s,right .26s cubic-bezier(.4,0,.2,1)':'left .26s cubic-bezier(.4,0,.2,1),right .42s cubic-bezier(.5,0,.2,1) .06s';}
  ind.style.left=L+'px';ind.style.right=Rr+'px';PILL_POS[nav.id]={L,R:Rr};}

/* ---------- cards ---------- */
function pCard(r){const st=PIPE_BY[r.stage]||PIPE_STAGES[0];const due=pDue(r);const v=pVal(r);const rag=PIPE_RAG[r.rag];
  const prod=(r.products||[]).map(p=>p==='Social Media Management'?'Social':p==='Full Package'?'Full package':p).join(' \u00b7 ');
  const nextSt=PIPE_STAGES[PIPE_STAGES.findIndex(s=>s.id===r.stage)+1];
  return `<div class="pCard ${r.priority?'prio':''}" data-act="pOpen" data-id="${r.id}" data-q="${esc(pSearchKey(r))}" style="--sc:${st.col}">
    <span class="pIni">${esc(pIni(r.business))}</span>
    <div class="grow"><b>${esc(r.business||'Unnamed')}</b><small>${esc([r.contact,prod].filter(Boolean).join(' \u00b7 ')||'No details yet')}</small>
      <div class="pMeta">${rag?`<span class="pRag" style="--rc:${rag.c}">${rag.n}</span>`:''}${r.priority?'<span class="pTag hot">Priority</span>':''}${v!=null?`<span class="pTag">${pMoney(v)}${r.deal_period==='monthly'?'/mo':''}</span>`:''}${r.follow_ups?`<span class="pTag">${r.follow_ups}\u00d7 followed up</span>`:''}${due?`<span class="pDue ${due.cls}">${due.cls==='stale'?`Gone quiet${r.last_contact?' \u00b7 '+pShortD(r.last_contact):''}`:(due.cls==='over'?'Overdue \u00b7 ':due.cls==='today'?'Today \u00b7 ':'')+pShortD(due.d)}</span>`:''}${r.review?'<span class="pTag chk">Check</span>':''}</div></div>
    <div class="pSide"><img class="pOwner" alt="${esc(pname(r.owner))}" src="${pAvatar(r.owner)}">${nextSt?`<button class="pNext" data-act="pNext" data-id="${r.id}" aria-label="Move to ${esc(nextSt.name)}" title="Move to ${esc(nextSt.name)}">\u203a</button>`:''}</div></div>`;}

/* ---------- the screen ---------- */
SCREENS.pipeline=()=>{pipeStart();const tab=S.view.ptab||'overview';
  if(!PIPE.ready)return `<div class="pad pipePage"><div class="card pEmpty"><h2>Pipeline</h2><p class="muted">Loading your prospects\u2026</p></div></div>`;
  const act=PIPE.rows.filter(r=>PIPE_STAGES.some(s=>s.id===r.stage)&&r.stage!=='client');const cl=PIPE.rows.filter(r=>r.stage==='client');
  const mrr=cl.filter(r=>r.deal_period==='monthly').reduce((a,r)=>a+(+r.deal_value||0),0);const due=pDueN();const chk=PIPE.rows.filter(r=>r.review).length;
  const head=`<div class="pipeTop"><div class="grow"><h2>Pipeline</h2><small>${act.length} active \u00b7 ${cl.length} client${cl.length===1?'':'s'}${mrr?` \u00b7 ${pMoney(mrr)} a month`:''}${due?` \u00b7 <b data-act="pTab" data-t="schedule" class="pDueLink">${due} due</b>`:''}</small></div><button class="btn primary pAddBtn" data-act="pAdd">+ New</button></div>
    ${PIPE.err?`<div class="card pErr"><b>Couldn't reach the pipeline.</b><small>${esc(PIPE.err)}</small><button class="btn sm" data-act="pReload">Try again</button></div>`:''}
    ${pillNav('pTabs',[['overview','Overview'],['board','Board'],['schedule','Schedule',due],['clients','Clients'],['growth','Growth'],...(chk?[['review','Check import',chk]]:[])],tab,'pTab')}`;
  const body={overview:()=>pOverviewHtml(),schedule:()=>pScheduleHtml(),growth:()=>pGrowthHtml(),clients:()=>pClientsHtml(cl),review:()=>pReviewHtml()}[tab];
  return `<div class="pad pipePage">${head}${body?body():pBoardHtml()}</div>`;};
function pBoardHtml(){const cur=S.view.pstage||'video_needed';const st=PIPE_BY[cur];const rows=pStageRows(cur);const tot=rows.reduce((a,r)=>a+(pVal(r)||0),0);const ow=S.view.powner||'all';
  const strip=`<div class="pStrip" role="tablist">${PIPE_ALL.map((s,i)=>`${i===PIPE_STAGES.length?'<span class="pStripGap"></span>':''}<button class="pStage ${s.id===cur?'on':''}" role="tab" aria-selected="${s.id===cur}" data-act="pStage" data-s="${s.id}" style="--sc:${s.col}"><i></i>${esc(s.name)}<b>${pFilter(PIPE.rows.filter(r=>r.stage===s.id)).length}</b></button>`).join('')}</div>`;
  return `<div class="pTools"><input class="pSearch" type="search" placeholder="Search name, contact, product or notes" aria-label="Search the pipeline" value="${esc(S.view.pq||'')}" data-pq><div class="seg mini pOwn">${[['all','Everyone'],['sam',pnameRaw('sam')],['james',pnameRaw('james')]].map(([k,n])=>`<button class="${ow===k?'on':''}" data-act="pOwner" data-o="${k}">${esc(n)}</button>`).join('')}</div></div>
   ${strip}
   <div class="pCol" style="--sc:${st.col}"><div class="pColHead"><div class="grow"><b>${esc(st.name)}</b><small>${rows.length} \u00b7 ${esc(st.hint)}${tot?` \u00b7 ${pMoney(tot)}`:''}</small></div><button class="btn sm" data-act="pAdd" data-s="${cur}">+ Add here</button></div>
     <div class="pList">${rows.length?rows.map(pCard).join(''):`<p class="pNone">Nothing in ${esc(st.name)}${ow!=='all'?` for ${esc(pnameRaw(ow))}`:''}.</p>`}</div>
     <p class="pHint">Swipe a card right to move it on, or tap it to edit.</p></div>
   <div class="pAllRes" hidden></div>`;}
function pClientsHtml(cl){const mrr=cl.filter(r=>r.deal_period==='monthly').reduce((a,r)=>a+(+r.deal_value||0),0),one=cl.filter(r=>r.deal_period!=='monthly').reduce((a,r)=>a+(+r.deal_value||0),0);
  return `<div class="pTotals"><div><b class="num">${pMoney(mrr)}</b><small>a month in retainers</small></div><div><b class="num">${pMoney(one)}</b><small>one-off work</small></div><div><b class="num">${cl.length}</b><small>clients</small></div></div>
   <div class="pList">${cl.length?cl.sort((a,b)=>(b.deal_value||0)-(a.deal_value||0)).map(r=>`<div class="pCard client" data-act="pOpen" data-id="${r.id}" style="--sc:${PIPE_BY.client.col}"><span class="pIni">${esc(pIni(r.business))}</span><div class="grow"><b>${esc(r.business)}</b><small>${esc([r.contact,(r.products||[]).join(' \u00b7 ')].filter(Boolean).join(' \u00b7 ')||'No details yet')}</small>
     <div class="pMeta">${r.deal_value!=null?`<span class="pTag gold">${pMoney(r.deal_value)}${r.deal_period==='monthly'?' a month':' one-off'}</span>`:''}${r.editor?`<span class="pTag">Editor: ${esc(r.editor)}</span>`:''}${r.website?`<a class="pTag link" href="${esc(/^https?:/.test(r.website)?r.website:'https://'+r.website)}" target="_blank" rel="noopener">${esc(pHost(r.website))}</a>`:''}</div></div><div class="pSide"><img class="pOwner" alt="" src="${pAvatar(r.owner)}"></div></div>`).join(''):'<p class="pNone">No clients yet. The first one gets fireworks.</p>'}</div>`;}
function pReviewHtml(){const rows=PIPE.rows.filter(r=>r.review);return `<div class="card pRev"><h3>Check the import</h3><p class="tiny muted">These rows from your sheet need a quick look. Open one to fix it, or mark it as right.</p></div>
  <div class="pList">${rows.map(r=>`<div class="pCard rev" style="--sc:${(PIPE_BY[r.stage]||PIPE_STAGES[0]).col}"><span class="pIni">${esc(pIni(r.business))}</span><div class="grow"><b>${esc(r.business)}</b><small>${esc(r.review)}</small><div class="pMeta"><span class="pTag">${esc((PIPE_BY[r.stage]||{}).name||r.stage)}</span></div></div>
    <div class="pRevBtns"><button class="btn sm" data-act="pOpen" data-id="${r.id}">Open</button><button class="btn sm primary" data-act="pOk" data-id="${r.id}">Looks right</button></div></div>`).join('')||'<p class="pNone">All checked. Nice work.</p>'}</div>`;}

/* ---------- moving cards ---------- */
async function pMove(id,to,opts){const r=PIPE.rows.find(x=>x.id===id);if(!r||r.stage===to)return;const from=r.stage;const t=G.today;const patch={stage:to};
  if(to==='messaged'||to==='followed_up'){patch.last_contact=t;if(!r.next_due||r.next_due<=t)patch.next_due=addDays(t,5);}
  if(to==='followed_up')patch.follow_ups=(r.follow_ups||0)+1;if(to==='client'&&!r.won_at)patch.won_at=t;if(to==='video_made'&&from==='video_needed')patch.priority=false;
  if(to==='not_now'){patch.return_on=(opts&&opts.ret)||r.return_on||addDays(t,30);}
  const sort=Math.max(0,...PIPE.rows.filter(x=>x.stage===to).map(x=>x.sort||0))+1;patch.sort=sort;
  const prev=await pipePatch(id,patch,'stage',{from,to});if(prev===false)return;PIPE.undo={id,prev,to};try{SND.pop&&SND.pop();}catch(e){}
  if(to==='client'){try{fireworks(2600);SND.level&&SND.level();}catch(e){}}
  const gk=P_GAME[to];const offer=gk&&!(r.tags||[]).includes('game:'+gk)&&!(opts&&opts.quiet);
  toast(`<b>${esc(r.business)}</b> moved to ${esc(PIPE_BY[to].name)}.${typeof pQuip==='function'&&pQuip(to)?` <i class="pQuip">${esc(pQuip(to))}</i>`:''}${offer?` <button class="tLink gold" data-act="pGame" data-k="${gk}" data-id="${r.id}">Count it: +${fmtN(KINDS[gk].xp)} XP</button>`:''} <button class="tLink" data-act="pUndo">Undo</button>`,'',offer?8000:5000);}
ACT.pNext=(d,el)=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;const i=PIPE_STAGES.findIndex(s=>s.id===r.stage);const nx=PIPE_STAGES[i+1];if(!nx)return;const card=el&&el.closest('.pCard');
  if(card&&!matchMedia('(prefers-reduced-motion: reduce)').matches){card.classList.add('sailOff');setTimeout(()=>pMove(r.id,nx.id),260);}else pMove(r.id,nx.id);};
ACT.pUndo=async()=>{const u=PIPE.undo;if(!u)return;PIPE.undo=null;await pipePatch(u.id,u.prev,'stage',{from:u.to,to:u.prev.stage,undo:true});};
ACT.pStage=d=>{S.view.pstage=d.s;render();};
ACT.pTab=d=>{S.view.ptab=d.t;render();};
ACT.pOwner=d=>{S.view.powner=d.o;render();};
ACT.pReload=()=>{PIPE.ready=false;render();pipeLoad();};
ACT.pOk=async d=>{await pipePatch(d.id,{review:null},'checked',{});};

/* ---------- quick add ---------- */
function pParse(txt){const s=String(txt||'').trim();const o={};if(!s)return o;
  const ig=s.match(/instagram\.com\/([A-Za-z0-9_.]+)/i)||s.match(/^@([A-Za-z0-9_.]+)$/);
  const nice=w=>w.replace(/[._-]+/g,' ').replace(/\b(uk|co|ltd)\b$/i,'').trim().replace(/\s+/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
  if(ig){o.insta=ig[1];o.business=nice(ig[1]);return o;}
  if(/^(https?:\/\/)?([\w-]+\.)+[a-z]{2,}(\/\S*)?$/i.test(s)){const h=pHost(s);o.website=/^https?:/.test(s)?s:'https://'+s;o.business=nice(h.split('.')[0]);return o;}
  o.business=s;return o;}
ACT.pAdd=d=>{const st=(d&&d.s)||S.view.pstage||'video_needed';
  openModal(`<h2>New prospect</h2><p class="muted" style="margin:2px 0 10px">Paste a website or Instagram link, or type the business name. Everything else can wait.</p>
   <label class="f">Link or name<input id="pqa" placeholder="instagram.com/\u2026 or www.\u2026 or a name" autocomplete="off"></label>
   <div id="pqaPrev" class="pQaPrev tiny muted">It'll go into <b>${esc(PIPE_BY[st].name)}</b>, owned by ${esc(pnameRaw(S.me))}.</div>
   <label class="f">Stage<select id="pqaSt">${PIPE_ALL.map(s=>`<option value="${s.id}" ${s.id===st?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>
   <div class="row" style="justify-content:flex-end;gap:8px;margin-top:12px"><button class="btn ghost" data-act="wnClose">Cancel</button><button class="btn primary" data-act="pAddGo">Add</button></div>`);
  setTimeout(()=>{const i=$('#pqa');if(!i)return;i.focus();i.addEventListener('input',()=>{const o=pParse(i.value);$('#pqaPrev').innerHTML=o.business?`Adds <b>${esc(o.business)}</b>${o.insta?` (@${esc(o.insta)})`:o.website?` (${esc(pHost(o.website))})`:''}. You can rename it after.`:'';});i.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();ACT.pAddGo();}});},30);};
ACT.pAddGo=async()=>{const o=pParse(($('#pqa')||{}).value);if(!o.business){const i=$('#pqa');if(i){i.focus();i.classList.add('shake');setTimeout(()=>i.classList.remove('shake'),400);}return;}
  const st=($('#pqaSt')||{}).value||'video_needed';closeModal();const r=await pipeInsert({...o,stage:st});if(!r)return;S.view.ptab='board';S.view.pstage=st;if(location.hash!=='#pipeline')location.hash='#pipeline';else render();
  toast(`<b>${esc(r.business)}</b> added to ${esc(PIPE_BY[st].name)}. Tap it to add details.`);};

/* ---------- the full card: edit everything, see the history ---------- */
const pv=(id)=>{const e=$('#'+id);return e?e.value.trim():'';};
ACT.pOpen=async d=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;const st=PIPE_BY[r.stage]||PIPE_STAGES[0];const opt=(v,n,cur)=>`<option value="${v}" ${v===cur?'selected':''}>${n}</option>`;
  const fld=(id,lab,val,type='text',ph='')=>`<label class="f">${lab}<input id="${id}" type="${type}" value="${esc(val==null?'':val)}" placeholder="${esc(ph)}"></label>`;
  openModal(`<div class="pDet" style="--sc:${st.col}" data-id="${r.id}">
   <div class="pDetHead"><span class="pIni big">${esc(pIni(r.business))}</span><div class="grow"><input id="pf_business" class="pBigIn" value="${esc(r.business||'')}" aria-label="Business name"><small>${r.created_at?`Added ${pShortD(String(r.created_at).slice(0,10))}`:''}${r.source?` \u00b7 ${esc(r.source)}`:''}</small></div></div>
   ${r.review?`<div class="pRevNote"><b>Check:</b> ${esc(r.review)}<label class="pChk"><input type="checkbox" id="pf_reviewed" checked> Mark as checked when I save</label></div>`:''}
   <div class="pGrid2"><label class="f">Stage<select id="pf_stage">${PIPE_ALL.map(s=>opt(s.id,s.name,r.stage)).join('')}</select></label>
     <label class="f">Owner<select id="pf_owner">${['sam','james'].map(p=>opt(p,esc(pnameRaw(p)),r.owner)).join('')}</select></label></div>
   <div class="pGrid2"><label class="f">How likely<select id="pf_rag">${opt('','Not set',r.rag||'')}${Object.entries(PIPE_RAG).map(([k,v])=>opt(k,v.n,r.rag)).join('')}</select></label>
     <label class="f pChkF"><span>Priority</span><input type="checkbox" id="pf_priority" ${r.priority?'checked':''}></label></div>
   <div class="f"><span>Products</span><div class="pProds">${PIPE_PRODUCTS.map(p=>`<label class="pProd"><input type="checkbox" value="${esc(p)}" ${(r.products||[]).includes(p)?'checked':''}> ${esc(p)}</label>`).join('')}</div></div>
   <h4 class="pSec">Who</h4>
   <div class="pGrid2">${fld('pf_contact','Contact',r.contact)}${fld('pf_niche','Niche',r.niche,'text','e.g. Interiors')}</div>
   <div class="pGrid2">${fld('pf_website','Website',r.website,'url','https://')}${fld('pf_insta','Instagram',r.insta,'text','handle')}</div>
   <div class="pGrid2">${fld('pf_email','Email',r.email,'email')}${fld('pf_phone','Phone',r.phone,'tel')}</div>
   ${fld('pf_location','Location',r.location)}
   <h4 class="pSec">Links</h4>
   <div class="pLinkRow">${fld('pf_video_url','Video (Loom)',r.video_url,'url','https://www.loom.com/share/\u2026')}${r.video_url?`<a class="btn sm" href="${esc(r.video_url)}" target="_blank" rel="noopener">Play</a>`:''}</div>
   <div class="pLinkRow">${fld('pf_quote_url','Quote',r.quote_url,'url','https://')}${r.quote_url?`<a class="btn sm" href="${esc(r.quote_url)}" target="_blank" rel="noopener">Open</a>`:''}</div>
   <div class="pOpenRow">${r.website?`<a class="btn sm" href="${esc(/^https?:/.test(r.website)?r.website:'https://'+r.website)}" target="_blank" rel="noopener">Website</a>`:''}${r.insta?`<a class="btn sm" href="https://www.instagram.com/${esc(r.insta)}/" target="_blank" rel="noopener">Instagram</a>`:''}${r.email?`<a class="btn sm" href="mailto:${esc(r.email)}">Email</a>`:''}</div>
   <h4 class="pSec">Money</h4>
   <div class="pGrid2">${fld('pf_quote_value','Quote value (\u00a3)',r.quote_value,'number')}${fld('pf_deal_value','Deal value (\u00a3)',r.deal_value,'number')}</div>
   <div class="pGrid2"><label class="f">Paid<select id="pf_deal_period">${opt('','Not set',r.deal_period||'')}${opt('monthly','Monthly',r.deal_period)}${opt('one_off','One-off',r.deal_period)}</select></label>${fld('pf_editor','Looked after by',r.editor)}</div>
   <h4 class="pSec">Dates</h4>
   <div class="pGrid2">${fld('pf_last_contact','Last contact',r.last_contact,'date')}<label class="f">Follow-ups<input id="pf_follow_ups" type="number" min="0" value="${r.follow_ups||0}"></label></div>
   <div class="pGrid2">${fld('pf_meeting_at','Meeting',r.meeting_at,'date')}<label class="f pChkF"><span>Meeting held</span><input type="checkbox" id="pf_meeting_held" ${r.meeting_held?'checked':''}></label></div>
   <div class="pGrid2">${fld('pf_next_action','Next action',r.next_action,'text','e.g. Send the quote')}${fld('pf_next_due','Due',r.next_due,'date')}</div>
   ${fld('pf_return_on','Bring back on (for Not now)',r.return_on,'date')}
   <label class="f">Notes<textarea id="pf_notes" rows="3">${esc(r.notes||'')}</textarea></label>
   <h4 class="pSec">History</h4><div class="pHist" id="pHist"><small class="muted">Loading\u2026</small></div>
   <div class="pDetBtns"><button class="btn ghost danger" data-act="pDel" data-id="${r.id}">Remove</button><span class="grow"></span><button class="btn ghost" data-act="wnClose">Close</button><button class="btn primary" data-act="pSave" data-id="${r.id}">Save</button></div></div>`);
  const ev=await pipeEvents(r.id);const h=$('#pHist');if(h)h.innerHTML=ev.length?ev.map(e=>`<div class="pEv"><b>${esc(pnameRaw(e.by||'')||'Someone')}</b> ${esc(pEvText(e))}<small>${pWhen(e.at)}</small></div>`).join(''):'<small class="muted">Nothing yet. Changes show up here.</small>';};
function pEvText(e){const d=e.detail||{};if(e.kind==='stage')return d.undo?`undid the move back to ${(PIPE_BY[d.to]||{}).name||d.to}`:`moved it from ${(PIPE_BY[d.from]||{}).name||d.from} to ${(PIPE_BY[d.to]||{}).name||d.to}`;if(e.kind==='created')return `added it to ${(PIPE_BY[d.stage]||{}).name||'the pipeline'}`;if(e.kind==='edit')return `edited ${(d.fields||[]).slice(0,4).join(', ')}${(d.fields||[]).length>4?'\u2026':''}`;if(e.kind==='checked')return 'checked the imported details';if(e.kind==='import')return 'imported it from the sheet';return e.kind;}
function pWhen(at){try{const d=new Date(at);return d.toLocaleDateString('en-GB',{day:'numeric',month:'short'})+' '+d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});}catch(e){return '';}}
ACT.pSave=async d=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;const num=v=>v===''?null:+v;const dt=v=>v||null;
  const patch={business:pv('pf_business')||r.business,owner:pv('pf_owner')||r.owner,rag:pv('pf_rag')||null,priority:!!($('#pf_priority')||{}).checked,
    products:[...document.querySelectorAll('.pProds input:checked')].map(i=>i.value),contact:pv('pf_contact')||null,niche:pv('pf_niche')||null,website:pv('pf_website')||null,insta:(pv('pf_insta')||'').replace(/^@/,'').replace(/.*instagram\.com\//i,'').replace(/\/.*$/,'')||null,
    email:pv('pf_email')||null,phone:pv('pf_phone')||null,location:pv('pf_location')||null,video_url:pv('pf_video_url')||null,quote_url:pv('pf_quote_url')||null,
    quote_value:num(pv('pf_quote_value')),deal_value:num(pv('pf_deal_value')),deal_period:pv('pf_deal_period')||null,editor:pv('pf_editor')||null,
    last_contact:dt(pv('pf_last_contact')),follow_ups:Math.max(0,parseInt(pv('pf_follow_ups')||'0',10)||0),meeting_at:dt(pv('pf_meeting_at')),meeting_held:!!($('#pf_meeting_held')||{}).checked,
    next_action:pv('pf_next_action')||null,next_due:dt(pv('pf_next_due')),return_on:dt(pv('pf_return_on')),notes:pv('pf_notes')||null};
  if(r.review&&($('#pf_reviewed')||{}).checked)patch.review=null;
  const newStage=pv('pf_stage');const changed=Object.keys(patch).filter(k=>JSON.stringify(patch[k]??null)!==JSON.stringify(r[k]??null));
  if(changed.length){const ok=await pipePatch(r.id,patch,'edit',{fields:changed.map(k=>k.replace(/_/g,' '))});if(ok===false)return;}
  closeModal();if(newStage&&newStage!==r.stage)await pMove(r.id,newStage);else if(changed.length)toast(`<b>Saved.</b> ${esc(r.business)} is up to date.`);};
ACT.pDel=d=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;openModal(`<h2>Remove ${esc(r.business)}?</h2><p class="muted">This deletes the prospect and its history for both of you. It can't be undone. If they've just gone quiet, Not now or No response keeps them for later.</p>
  <div class="row" style="justify-content:flex-end;gap:8px;margin-top:12px"><button class="btn ghost" data-act="pOpen" data-id="${r.id}">Keep it</button><button class="btn danger" data-act="pDelGo" data-id="${r.id}">Remove for good</button></div>`);};
ACT.pDelGo=async d=>{const r=PIPE.rows.find(x=>x.id===d.id);closeModal();await pipeRemove(d.id);if(r)toast(`<b>${esc(r.business)}</b> removed.`);};

/* ---------- search filters cards in place (no re-render, so typing stays smooth) ---------- */
document.addEventListener('input',e=>{const i=e.target.closest&&e.target.closest('[data-pq]');if(!i)return;S.view.pq=i.value;pApplySearch();});
function pApplySearch(){const q=(S.view.pq||'').trim().toLowerCase();const box=$('.pAllRes'),col=$('.pCol'),strip=$('.pStrip');if(!box||!col)return;
  if(!q){box.hidden=true;box.innerHTML='';col.hidden=false;if(strip)strip.hidden=false;return;}
  const hits=pFilter(PIPE.rows).filter(r=>pSearchKey(r).includes(q));col.hidden=true;if(strip)strip.hidden=true;box.hidden=false;
  box.innerHTML=`<p class="pHint" style="margin:6px 4px">${hits.length} match${hits.length===1?'':'es'} across every stage</p><div class="pList">${hits.map(r=>pCard(r).replace('<div class="grow"><b>',`<div class="grow"><em class="pStTag" style="--sc:${(PIPE_BY[r.stage]||{}).col}">${esc((PIPE_BY[r.stage]||{}).name||'')}</em><b>`)).join('')||'<p class="pNone">Nothing matches.</p>'}</div>`;}

/* ---------- swipe a card right to move it on ---------- */
(function pSwipe(){let st=null;
  document.addEventListener('pointerdown',e=>{const c=e.target.closest&&e.target.closest('.pCard');if(!c||e.target.closest('button,a,input')||!c.closest('.pCol,.pAllRes'))return;st={c,x:e.clientX,y:e.clientY,dx:0,on:false,id:pid(c)};},{passive:true});
  const pid=c=>c.dataset.id||((c.querySelector('[data-id]')||{}).dataset||{}).id;
  document.addEventListener('pointermove',e=>{if(!st)return;const dx=e.clientX-st.x,dy=e.clientY-st.y;if(!st.on){if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)){st=null;return;}if(dx>10&&Math.abs(dx)>Math.abs(dy)){st.on=true;st.c.classList.add('swiping');}}
    if(st&&st.on){st.dx=Math.max(0,dx);st.c.style.transform=`translateX(${st.dx}px)`;st.c.style.setProperty('--sw',Math.min(1,st.dx/90));}},{passive:true});
  const end=()=>{if(!st)return;const s=st;st=null;if(!s.on)return;s.c.classList.remove('swiping');S.pSwiped=Date.now();
    if(s.dx>90){const r=PIPE.rows.find(x=>x.id===s.id);const i=r?PIPE_STAGES.findIndex(t=>t.id===r.stage):-1;const nx=PIPE_STAGES[i+1];if(nx){s.c.style.transition='transform .22s ease-in,opacity .22s';s.c.style.transform='translateX(110%)';s.c.style.opacity='0';setTimeout(()=>pMove(r.id,nx.id),200);return;}}
    s.c.style.transition='transform .25s cubic-bezier(.3,1.4,.5,1)';s.c.style.transform='';setTimeout(()=>{s.c.style.transition='';},260);};
  document.addEventListener('pointerup',end);document.addEventListener('pointercancel',end);
  // a swipe shouldn't also count as a tap that opens the card
  document.addEventListener('click',e=>{if(S.pSwiped&&Date.now()-S.pSwiped<350&&e.target.closest('.pCard')){e.stopPropagation();e.preventDefault();}},true);})();

/* ---------- after each render: place the pill, re-apply search ---------- */
{const _dv=decorateView;decorateView=function(){_dv.apply(this,arguments);try{if(S.screen==='pipeline'){document.querySelectorAll('.pillNav').forEach(pillPlace);pApplySearch();const on=$('.pStage.on');if(on&&on.scrollIntoView&&!S.pStripKept){on.scrollIntoView({block:'nearest',inline:'center'});}}}catch(e){console.warn(e);}};}

/* ---------- way in: a banner at the top of More ---------- */
{const _mP=SCREENS.more;SCREENS.more=function(){pipeStart();const h=_mP.apply(this,arguments);const act=PIPE.rows.filter(r=>PIPE_STAGES.some(s=>s.id===r.stage)&&r.stage!=='client').length;const chk=PIPE.rows.filter(r=>r.review).length;const due=PIPE.ready?pDueN():0;
  const ban=`<a class="card pBanner" href="#pipeline"><span class="pBanIco"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h4v14H3zm7 0h4v9h-4zm7 0h4v5h-4z"/></svg></span><span class="grow"><b>Pipeline</b><small>${PIPE.ready?`${act} active prospects${due?` \u00b7 ${due} due`:''}${chk?` \u00b7 ${chk} to check`:''}`:'Your prospects, clients and follow-ups'}</small></span><span class="chev">\u203a</span></a>`;
  return h.replace('<div class="pad">','<div class="pad">'+ban);};}
HELP.push(['Pipeline','More, then Pipeline, is your client pipeline: every prospect from first video to signed client, shared between you both and saved straight away. Tap + New and paste a website or Instagram link to add someone. Swipe a card right (or tap \u203a) to move it to the next stage, or tap it to edit everything: contact, products, links to the Loom video and quote, money, dates and notes. Each card keeps a history of who changed what. Not now asks when to bring them back.']);

/* ============================== 22 Nov: the client pipeline (part 2) ==============================
   Overview, Schedule and Growth tabs, a daily reminder, the Harbour button, and stage moves that count in the game.
   Moving a card to Video made, Talking, Meeting or Client offers a one-tap "Count it" in the toast, so nothing is
   logged twice by accident. Caps, cooldowns and the crew check still apply, because it goes through the normal buttons. */
const P_GAME={video_made:'v',talking:'r',meeting:'m',client:'c'};
const P_IDX=Object.fromEntries(PIPE_STAGES.map((s,i)=>[s.id,i]));
const pNth=n=>n+(n%100>=11&&n%100<=13?'th':['th','st','nd','rd'][n%10]||'th');
const pAgo=at=>{const m=Math.max(0,Math.round((Date.now()-Date.parse(at))/60000));return m<1?'just now':m<60?`${m} min ago`:m<1440?`${Math.round(m/60)} h ago`:m<2880?'yesterday':`${Math.round(m/1440)} days ago`;};
const pRnd=a=>a[Math.floor(Math.random()*a.length)];
function pOwnSeg(){const ow=S.view.powner||'all';return `<div class="seg mini pOwn">${[['all','Everyone'],['sam',pnameRaw('sam')],['james',pnameRaw('james')]].map(([k,n])=>`<button class="${ow===k?'on':''}" data-act="pOwner" data-o="${k}">${esc(n)}</button>`).join('')}</div>`;}
// how far a prospect has ever got (exits keep the credit for what happened before they left)
function pReach(r){let i=r.stage in P_IDX?P_IDX[r.stage]:(r.follow_ups?P_IDX.followed_up:P_IDX.messaged);if(r.meeting_held)i=Math.max(i,P_IDX.meeting);if(r.quote_url)i=Math.max(i,P_IDX.quote_sent);if(r.stage==='video_needed'||r.stage==='video_made')i=P_IDX[r.stage];return i;}

/* ---------- everyone's recent activity (for Overview and Growth) ---------- */
function pEvStart(){if(PIPE.allEv||PIPE.evLoading)return;PIPE.evLoading=true;
  if(PIPE.src==='supa'){S.sb.from('hl_prospect_events').select('prospect_id,by,kind,detail,at').neq('kind','import').gte('at',new Date(Date.now()-70*864e5).toISOString()).order('at',{ascending:false}).limit(2000)
      .then(({data})=>{PIPE.allEv=data||[];PIPE.evLoading=false;pipeRefresh();},()=>{PIPE.allEv=[];PIPE.evLoading=false;});
    try{S.sb.channel('hl-pipe-ev').on('postgres_changes',{event:'INSERT',schema:'public',table:'hl_prospect_events'},p=>{const e=p.new;if(!e||e.by===S.me||!PIPE.allEv)return;PIPE.allEv.unshift(e);(PIPE.ev[e.prospect_id]||[]).unshift(e);pipeRefresh();}).subscribe();}catch(e){}}
  else{const a=[];try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith('hl_pipe_ev_'))a.push(...JSON.parse(localStorage.getItem(k)||'[]'));}}catch(e){}
    a.sort((x,y)=>x.at<y.at?1:-1);PIPE.allEv=a;PIPE.evLoading=false;}}
function pActText(e){const r=PIPE.rows.find(x=>x.id===e.prospect_id);const b=`<b>${esc(r?r.business:'a prospect')}</b>`;const d=e.detail||{};const sn=id=>esc((PIPE_BY[id]||{}).name||id||'');
  if(e.kind==='stage')return d.undo?`moved ${b} back to ${sn(d.to)}`:`moved ${b} to ${sn(d.to)}`;if(e.kind==='created')return `added ${b}`;if(e.kind==='followup')return `followed up with ${b}`;if(e.kind==='held')return `had the meeting with ${b}`;
  if(e.kind==='snooze')return `pushed ${b} back to ${pShortD(d.to)}`;if(e.kind==='game')return `counted ${b} in the game`;if(e.kind==='checked')return `checked ${b}`;if(e.kind==='touch')return `caught up with ${b}`;return `edited ${b}`;}
{const _pe=pEvText;pEvText=function(e){const d=e.detail||{};if(e.kind==='followup')return `logged a follow-up (${pNth(d.n||1)})`;if(e.kind==='held')return 'marked the meeting as held';if(e.kind==='snooze')return `pushed it back to ${pShortD(d.to)}`;if(e.kind==='game')return `counted it in the game (${(KINDS[d.k]||{}).name||d.k})`;if(e.kind==='touch')return 'caught up with them';return _pe.apply(this,arguments);};}

/* ---------- what's due, and the one-tap "done" for each kind ---------- */
function pSchedItems(rows){return (rows||PIPE.rows).map(r=>{const d=pDue(r);if(!d)return null;let what,done;
    if(r.stage==='not_now'){what='Bring them back';done='Message';}
    else if(r.stage==='meeting'){if(r.meeting_at&&!r.meeting_held){what=d.cls==='later'||d.cls==='today'?'Meeting':'Meeting: did it happen?';done='Held';}else{what='Follow up after the meeting';done='Done';}}
    else if(r.stage==='messaged'){what='1st follow-up';done='Followed up';}
    else if(r.stage==='followed_up'){what=`${pNth((r.follow_ups||1)+1)} follow-up`;done='Followed up';}
    else if(r.stage==='talking'){what='Keep the chat warm';done='Caught up';}
    else if(r.stage==='quote_sent'){what='Chase the quote';done='Chased';}
    else{what='Follow up';done='Done';}
    return {r,d:d.d,cls:d.cls,what,done};}).filter(Boolean).sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:(b.r.priority?1:0)-(a.r.priority?1:0));}
function pSchedRow(x,opts){const r=x.r;const st=PIPE_BY[r.stage]||PIPE_STAGES[0];const dd=new Date(x.d+'T12:00:00Z');
  return `<div class="pSched ${x.cls}" style="--sc:${st.col}"><span class="pDay"><b>${dd.getUTCDate()}</b><small>${dd.toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'})}</small></span>
    <div class="grow" data-act="pOpen" data-id="${r.id}"><b>${esc(r.business||'Unnamed')}</b><small>${esc(x.what)} \u00b7 ${esc(st.name)}${r.contact?' \u00b7 '+esc(r.contact):''}</small></div>
    <div class="pSchBtns">${x.cls==='stale'?`<button class="btn sm ghost" data-act="pQuiet" data-id="${r.id}" title="Move to No response">Let go</button>`:''}<button class="btn sm primary" data-act="pDone" data-id="${r.id}">${esc(x.done)}</button>${r.stage==='meeting'&&r.meeting_at&&!r.meeting_held?'':`<button class="btn sm ghost pSnz" data-act="pSnooze" data-id="${r.id}" data-n="3" title="Push back 3 days" aria-label="Push back 3 days">+3d</button>`}</div></div>`;}
ACT.pDone=async(d,el)=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;const t=G.today;const row=el&&el.closest('.pSched');if(row)row.classList.add('ticked');
  const later=fn=>setTimeout(fn,row&&!matchMedia('(prefers-reduced-motion: reduce)').matches?320:0);
  later(async()=>{
    if(r.stage==='not_now')return pMove(r.id,'messaged');
    if(r.stage==='messaged')return pMove(r.id,'followed_up');
    let patch,kind,det,msg;
    if(r.stage==='followed_up'){const n=(r.follow_ups||1)+1;patch={follow_ups:n,last_contact:t,next_due:addDays(t,5)};kind='followup';det={n};msg=`${pNth(n)} follow-up logged. Next nudge ${pShortD(addDays(t,5))}.`;}
    else if(r.stage==='meeting'&&r.meeting_at&&!r.meeting_held){patch={meeting_held:true,last_contact:t,next_due:addDays(t,2)};kind='held';msg=`Meeting marked as held. A follow-up is due ${pShortD(addDays(t,2))}.`;}
    else{const g=P_GAP[r.stage]||5;patch={last_contact:t,next_due:addDays(t,g)};kind='touch';msg=`Done. Next one ${pShortD(addDays(t,g))}.`;}
    const prev=await pipePatch(r.id,patch,kind,det);if(prev===false)return;PIPE.undoP={id:r.id,prev};try{SND.pop&&SND.pop();}catch(e){}
    toast(`<b>${esc(r.business)}</b>: ${msg} <button class="tLink" data-act="pUndoP">Undo</button>`,'',5000);});};
ACT.pSnooze=async d=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;const to=addDays(G.today,+d.n||3);const patch=r.stage==='not_now'?{return_on:to}:{next_due:to};
  const prev=await pipePatch(r.id,patch,'snooze',{to});if(prev===false)return;PIPE.undoP={id:r.id,prev};toast(`<b>${esc(r.business)}</b> pushed back to ${pShortD(to)}. <button class="tLink" data-act="pUndoP">Undo</button>`,'',4500);};
ACT.pQuiet=d=>pMove(d.id,'no_response');
ACT.pUndoP=async()=>{const u=PIPE.undoP;if(!u)return;PIPE.undoP=null;await pipePatch(u.id,u.prev,'edit',{fields:['undo']});};
ACT.pGoStage=d=>{S.view.ptab='board';S.view.pstage=d.s;S.view.pq='';render();};
ACT.pGoSched=()=>{document.querySelectorAll('.toast').forEach(t=>{if(t.querySelector('[data-act=pGoSched]'))t.remove();});S.view.ptab='schedule';if(location.hash!=='#pipeline')location.hash='#pipeline';else render();};
ACT.pSchDay=d=>{const g=document.getElementById('psd-'+d.d)||document.getElementById('psg-'+d.g);if(g)g.scrollIntoView({block:'start',behavior:'smooth'});};

/* ---------- Overview ---------- */
function pOverviewHtml(){pEvStart();const rows=pFilter(PIPE.rows);const act=rows.filter(r=>r.stage in P_IDX&&r.stage!=='client');const cl=rows.filter(r=>r.stage==='client');
  const items=pSchedItems(rows);const now=items.filter(x=>x.cls==='over'||x.cls==='today');const val=act.reduce((a,r)=>a+(pVal(r)||0),0);
  const reached=rows.filter(r=>pReach(r)>=P_IDX.messaged).length;const win=reached?Math.round(cl.length/reached*100):0;
  const counts=PIPE_STAGES.map(s=>rows.filter(r=>r.stage===s.id).length);const mx=Math.max(1,...counts);
  const prod={};act.forEach(r=>(r.products||[]).forEach(p=>prod[p]=(prod[p]||0)+1));const pr=Object.entries(prod).sort((a,b)=>b[1]-a[1]);const pmx=Math.max(1,...pr.map(x=>x[1]));
  const ev=(PIPE.allEv||[]).filter(e=>(S.view.powner||'all')==='all'||e.by===S.view.powner).slice(0,8);
  return `<div class="pTools pOvTools"><span class="grow tiny muted">${rows.length} prospects${(S.view.powner||'all')!=='all'?` owned by ${esc(pnameRaw(S.view.powner))}`:''}</span>${pOwnSeg()}</div>
   <div class="pKpis">
     <button class="pKpi" data-act="pTab" data-t="board"><b class="num">${act.length}</b><small>active</small></button>
     <button class="pKpi ${now.length?'hot':''}" data-act="pTab" data-t="schedule"><b class="num">${now.length}</b><small>due now</small></button>
     ${val?`<button class="pKpi" data-act="pTab" data-t="board"><b class="num">${pMoney(val)}</b><small>quoted, open</small></button>`:`<button class="pKpi" data-act="pTab" data-t="clients"><b class="num">${pMoney(cl.filter(r=>r.deal_period==='monthly').reduce((a,r)=>a+(+r.deal_value||0),0))}</b><small>a month</small></button>`}
     <button class="pKpi" data-act="pTab" data-t="growth"><b class="num">${win}%</b><small>win rate</small></button></div>
   <div class="card pOvCard"><div class="row between"><h3>Today's jobs</h3>${now.length>4?`<button class="btn sm ghost" data-act="pTab" data-t="schedule">All ${now.length} \u203a</button>`:''}</div>
     ${now.length?`<div class="pSchList">${now.slice(0,4).map(x=>pSchedRow(x)).join('')}</div>`:`<p class="pNone">${pRnd(['Nothing due. Gary is suspicious.','All caught up. Treat yourself to a biscuit.','Clear decks, captain. Go and find new prospects.'])}</p>`}</div>
   <div class="card pOvCard"><h3>The pipeline</h3><p class="tiny muted" style="margin:2px 0 8px">Tap a stage to open it on the Board.</p>
     <div class="pFunnel">${PIPE_STAGES.map((s,i)=>`<button class="pFRow" data-act="pGoStage" data-s="${s.id}" style="--sc:${s.col};--w:${Math.max(counts[i]?4:0,counts[i]/mx*100)}%;--d:${i*40}ms"><span class="pFName">${esc(s.name)}</span><span class="pFBar"><i></i></span><b class="num">${counts[i]}</b></button>`).join('')}</div></div>
   ${pr.length?`<div class="card pOvCard"><h3>What they want</h3><div class="pFunnel">${pr.map(([p,n],i)=>`<div class="pFRow still" style="--sc:#3E8DDB;--w:${n/pmx*100}%;--d:${i*40}ms"><span class="pFName">${esc(p==='Social Media Management'?'Social media':p)}</span><span class="pFBar"><i></i></span><b class="num">${n}</b></div>`).join('')}</div></div>`:''}
   <div class="card pOvCard"><h3>Recent moves</h3>${!PIPE.allEv?'<p class="pNone">Loading\u2026</p>':ev.length?`<div class="pAct">${ev.map(e=>`<div class="pActRow"><img alt="" src="${pAvatar(e.by)}"><span class="grow">${esc(pnameRaw(e.by))} ${pActText(e)}</span><small>${pAgo(e.at)}</small></div>`).join('')}</div>`:'<p class="pNone">No moves yet. The first swipe is the hardest.</p>'}</div>`;}

/* ---------- Schedule ---------- */
function pScheduleHtml(){const t=G.today;const items=pSchedItems(pFilter(PIPE.rows));const wk=[...Array(7)].map((_,i)=>addDays(t,i));
  const grp=[['over','Overdue',x=>x.cls==='over'],['today','Today',x=>x.cls==='today'],['tom','Tomorrow',x=>x.d===addDays(t,1)],['week','This week',x=>x.d>addDays(t,1)&&x.d<=addDays(t,6)],['later','Later',x=>x.d>addDays(t,6)]];
  const stale=items.filter(x=>x.cls==='stale');const cnt=d=>items.filter(x=>x.d===d).length;const ovN=items.filter(x=>x.cls==='over').length;
  const strip=`<div class="pWeek">${wk.map((d,i)=>{const n=cnt(d)+(i===0?ovN:0);const dd=new Date(d+'T12:00:00Z');return `<button class="pWDay ${i===0?'today':''} ${n?'has':''}" data-act="pSchDay" data-d="${d}" data-g="${i===0?(ovN?'over':'today'):i===1?'tom':'week'}"><small>${i===0?'Today':DAYN[dd.getUTCDay()]}</small><b>${dd.getUTCDate()}</b><i>${n?n:''}</i></button>`;}).join('')}</div>`;
  let used=new Set();const out=grp.map(([k,n,f])=>{const xs=items.filter(x=>!used.has(x)&&x.cls!=='stale'&&f(x));xs.forEach(x=>used.add(x));if(!xs.length)return '';const shown=k==='later'?xs.slice(0,25):xs;
    return `<section class="pSGroup ${k}" id="psg-${k}"><h4>${n} <span>${xs.length}</span></h4><div class="pSchList">${shown.map(x=>`<div id="psd-${x.d}" class="pSAnchor"></div>`+pSchedRow(x)).join('').replace(/<div id="psd-([\d-]+)" class="pSAnchor"><\/div>/g,(m,d,o,str)=>str.indexOf(`psd-${d}"`)<o?'':m)}${k==='later'&&xs.length>25?`<p class="pHint">${xs.length-25} more after these.</p>`:''}</div></section>`;}).join('');
  return `<div class="pTools"><span class="grow tiny muted">Follow-ups, meetings and comebacks, soonest first.</span>${pOwnSeg()}</div>${strip}
   ${out||`<div class="card"><p class="pNone">${pRnd(['Nothing scheduled. The calendar is so empty it echoes.','No follow-ups due. Either you are brilliant or something is wrong. We choose brilliant.'])}</p></div>`}
   ${stale.length?`<details class="card pStale"><summary><b>Gone quiet</b> <span class="tiny muted">${stale.length} with no contact for over a month</span></summary><p class="tiny muted" style="margin:6px 0 8px">Give them one last nudge, push them back, or let them go to No response. No hard feelings. Some hard feelings.</p><div class="pSchList">${stale.map(x=>pSchedRow(x)).join('')}</div></details>`:''}`;}

/* ---------- Growth ---------- */
const pGoal=()=>{try{return +localStorage.getItem('hl_pipe_goal')||2000;}catch(e){return 2000;}};
ACT.pGoal=()=>{openModal(`<h2>Monthly retainer goal</h2><p class="muted" style="margin:2px 0 10px">What you want coming in each month from retainers. Only saved on this device.</p><label class="f">Goal (\u00a3 a month)<input id="pGoalIn" type="number" min="100" step="50" value="${pGoal()}"></label><div class="row" style="justify-content:flex-end;gap:8px;margin-top:12px"><button class="btn ghost" data-act="wnClose">Cancel</button><button class="btn primary" data-act="pGoalGo">Save</button></div>`);setTimeout(()=>{const i=$('#pGoalIn');i&&i.select();},40);};
ACT.pGoalGo=()=>{const v=Math.max(100,Math.round(+(($('#pGoalIn')||{}).value)||0));try{localStorage.setItem('hl_pipe_goal',String(v));}catch(e){}closeModal();render();};
function pGrowthHtml(){pEvStart();const rows=pFilter(PIPE.rows);const t=G.today;const cl=rows.filter(r=>r.stage==='client');const mon=cl.filter(r=>r.deal_period==='monthly');
  const mrr=mon.reduce((a,r)=>a+(+r.deal_value||0),0);const goal=pGoal();const avg=mon.length?mrr/mon.length:275;const left=Math.max(0,goal-mrr);const pct=Math.min(100,Math.round(mrr/goal*100));
  // how far prospects get
  const reach=PIPE_STAGES.map((s,i)=>rows.filter(r=>pReach(r)>=i).length);const rmx=Math.max(1,reach[0]);
  // the last 8 weeks of moves, by captain
  const ws0=weekStart(t);const weeks=[...Array(8)].map((_,i)=>addDays(ws0,-7*(7-i)));const ev=(PIPE.allEv||[]).filter(e=>e.kind!=='checked'&&e.kind!=='edit'&&e.kind!=='import');
  const wk=weeks.map(w=>{const e=addDays(w,7);const o={w,sam:0,james:0};ev.forEach(x=>{const d=L(Date.parse(x.at)).date;if(d>=w&&d<e&&(x.by==='sam'||x.by==='james'))o[x.by]++;});return o;});const wmx=Math.max(1,...wk.map(o=>o.sam+o.james));
  // clients won by month
  const months=[...Array(6)].map((_,i)=>{const d=new Date(t+'T12:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-(5-i));return d.toISOString().slice(0,7);});
  const won=months.map(m=>cl.filter(r=>(r.won_at||'').slice(0,7)===m).length);const before=cl.filter(r=>!r.won_at||r.won_at.slice(0,7)<months[0]).length;const cmx=Math.max(1,before,...won);
  return `<div class="pTools"><span class="grow tiny muted">How the pipeline is growing.</span>${pOwnSeg()}</div>
   <div class="card pGoalCard"><div class="row between"><h3>Retainer goal</h3><button class="btn sm ghost" data-act="pGoal">Change</button></div>
     <div class="pGoalNums"><b class="num">${pMoney(mrr)}</b><small>of ${pMoney(goal)} a month</small></div>
     <div class="pGoalBar" style="--p:${pct}%"><i></i><span>${pct}%</span></div>
     <p class="tiny muted" style="margin:8px 0 0">${left?`${pMoney(left)} to go. That's about ${Math.ceil(left/avg)} more retainer${Math.ceil(left/avg)===1?'':'s'} at your average of ${pMoney(avg)}.`:'Goal smashed. Time to raise it, you magnificent sea dogs.'}</p></div>
   <div class="card pOvCard"><h3>How far prospects get</h3><p class="tiny muted" style="margin:2px 0 8px">Everyone who has ever reached each stage, and how many make the next step.</p>
     <div class="pReach">${PIPE_STAGES.map((s,i)=>`${i?`<div class="pConv">${reach[i-1]?Math.round(reach[i]/reach[i-1]*100):0}% go on</div>`:''}<div class="pFRow still" style="--sc:${s.col};--w:${Math.max(reach[i]?3:0,reach[i]/rmx*100)}%;--d:${i*45}ms"><span class="pFName">${esc(s.name)}</span><span class="pFBar"><i></i></span><b class="num">${reach[i]}</b></div>`).join('')}</div></div>
   <div class="card pOvCard"><div class="row between"><h3>Moves per week</h3><span class="pLegend"><i style="--c:${pcol('sam')}"></i>${esc(pnameRaw('sam'))} <i style="--c:${pcol('james')}"></i>${esc(pnameRaw('james'))}</span></div>
     ${!PIPE.allEv?'<p class="pNone">Loading\u2026</p>':`<div class="pCols">${wk.map((o,i)=>`<div class="pColW" style="--d:${i*40}ms"><div class="pColStack" title="${o.sam+o.james} moves"><i style="--h:${o.james/wmx*100}%;--c:${pcol('james')}"></i><i style="--h:${o.sam/wmx*100}%;--c:${pcol('sam')}"></i></div><b class="num">${o.sam+o.james||''}</b><small>${pShortD(o.w).replace(' ','\u00a0')}</small></div>`).join('')}</div><p class="tiny muted" style="margin:6px 0 0">Adds, stage moves, follow-ups and meetings. Counting started with the pipeline, so the early weeks are empty.</p>`}</div>
   <div class="card pOvCard"><h3>Clients won</h3><div class="pCols">${[['Before',before],...months.map((m,i)=>[new Date(m+'-15T12:00:00Z').toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'}),won[i]])].map(([n,v],i)=>`<div class="pColW" style="--d:${i*40}ms"><div class="pColStack"><i style="--h:${v/cmx*100}%;--c:${PIPE_BY.client.col}"></i></div><b class="num">${v||''}</b><small>${n}</small></div>`).join('')}</div></div>`;}

/* ---------- moves that count in the game ---------- */
ACT.pGame=d=>{const r=PIPE.rows.find(x=>x.id===d.id);if(!r)return;const k=d.k;document.querySelectorAll('.toast').forEach(t=>{if(t.querySelector('[data-act=pGame]'))t.remove();});
  const who=(r.insta?'@'+r.insta:r.business||'').slice(0,60);
  if(k==='m'||k==='c'){S.pGame={k,id:r.id};openMCSheet(k);setTimeout(()=>{const i=$('#prIn');if(i&&!i.value){i.value=who;i.dispatchEvent(new Event('input',{bubbles:true}));}},90);return;}
  const t0=Date.now();const btn=document.querySelector(`.act[data-k="${k}"]`)||document.createElement('button');logAction(k,btn);
  if(Object.values(S.pending||{}).some(x=>x.k===k&&x.pid===S.me&&x.t>=t0))pGameMark(r,k);};
function pGameMark(r,k){pipePatch(r.id,{tags:[...(r.tags||[]).filter(x=>x!=='game:'+k),'game:'+k]},'game',{k});}
{const _smc=submitMC;submitMC=async function(k,pr){const g=S.pGame;S.pGame=null;const t0=Date.now();const out=await _smc.apply(this,arguments);
  try{if(g&&g.k===k){const ok=Object.values(S.pending||{}).some(x=>x.k===k&&x.pid===S.me&&x.t>=t0)||((G&&G.mc)||[]).some(e=>e.k===k&&e.pid===S.me&&e.t>=t0);const r=PIPE.rows.find(x=>x.id===g.id);if(ok&&r)pGameMark(r,k);}}catch(e){}return out;};}

/* ---------- the daily nudge, once a day on the Harbour ---------- */
const P_REM_QUIPS=['Gary has started pecking the calendar.','The follow-ups will not send themselves. We asked them nicely.','A prospect left on read is a prospect left at sea.','Fortune favours the captain who nudges.','Even the kraken replies eventually. Usually.','Barnaby says the ink is drying on these.'];
function pRemind(){try{if(!PIPE.ready||!S.me||!G||S.screen!=='harbour')return;const k='hl_pipe_rem_'+S.me;if(localStorage.getItem(k)===G.today)return;
  const it=pSchedItems(PIPE.rows).filter(x=>x.cls==='over'||x.cls==='today');if(!it.length)return;localStorage.setItem(k,G.today);const mine=it.filter(x=>x.r.owner===S.me).length;
  const meet=it.filter(x=>x.r.stage==='meeting'&&x.d===G.today).length;
  toast(`<b>${it.length} in the pipeline need${it.length===1?'s':''} you today</b>${mine&&mine<it.length?` (${mine} yours)`:''}${meet?`, including ${meet} meeting${meet===1?'':'s'}`:''}. ${pRnd(P_REM_QUIPS)} <button class="tLink" data-act="pGoSched">Open the schedule</button>`,'',9000);}catch(e){}}
{const _pr=pipeRefresh;pipeRefresh=function(){_pr.apply(this,arguments);if(S.screen==='harbour')setTimeout(pRemind,400);};}

/* ---------- the Harbour button ---------- */
{const _hP=SCREENS.harbour;SCREENS.harbour=function(){const h=_hP.apply(this,arguments);try{pipeStart();}catch(e){}const due=PIPE.ready?pDueN():0;const act=PIPE.rows.filter(r=>r.stage in P_IDX&&r.stage!=='client').length;
  const btn=`<a class="tvGo pGoBtn" href="#pipeline"><span class="appIco" style="background:#2C3E50"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h4v14H3zm7 0h4v9h-4zm7 0h4v5h-4z"/></svg></span><span class="grow"><b>Pipeline</b><small>${PIPE.ready?`${act} active${due?` \u00b7 <b class="pGoDue">${due} due</b>`:' \u00b7 all caught up'}`:'Prospects, follow-ups and clients'}</small></span>${due?`<span class="pGoBadge">${due}</span>`:''}<span class="tvGoArrow">\u203a</span></a>`;
  const L='<a class="tvGo" href="#tavern">';return h.includes(L)?h.replace(L,btn+L):h.replace('<div class="pad">','<div class="pad">'+btn);};}

/* ---------- after each render ---------- */
{const _dv=decorateView;decorateView=function(){_dv.apply(this,arguments);try{if(S.screen==='harbour')setTimeout(pRemind,600);if(S.screen==='pipeline'){const on=$('#pTabs button.on');if(on&&on.scrollIntoView)on.scrollIntoView({block:'nearest',inline:'nearest'});}}catch(e){}};}
HELP.push(['Pipeline: Overview, Schedule, Growth','Overview shows today\'s jobs, how many prospects sit in each stage, what they want and the latest moves by either of you. Schedule lists every follow-up, meeting and comeback by date. Tap the main button when it\'s done (it logs the follow-up and sets the next one) or +3d to push it back. Prospects with no contact for over a month sit under Gone quiet. Growth tracks your retainer goal, how far prospects get, and moves and wins over time. Moving a card to Video made, Talking, Meeting or Client offers "Count it" in the message, which logs the matching Video, Response, Meeting or Client in the game, once per prospect. You get one reminder a day on the Harbour when anything is due.']);

