// shop DM celebrations and records slot into the same lists as the level ones (run once levels.js has set those lists up)
function s7Register(){
S7.filter(i=>i.cat==='dmfx').forEach(i=>{LVX[i.id]={id:i.id,kind:'fx',name:i.name,shape:i.shape,cols:i.cols,shop:true,t:1};});
S7.filter(i=>i.cat==='record').forEach((i,k)=>{const src=SONG_BY[`lv_rec_${(k%10)+1}_${(k*3)%10}`]||Object.values(SONG_BY).find(s=>s.lvrec);const u=x=>h32(i.id+x)/4294967296;
  const sh=Math.floor(u('t')*5)-2;const notes=src.notes.split(' ').map(t=>{const m=/^([A-G]#?)(\d):(\d+)$/.exec(t);if(!m)return t;const NN=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];let ix=NN.indexOf(m[1])+sh,o=+m[2];while(ix<0){ix+=12;o--;}while(ix>11){ix-=12;o++;}return NN[ix]+o+':'+m[3];}).join(' ');
  const s={id:'sr_'+i.id,name:i.name,bpm:[132,96,140,150,84,72,128,144,160,110][k],notes,lvrec:i.id};SONG_BY[s.id]=s;LVX[i.id]={id:i.id,kind:'rec',name:i.name,song:s.id,shop:true,t:1};});

}

