function s7Sparkle(c,cx,cy,r,t,set){const cols=set.sparkle||['#FFE38A','#FFFFFF'];for(let i=0;i<5;i++){const a=t/1400+i*1.26;const tw=(Math.sin(t/260+i*2.1)+1)/2;if(tw<.35)continue;const px=cx+Math.cos(a)*r,py=cy+Math.sin(a*1.3)*r*.8;c.fillStyle=cols[i%cols.length];c.globalAlpha=tw;c.beginPath();for(let k=0;k<8;k++){const an=k/8*TAU,rr2=(k%2?.18:.7)*(.6+tw*.5)*(r/7);c.lineTo(px+Math.cos(an)*rr2,py+Math.sin(an)*rr2);}c.fill();}c.globalAlpha=1;}

